static string secFingerprint(const string& path) {
    std::ifstream in(fs::u8path(path), std::ios::binary);
    if (!in) return "";
    uint64_t h = 1469598103934665603ULL;
    char buf[65536];
    while (in) {
        in.read(buf, sizeof(buf));
        std::streamsize n = in.gcount();
        for (std::streamsize i = 0; i < n; ++i) {
            h ^= (unsigned char)buf[i];
            h *= 1099511628211ULL;
        }
    }
    std::ostringstream ss;
    ss << std::hex << h;
    return ss.str();
}
static bool secOfficialPath(const string& path) {
    std::error_code ec;
    string app = fs::current_path(ec).u8string();
    string full = fs::weakly_canonical(fs::u8path(path), ec).u8string();
    return !app.empty() && full.rfind(app, 0) == 0;
}
static std::vector<std::pair<int, std::string>> secScanSource(const string& src) {
    static const std::vector<std::pair<std::string, std::string>> rules = {
        {"二进制破坏", "危险操作"}, {"危险模式", "权限提升"},
        {"申请管理员", "权限提升"}, {"调用外部", "外部执行"},
        {"删除文件", "文件破坏"}, {"写二进制", "文件写入"},
        {"下载", "网络写入"}, {"执行字节码", "动态执行"},
        {"网络反流", "防火墙修改"}};
    std::vector<std::pair<int, std::string>> out;
    int n = 0;
    for (const auto& raw : splitLines(src)) {
        ++n;
        size_t cb = raw.find_first_not_of(" \t");
        if (cb != string::npos && raw[cb] == '#') continue;
        for (const auto& r : rules)
            if (raw.find(r.first) != std::string::npos)
                out.push_back({n, r.second + "：" + r.first});
    }
    return out;
}
static std::string secDeclaredLabel(const string& src, string& label) {
    for (const auto& raw : splitLines(src)) {
        size_t b = raw.find_first_not_of(" \t");
        if (b == string::npos) continue;
        string s = raw.substr(b);
        if (s.rfind("# 官方标签:", 0) != 0) continue;
        std::istringstream ss(s.substr(7));
        string name, hash;
        ss >> name >> hash;
        label = name;
        return hash;
    }
    return "";
}
static string readWholeFile(const string& path);
static string resolveWenPath(const string& path);
static void probeExternal(const string& path, int line) {
    if (!gProbeActive) return;
    gProbeTarget = fs::absolute(fs::u8path(path)).u8string();
    gProbeStatus = "扫描中";
    string src;
    try { src = readWholeFile(resolveWenPath(path)); }
    catch (...) { gProbeStatus = "无法读取"; return; }
    auto issues = secScanSource(src);
    gProbeStatus = issues.empty() ? "已放行" : "发现可疑";
    if (!issues.empty() && gSecurityPolicy == "拒绝")
        throw WenError("安全权限", line, 0, "探针拒绝启动：" + path);
}
static SecEntry& secCheckFile(const string& path) {
    std::error_code ec;
    string full = fs::weakly_canonical(fs::u8path(path), ec).u8string();
    if (full.empty()) full = path;
    string fp = secFingerprint(full);
    for (auto& e : gSecEntries)
        if (e.file == full && e.fingerprint == fp) return e;
    SecEntry e;
    e.file = full;
    e.fingerprint = fp;
    e.source = secOfficialPath(full) ? "官方目录" : "外部";
    e.status = e.source == "官方目录" ? "安全" : "密切";
    e.decision = "待定";
    gSecEntries.push_back(e);
    return gSecEntries.back();
}
