// 纯表达式 → 栈式字节码（数字/参数/四则/比较/且或），失败返回 false
static bool compilePureExpr(const ExprPtr& e, const std::vector<SymId>& ps,
                            std::vector<int>& ops, std::vector<double>& vals) {
    if (!e) return false;
    if (e->k == Expr::K::Num) { ops.push_back(1); vals.push_back(e->num); return true; }
    if (e->k == Expr::K::Var) {
        for (size_t i = 0; i < ps.size(); ++i)
            if (ps[i] == e->sym) { ops.push_back(2); vals.push_back((double)i); return true; }
        return false;
    }
    if (e->k == Expr::K::Unary && e->args.size() == 1) {
        if (!compilePureExpr(e->args[0], ps, ops, vals)) return false;
        if (e->op == "-") { ops.push_back(16); vals.push_back(0); return true; }
        if (e->op == "非") { ops.push_back(17); vals.push_back(0); return true; }
        return false;
    }
    if (e->k == Expr::K::Binary && e->args.size() == 2) {
        if (!compilePureExpr(e->args[0], ps, ops, vals)) return false;
        if (!compilePureExpr(e->args[1], ps, ops, vals)) return false;
        const string& o = e->op;
        int code = 0;
        if (o == "+") code = 3;
        else if (o == "-") code = 4;
        else if (o == "*") code = 5;
        else if (o == "/") code = 6;
        else if (o == "%") code = 7;
        else if (o == "<") code = 8;
        else if (o == "<=") code = 9;
        else if (o == ">") code = 10;
        else if (o == ">=") code = 11;
        else if (o == "==") code = 12;
        else if (o == "!=") code = 13;
        else if (o == "且") code = 14;
        else if (o == "或") code = 15;
        if (!code) return false;
        ops.push_back(code); vals.push_back(0);
        return true;
    }
    return false;
}

class Interpreter {
public:
    shared_ptr<Scope> globals;
    // 「返回」不靠抛异常：设标志 + 值，逐层检查，省掉每次函数调用一次 throw/catch
    bool retFlag = false;
    Value retVal;
    std::mt19937 rng;
    string filename;
    vector<string> sourceLines;
    bool lastWasExpr = false;
    Value lastValue;
    std::set<string> loadedModules;
    std::map<string, string> symbolOwner;  // 名字 -> 库/用户，防止静默覆盖
    bool callStats = false;                // 调用统计：只在开启时计数
    int callDepth = 0;
    int maxCallDepth = 1000;
    bool adminGranted = false;             // 管理员权限
    bool dangerousMode = false;            // 危险模式：允许二进制破坏
    std::map<string, long long> callCounts;
    std::map<string, std::map<string, Value>> libraryFunctions;  // 库名 -> 函数表
    std::vector<Value> renderScene;  // 渲染场景：面/涂鸦/渐变/体积光，供各后端使用
    bool accelEnabled = false;       // 加速库：纯函数结果缓存开关
    std::unordered_map<string, Value> accelCache;
    long long accelHits = 0;
    std::unordered_map<string, Value> leapCache;  // 跃迁库：同键直接跳过计算
    bool leapAuto = false;               // 跃迁库：自动缓存用户函数
    long long leapHits = 0;
    long long leapMisses = 0;
    size_t leapLimit = 200000;
    std::map<string, Value> memoryStore;  // 内存库：常驻
    std::map<string, Value> memoryTemp;   // 内存库：临时
    std::map<string, string> memoryCompressed;  // 内存库：压缩区
    std::map<string, size_t> memoryOrigSize;    // 压缩前字节数
    std::map<string, string> decompressCache;    // 压缩文本 -> 解压结果

    size_t memoryUsageBytes() const {
        size_t bytes = 0;
        for (const auto& kv : memoryStore) bytes += toText(kv.second, true).size();
        for (const auto& kv : memoryTemp) bytes += toText(kv.second, true).size();
        for (const auto& kv : memoryCompressed) bytes += kv.second.size();
        return bytes;
    }
    void memoryPut(const string& key, bool temp, const Value& v, int line) {
        size_t need = toText(v, true).size();
        if (!temp) memoryStore.erase(key); else memoryTemp.erase(key);
        while (memoryUsageBytes() + need > gMemoryMaxBytes) {
            if (!memoryTemp.empty()) memoryTemp.erase(memoryTemp.begin());
            else if (!memoryCompressed.empty()) memoryCompressed.erase(memoryCompressed.begin());
            else if (!memoryStore.empty()) memoryStore.erase(memoryStore.begin());
            else break;
        }
        if (memoryUsageBytes() + need > gMemoryMaxBytes)
            throw WenError("运行时错误", line, 0, "内存超过上限；调大「内存上限」或清理键");
        if (temp) memoryTemp[key] = v; else memoryStore[key] = v;
    }
    std::vector<string> memoryDict;             // 符号字典
    std::map<string, int> memoryDictIndex;
    bool memoryAuto = false;             // 内存库：用户函数自动缓存
    bool memoryCompress = false;         // 内存库：新缓存直接压缩
    double memoryMinSavings = 0.0;       // 压缩阈值：至少省这么多才压
    std::set<string> memoryPullKeys;     // 牵引：精确键
    std::vector<string> memoryPullPrefixes;  // 牵引：前缀/范围
    bool memoryPullAll = false;          // 牵引：全部
    long long memoryHits = 0;
    long long memoryMisses = 0;
    std::map<string, std::deque<Value>> channels;
    std::deque<string> inputBuffer;
    bool inLibrary_ = false;
    std::set<string> moduleExports;
    std::vector<std::tuple<string, int, long long>> netHits;
    std::vector<std::pair<string, bool>> firewallRules;

    Interpreter();

    void 加载模块(const string& name, int line);
    void 加载外部库(const string& name, int line);
    bool 是内置库(const string& name) const;
    void registerBuiltin(const string& name, int minArgs, int maxArgs,
                         std::function<Value(Interpreter&, vector<Value>&, int)> fn);

    vector<StmtPtr> parseSource(const string& src);
    void scanPull(const string& src);
    bool isPulled(const string& key) const;
    string leapKey(const Value& key, int line);
    void buildMemoryDict(const string& extra = "");
    string compressMemoryText(const string& text);
    string decompressMemoryText(const string& text, int line);
    void run(const string& src, const string& name);
    void execProgram(const vector<StmtPtr>& program);
    void execProgram(const vector<StmtPtr>& program, const shared_ptr<Scope>& scope);
    void exec(const StmtPtr& s, const shared_ptr<Scope>& scope);
    Value eval(const ExprPtr& e, const shared_ptr<Scope>& scope);
    Value callValue(const Value& callee, vector<Value>& args, int line);
    void assignTarget(const ExprPtr& target, Value val, const shared_ptr<Scope>& scope);
    // AST 路径和字节码路径共用的「给变量赋值」语义（gslot < 0 的那一支）。
    void assignVarSym(SymId sym, Value val, const shared_ptr<Scope>& scope,
                       bool knownBuiltin = false);
    // 跑一段语句字节码；返回函数返回值（顶层循环返回 空）。
    Value runCode(const std::vector<Instr>& code, const std::vector<double>& kconst,
                  const std::vector<StmtPtr>& slow, int vstack, const shared_ptr<Scope>& scope);
    // 循环体块跑完时的控制码：0 正常 / 1 继续 / 2 中断
    int vmCtl = 0;
    // 这一段字节码有没有执行过「返回」（BC_RET）
    int vmRetFlag = 0;
    // 正在执行一条由字节码委派过来的语句：这时 exec 不要再试着把「当」编译一遍，
    // 否则 exec → 编译 → 委派 → exec 会无限递归。
    bool delegating = false;
    Value getIndex(const Value& obj, const Value& idx, int line);
    void setIndex(Value& obj, const Value& idx, const Value& val, int line);

    [[noreturn]] void rtError(int line, const string& msg) {
        throw WenError("运行时错误", line, 0, msg);
    }

    // 名字不存在：如果它属于某个还没「依赖」的库，给出依赖提示。
    [[noreturn]] void undefinedName(const string& name, int line) {
        for (const auto& kv : libraryFunctions) {
            if (kv.second.count(name))
                throw WenError("运行时错误", line, 0,
                               "「" + name + "」属于「" + kv.first +
                                   "」，请先在使用前写「依赖 " + kv.first + "」");
        }
        static const std::map<string, string> constLib = {
            {"圆周率", "数学库"}, {"π", "数学库"}, {"自然常数", "数学库"},
            {"重力加速度", "物理库"}, {"光速", "物理库"},
            {"万有引力常数", "物理库"}, {"声速", "物理库"}};
        auto ci = constLib.find(name);
        if (ci != constLib.end())
            throw WenError("运行时错误", line, 0,
                           "「" + name + "」属于「" + ci->second +
                               "」，请先在使用前写「依赖 " + ci->second + "」");
        string hint = nearestName(name);
        throw WenError("运行时错误", line, 0, "变量「" + name + "」还没有值" +
                       (hint.empty() ? "" : "；你是不是要找「" + hint + "」？"));
    }
};

// ============================================================
// 9. 解释器实现
// ============================================================

void Interpreter::registerBuiltin(
    const string& name, int minArgs, int maxArgs,
    std::function<Value(Interpreter&, vector<Value>&, int)> fn) {
    auto b = std::make_shared<Builtin>();
    b->name = name;
    b->minArgs = minArgs;
    b->maxArgs = maxArgs;
    b->fn = std::move(fn);
    globals->set(name, vFunc(b));
    gCallableNames.insert(name);
    gBuiltinArity[name] = {minArgs, maxArgs};
}

static void collectCallables(const vector<StmtPtr>&, std::set<string>&);
static void checkStmtStatic(const vector<StmtPtr>&, const std::set<string>&, vector<WenError>&);
static void collectStaticDefs(const vector<StmtPtr>&, std::set<string>&, std::map<string,int>&);
static void checkStmtNames(const vector<StmtPtr>&, const std::set<string>&,
                           const std::map<string,int>&, vector<WenError>&, bool);

vector<StmtPtr> Interpreter::parseSource(const string& src) {
    Lexer lex(src);
    auto toks = lex.scan();
    Parser p(std::move(toks));
    auto ast = p.parseProgram();
    std::set<string> callables = gCallableNames;
    collectCallables(ast, callables);
    vector<WenError> errs;
    checkStmtStatic(ast, callables, errs);
    if (!gNoNameCheck) {
        std::set<string> vars;
        std::map<string,int> funcs;
        collectStaticDefs(ast, vars, funcs);
        checkStmtNames(ast, vars, funcs, errs,
                       src.find("依赖") != string::npos || src.find("别名") != string::npos ||
                       src.find("后缀") != string::npos);
    }
    if (!errs.empty()) throw errs.front();
    return ast;
}

void Interpreter::scanPull(const string& src) {
    std::istringstream in(src);
    string line;
    while (std::getline(in, line)) {
        string t = trimText(line);
        if (t.empty() || t[0] != '#') continue;
        t = trimText(t.substr(1));
        if (t.rfind("牵引", 0) != 0) continue;
        t = trimText(t.substr(6));
        if (!t.empty() && (t[0] == ':' || startsWith(t, 0, "：")))
            t = trimText(t.substr(t[0] == ':' ? 1 : 3));
        std::istringstream parts(t);
        string item;
        while (std::getline(parts, item, ',')) {
            item = trimText(item);
            if (item.empty()) continue;
            if (item == "全部" || item == "*") {
                memoryPullAll = true;
            } else if (!item.empty() && item.back() == '*') {
                memoryPullPrefixes.push_back(item.substr(0, item.size() - 1));
            } else {
                memoryPullKeys.insert(item);
            }
        }
    }
}

bool Interpreter::isPulled(const string& key) const {
    if (memoryPullAll) return true;
    if (memoryPullKeys.count(key)) return true;
    for (const auto& p : memoryPullPrefixes)
        if (startsWith(key, 0, p)) return true;
    return false;
}

static vector<string> memoryTokens(const string& s) {
    vector<string> out;
    string cur;
    auto flush = [&]() {
        if (!cur.empty()) {
            out.push_back(cur);
            cur.clear();
        }
    };
    for (unsigned char c : s) {
        if (c == '{' || c == '}' || c == '[' || c == ']' || c == '"' || c == ':' ||
            c == ',' || c == ' ' || c == '\n' || c == '\t' || c == '\r')
            flush();
        else
            cur += (char)c;
    }
    flush();
    return out;
}

void Interpreter::buildMemoryDict(const string& extra) {
    decompressCache.clear();
    vector<std::pair<string, string>> compRaws;
    for (const auto& kv : memoryCompressed)
        compRaws.push_back({kv.first, decompressMemoryText(kv.second, 0)});
    memoryDict.clear();
    memoryDictIndex.clear();
    std::map<string, int> freq;
    auto scanText = [&](const string& text) {
        for (const auto& t : memoryTokens(text))
            if (t.size() >= 3) ++freq[t];
    };
    for (const auto& kv : memoryStore) scanText(jsonDump(kv.second, 0));
    for (const auto& kv : memoryTemp) scanText(jsonDump(kv.second, 0));
    for (const auto& kv : compRaws) scanText(kv.second);
    if (!extra.empty()) scanText(extra);
    struct Cand {
        string token;
        long long score;
    };
    vector<Cand> cands;
    for (const auto& kv : freq) {
        if (kv.second < 2) continue;
        long long score = (long long)(kv.first.size() - 2) * kv.second;
        if (score > 0) cands.push_back({kv.first, score});
    }
    std::sort(cands.begin(), cands.end(), [](const Cand& a, const Cand& b) {
        if (a.score != b.score) return a.score > b.score;
        return a.token < b.token;
    });
    int id = 1;
    for (const auto& c : cands) {
        if (id > 255) break;
        memoryDict.push_back(c.token);
        memoryDictIndex[c.token] = id++;
    }
    for (const auto& kv : compRaws) {
        memoryOrigSize[kv.first] = kv.second.size();
        memoryCompressed[kv.first] = compressMemoryText(kv.second);
    }
}

string Interpreter::compressMemoryText(const string& text) {
    if (memoryDict.empty() || text.empty()) return text;
    string out;
    size_t i = 0;
    while (i < text.size()) {
        unsigned char c = text[i];
        bool delim = (c == '{' || c == '}' || c == '[' || c == ']' || c == '"' || c == ':' ||
                      c == ',' || c == ' ' || c == '\n' || c == '\t' || c == '\r');
        if (delim) {
            out += (char)c;
            ++i;
            continue;
        }
        size_t j = i;
        while (j < text.size()) {
            unsigned char d = text[j];
            if (d == '{' || d == '}' || d == '[' || d == ']' || d == '"' || d == ':' ||
                d == ',' || d == ' ' || d == '\n' || d == '\t' || d == '\r')
                break;
            ++j;
        }
        string tok = text.substr(i, j - i);
        auto it = memoryDictIndex.find(tok);
        if (it != memoryDictIndex.end()) {
            out += (char)1;
            out += (char)it->second;
        } else {
            for (char ch : tok) {
                if ((unsigned char)ch == 1) {
                    out += (char)1;
                    out += (char)0;
                } else {
                    out += ch;
                }
            }
        }
        i = j;
    }
    if (out.size() >= text.size()) return text;
    double saving = 1.0 - (double)out.size() / (double)text.size();
    if (saving < memoryMinSavings) return text;
    if (decompressMemoryText(out, 0) != text) return text;
    return out;
}

static string accelKey(const string& name, const vector<Value>& args);
string Interpreter::leapKey(const Value& key, int line) {
    if (key.type == VT::Str) return key.str;
    vector<Value> one{key};
    return "key|" + accelKey("", one);
}

string Interpreter::decompressMemoryText(const string& text, int line) {
    auto cache = decompressCache.find(text);
    if (cache != decompressCache.end()) return cache->second;
    string out;
    for (size_t i = 0; i < text.size(); ++i) {
        unsigned char c = text[i];
        if (c != 1) {
            out += (char)c;
            continue;
        }
        if (i + 1 >= text.size())
            throw WenError("运行时错误", line, 0, "压缩数据损坏：缺少符号编号");
        unsigned char id = text[++i];
        if (id == 0) {
            out += (char)1;
        } else if (id <= memoryDict.size()) {
            out += memoryDict[id - 1];
        } else {
            throw WenError("运行时错误", line, 0, "压缩数据损坏：未知符号 " +
                                                   std::to_string((int)id));
        }
    }
    return out;
}

void Interpreter::run(const string& src, const string& name) {
    filename = name;
    sourceLines = splitLines(src);
    scanPull(src);
    try {
        auto program = parseSource(src);
        execProgram(program);
    } catch (IncompleteError& e) {
        throw WenError("语法错误", e.line, 0, e.what());
    }
}

void Interpreter::加载模块(const string& rawName, int line) {
    string name = rawName;
    if (name == "JSON库") name = "数据格式库";
    else if (name == "HTML库") name = "网页库";
    else if (name == "加速库") name = "跃迁库";
    else if (name == "外派库") name = "兼容库";
    else if (name == "安全库" || name == "检测库") name = "网络库";
    else if (name == "翻译器") name = "兼容库";
    if (loadedModules.count(name)) return;
    auto lib = libraryFunctions.find(name);
    if (lib == libraryFunctions.end()) {
        string list;
        for (const auto& kv : libraryFunctions) {
            if (!list.empty()) list += "、";
            list += kv.first;
        }
        throw WenError("运行时错误", line, 0,
                       "未知库「" + name + "」；目前支持：" + list);
    }
    // 核心只负责安装：库自己声明了哪些函数，这里就装哪些。
    for (const auto& kv : lib->second) {
        auto owner = symbolOwner.find(kv.first);
        if (owner != symbolOwner.end() && owner->second != name)
            throw WenError("库冲突", line, 0,
                           "函数「" + kv.first + "」已被「" + owner->second +
                               "」占用；依赖「" + name + "」会覆盖它，请改名或去掉其中一个库");
        Value existing;
        if (globals->lookup(internSymbol(kv.first), existing))
            throw WenError("库冲突", line, 0,
                           "用户代码已定义「" + kv.first + "」，与「" + name +
                               "」同名；依赖会覆盖它，请改名");
        globals->set(kv.first, kv.second);
        symbolOwner[kv.first] = name;
        if (auto b = std::dynamic_pointer_cast<Builtin>(kv.second.callable)) {
            b->module = name;
            b->moduleKnown = true;
            b->cacheableFn = cacheableBuiltin(kv.first);
            b->moduleLoaded = true;
            b->core = false;
        }
    }
    auto aliasFn = [&](const string& cn, const string& old) {
        auto it = lib->second.find(old);
        if (it == lib->second.end()) return;
        globals->set(cn, it->second);
        symbolOwner[cn] = name;
    };
    if (name == "数据格式库") {
        aliasFn("解析结构化文本", "解析JSON");
        aliasFn("生成结构化文本", "生成JSON");
        aliasFn("解析表格文本", "解析CSV");
        aliasFn("生成表格文本", "生成CSV");
    } else if (name == "编码库") {
        aliasFn("六四编码", "Base64编码");
        aliasFn("六四解码", "Base64解码");
        aliasFn("网址编码", "URL编码");
        aliasFn("网址解码", "URL解码");
    } else if (name == "处理器库") {
        aliasFn("处理器核心数", "CPU核心数");
        aliasFn("处理器并行求和", "CPU并行求和");
        aliasFn("处理器并行最大", "CPU并行最大");
        aliasFn("处理器并行最小", "CPU并行最小");
    } else if (name == "网络库") {
        aliasFn("抓取结构化文本", "抓取JSON");
    }    if (name == "数学库") {
        const double pi = piValue();
        globals->set("圆周率", vNum(pi));
        globals->set("π", vNum(pi));
        globals->set("自然常数", vNum(wenE()));
    } else if (name == "物理库") {
        globals->set("重力加速度", vNum(9.80665));
        globals->set("光速", vNum(299792458.0));
        globals->set("万有引力常数", vNum(6.67430e-11));
        globals->set("声速", vNum(343.0));
        globals->set("普朗克常数", vNum(6.62607015e-34));
        globals->set("电子电荷", vNum(1.602176634e-19));
        globals->set("阿伏伽德罗常数", vNum(6.02214076e23));
        globals->set("理想气体常数", vNum(8.314462618));
        globals->set("静电力常量", vNum(8.9875517923e9));
    }
    loadedModules.insert(name);
}

bool Interpreter::是内置库(const string& rawName) const {
    string name = rawName;
    if (name == "JSON库") name = "数据格式库";
    else if (name == "HTML库") name = "网页库";
    else if (name == "加速库") name = "跃迁库";
    else if (name == "外派库") name = "兼容库";
    else if (name == "安全库" || name == "检测库") name = "网络库";
    else if (name == "翻译器") name = "兼容库";
    return libraryFunctions.count(name) > 0;
}

void Interpreter::加载外部库(const string& name, int line) {
    if (loadedModules.count(name)) return;

    static const char* suffixes[] = {".库", ".wenlib", ".wen"};
    vector<fs::path> dirs;
    std::error_code ec;
    if (!filename.empty() && filename[0] != '<') {
        dirs.push_back(fs::u8path(filename).parent_path());
    }
    dirs.push_back(fs::current_path(ec) / fs::u8path("库"));
    dirs.push_back(fs::current_path(ec));

    vector<fs::path> candidates;
    for (const auto& dir : dirs) {
        // 目录库：库/名字/主.wen
        candidates.push_back(dir / fs::u8path(name) / fs::u8path("主.wen"));
        // 单文件库：库/名字.wen、库/名字.w、库/名字.文 …
        for (const char* suf : suffixes) {
            candidates.push_back(dir / fs::u8path(name + suf));
        }
    }

    fs::path found;
    for (const auto& p : candidates) {
        if (fs::exists(p, ec) && !ec) {
            found = p;
            break;
        }
    }
    if (found.empty()) {
        throw WenError("运行时错误", line, 0,
                       "找不到库「" + name +
                       "」：不是内置库，也没找到 库/" + name +
                       ".脚本/.程序/.wen（库还认 .库/.wenlib，或目录 " + name + "/主.wen）");
    }

    loadedModules.insert(name);
    string oldFile = filename;
    vector<string> oldLines = sourceLines;
    bool oldInLibrary = inLibrary_;
    std::set<string> oldExports = moduleExports;
    inLibrary_ = true;
    moduleExports.clear();
    try {
        string src = readWholeFile(found.u8string());
        src = normalizeWenSource(src);
        filename = found.u8string();
        sourceLines = splitLines(src);
        auto program = parseSource(src);
        auto moduleScope = std::make_shared<Scope>(globals);
        execProgram(program, moduleScope);

        auto installExport = [&](const string& n, const Value& val) {
            auto owner = symbolOwner.find(n);
            if (owner != symbolOwner.end() && owner->second != name)
                throw WenError("库冲突", line, 0,
                               "名字「" + n + "」已被「" + owner->second +
                                   "」占用；库「" + name + "」不能再导出它");
            globals->set(n, val);
            symbolOwner[n] = name;
        };
        if (moduleExports.empty()) {
            for (const auto& kv : moduleScope->vars) installExport(kv.first, kv.second);
        } else {
            for (const auto& n : moduleExports) {
                auto it = moduleScope->vars.find(n);
                if (it == moduleScope->vars.end()) {
                    throw WenError("运行时错误", line, 0,
                                   "库「" + name + "」导出的名字「" + n +
                                   "」没有定义");
                }
                installExport(n, it->second);
            }
        }
        filename = oldFile;
        sourceLines = oldLines;
        inLibrary_ = oldInLibrary;
        moduleExports = oldExports;
    } catch (WenError& e) {
        loadedModules.erase(name);
        filename = oldFile;
        sourceLines = oldLines;
        inLibrary_ = oldInLibrary;
        moduleExports = oldExports;
        throw WenError("运行时错误", line, 0,
                       "库「" + name + "」加载失败（第 " +
                       std::to_string(e.line) + " 行）：" + e.what());
    } catch (IncompleteError& e) {
        loadedModules.erase(name);
        filename = oldFile;
        sourceLines = oldLines;
        inLibrary_ = oldInLibrary;
        moduleExports = oldExports;
        throw WenError("语法错误", line, 0,
                       "库「" + name + "」没有写完（第 " +
                       std::to_string(e.line) + " 行）：" + e.what());
    } catch (std::exception& e) {
        loadedModules.erase(name);
        filename = oldFile;
        sourceLines = oldLines;
        inLibrary_ = oldInLibrary;
        moduleExports = oldExports;
        throw WenError("运行时错误", line, 0,
                       "库「" + name + "」加载失败：" + e.what());
    }
}

void Interpreter::execProgram(const vector<StmtPtr>& program) {
    execProgram(program, globals);
}

void Interpreter::execProgram(const vector<StmtPtr>& program, const shared_ptr<Scope>& scope) {
    gTotal = std::max<long long>(gTotal, (long long)program.size());
    try {
        for (const auto& s : program) exec(s, scope);
    } catch (ReturnSignal& r) {
        rtError(r.line, "「返回」只能用在函数里");
    } catch (BreakSignal& b) {
        rtError(b.line, "「中断」只能用在循环里");
    } catch (ContinueSignal& c) {
        rtError(c.line, "「继续」只能用在循环里");
    }
}

static string int128ToString(WenI128 x);
static bool fastLinearSumWhile(Interpreter& vm, const StmtPtr& s,
                                const shared_ptr<Scope>& scope) {
    if (gNoFast) return false;
    if (!scope || scope != vm.globals) return false;
    if (!s->expr || s->expr->k != Expr::K::Binary) return false;
    string op = s->expr->op;
    if (op != "<" && op != "<=") return false;
    ExprPtr lv = s->expr->args[0], rv = s->expr->args[1];
    if (!lv || lv->k != Expr::K::Var || lv->gslot < 0 || lv->slotDepth != 0) return false;
    if (!rv || rv->k != Expr::K::Num) return false;
    if (s->body.size() != 2) return false;
    int cond = lv->gslot;
    double limit = rv->num;

    auto isSelfPlus = [&](const StmtPtr& st, int self, const ExprPtr& other) -> bool {
        if (!st || st->k != Stmt::K::Assign) return false;
        if (!st->target || st->target->k != Expr::K::Var || st->target->gslot != self) return false;
        if (!st->expr || st->expr->k != Expr::K::Binary || st->expr->op != "+") return false;
        ExprPtr a = st->expr->args[0], b = st->expr->args[1];
        if (!a || a->k != Expr::K::Var || a->gslot != self) return false;
        if (!other || other->k != Expr::K::Var || other->gslot < 0) return false;
        return b && b->k == Expr::K::Var && b->gslot == other->gslot;
    };

    const StmtPtr& s0 = s->body[0];
    const StmtPtr& s1 = s->body[1];
    int acc = -1;
    bool accFirst = false, incFirst = false;
    ExprPtr dummy;
    if (s0 && s0->k == Stmt::K::Assign && s0->target && s0->target->k == Expr::K::Var &&
        s0->target->gslot != cond && s1 && s1->k == Stmt::K::Assign &&
        s1->target && s1->target->k == Expr::K::Var && s1->target->gslot == cond) {
        ExprPtr incOther;
        if (s1->expr && s1->expr->k == Expr::K::Binary && s1->expr->op == "+" &&
            s1->expr->args.size() == 2) {
            ExprPtr ia = s1->expr->args[0], ib = s1->expr->args[1];
            if (ia && ia->k == Expr::K::Var && ia->gslot == cond && ib && ib->k == Expr::K::Num && ib->num == 1)
                incOther = ia;
        }
        if (incOther && isSelfPlus(s0, s0->target->gslot, lv)) { acc = s0->target->gslot; accFirst = true; }
    }
    if (acc < 0) return false;

    Value av, cv;
    if (!vm.globals->fastGet(acc, av) || av.type != VT::Num) return false;
    if (!vm.globals->fastGet(cond, cv) || cv.type != VT::Num) return false;
    double a = av.num, i = cv.num;
    if (accFirst) {
        long double count = 0;
        if (op == "<") count = std::ceil((long double)limit - (long double)i);
        else count = std::floor((long double)limit - (long double)i) + 1.0L;
        if (count >= 1000000.0L) {
            auto isInt = [](double x) { return std::trunc(x) == x && std::fabs(x) < 9.0e15; };
#if defined(__SIZEOF_INT128__)
            if (isInt(a) && isInt(i) && isInt(limit) && count < 9.0e18L) {
                WenI128 c = (WenI128)count;
                WenI128 series = c * (2 * (WenI128)(long long)i + (c - 1)) / 2;
                WenI128 sum = (WenI128)(long long)a + series;
                vm.globals->fastSet(acc, vBig(int128ToString(sum)));
                vm.globals->fastSet(cond, vNum(i + (double)c));
                return true;
            }
#endif
            long double series = count * (2.0L * (long double)i + count - 1.0L) / 2.0L;
            a += (double)series;
            i += (double)count;
            vm.globals->fastSet(acc, vNum(a));
            vm.globals->fastSet(cond, vNum(i));
            return true;
        }
    }
    auto one = [&]() {
        if (accFirst) { a += i; i += 1; }
        else { i += 1; a += i; }
    };
    if (op == "<") {
        while (i + 7 < limit) {
            one(); one(); one(); one(); one(); one(); one(); one();
        }
        while (i < limit) one();
    } else {
        while (i + 7 <= limit) {
            one(); one(); one(); one(); one(); one(); one(); one();
        }
        while (i <= limit) one();
    }
    vm.globals->fastSet(acc, vNum(a));
    vm.globals->fastSet(cond, vNum(i));
    return true;
}

static bool fastNumericWhile(Interpreter& vm, const StmtPtr& s,
                             const shared_ptr<Scope>& scope) {
    if (gNoFast) return false;
    if (!scope || scope != vm.globals) return false;
    if (!s->expr || s->expr->k != Expr::K::Binary) return false;
    string op = s->expr->op;
    if (op != "<" && op != "<=" && op != ">" && op != ">=" && op != "==") return false;
    ExprPtr left = s->expr->args[0], right = s->expr->args[1];
    if (!left || left->k != Expr::K::Var || left->slotDepth != 0 || left->gslot < 0) return false;
    if (!right || right->k != Expr::K::Num) return false;
    int condSlot = left->gslot;
    double rhs = right->num;
    Value cv;
    if (!vm.globals->fastGet(condSlot, cv) || cv.type != VT::Num) return false;

    struct Upd {
        int slot = 0, oslot = 0, ti = -1, oi = -1;
        bool add = true, operandSlot = false;
        double num = 0;
    };
    std::vector<Upd> ups;
    if (s->body.size() > 6) return false;
    for (const auto& st : s->body) {
        if (!st || st->k != Stmt::K::Assign) return false;
        if (!st->target || st->target->k != Expr::K::Var ||
            st->target->slotDepth != 0 || st->target->gslot < 0) return false;
        if (!st->expr || st->expr->k != Expr::K::Binary) return false;
        string bop = st->expr->op;
        if (bop != "+" && bop != "-") return false;
        ExprPtr a = st->expr->args[0], b = st->expr->args[1];
        if (!a || a->k != Expr::K::Var || a->gslot != st->target->gslot ||
            a->slotDepth != 0) return false;
        Upd u;
        u.slot = st->target->gslot;
        u.add = bop == "+";
        u.operandSlot = b && b->k == Expr::K::Var && b->slotDepth == 0 && b->gslot >= 0;
        if (u.operandSlot) u.oslot = b->gslot;
        else if (b && b->k == Expr::K::Num) u.num = b->num;
        else return false;
        ups.push_back(u);
    }
    if (ups.empty()) return false;

    std::vector<int> slots{condSlot};
    auto idxOf = [&](int slot) -> int {
        for (size_t i = 0; i < slots.size(); ++i)
            if (slots[i] == slot) return (int)i;
        slots.push_back(slot);
        return (int)slots.size() - 1;
    };
    for (auto& u : ups) {
        u.ti = idxOf(u.slot);
        if (u.operandSlot) u.oi = idxOf(u.oslot);
    }
    std::vector<double> vals(slots.size());
    for (size_t i = 0; i < slots.size(); ++i) {
        Value v;
        if (!vm.globals->fastGet(slots[i], v) || v.type != VT::Num) return false;
        vals[i] = v.num;
    }
    int ci = idxOf(condSlot);
    double lhs = vals[(size_t)ci];
    auto step = [&]() {
        for (auto& u : ups) {
            double b = u.operandSlot ? vals[(size_t)u.oi] : u.num;
            double& t = vals[(size_t)u.ti];
            t = u.add ? t + b : t - b;
            if (u.slot == condSlot) lhs = t;
        }
    };
    if (op == "<") { while (lhs < rhs) step(); }
    else if (op == "<=") { while (lhs <= rhs) step(); }
    else if (op == ">") { while (lhs > rhs) step(); }
    else if (op == ">=") { while (lhs >= rhs) step(); }
    else { while (lhs == rhs) step(); }
    for (size_t i = 0; i < slots.size(); ++i)
        vm.globals->fastSet(slots[i], vNum(vals[i]));
    return true;
}

// ============================================================
// 语句级字节码：编译 + 执行
// 只编译「纯数值」的代码：没有调用、没有文本/列表/字典、没有 try/match/for。
// 编译不了的整块直接放弃，继续走 AST（双轨并存，按函数/循环粒度切换）。
// ============================================================

static bool gNoBytecode = false;   // --无字节码：强制走 AST，供对拍用例使用

// 一元负号：AST 和字节码共用，避免两处各写一遍 Int 的取负语义。
static Value negateValue(const Value& a, int line) {
    if (a.type == VT::Int) return vInt((uint64_t)(-(WenI128)intSigned(a)), a.width, a.isSigned);
    return vNum(-needNum(a, "负号", line));
}

namespace {

// 「这条语句里有没有属于外层循环的中断/继续」。
// 有的话不能交给 exec：字节码里的循环是跳转，不是 C++ 的 try，
// 委派出去的 BreakSignal 会一路穿出 runCode，变成「中断只能用在循环里」。
static bool hasFreeLoopControl(const StmtPtr& s) {
    if (!s) return false;
    switch (s->k) {
        case Stmt::K::Break:
        case Stmt::K::Continue: return true;
        case Stmt::K::While:
        case Stmt::K::For: return false;   // 里面的中断属于它自己
        default: break;
    }
    for (const auto& st : s->body) if (hasFreeLoopControl(st)) return true;
    for (const auto& st : s->elseBody) if (hasFreeLoopControl(st)) return true;
    for (const auto& st : s->finallyBody) if (hasFreeLoopControl(st)) return true;
    for (const auto& br : s->branches)
        for (const auto& st : br.second) if (hasFreeLoopControl(st)) return true;
    return false;
}

struct WenAsm {
    std::vector<Instr> code;
    std::vector<double> kconst;
    int depth = 0;
    int maxDepth = 0;
    bool topLevel = false;        // 作用域就是 globals，可以走全局快槽
    shared_ptr<Scope> globals;
    std::vector<SymId> params;
    struct Loop {
        std::vector<int> brks;
        std::vector<int> conts;
    };
    std::vector<Loop> loops;
    // 「循环体块」模式：把 对于 的循环体单独编译，中断/继续 变成块尾标记，
    // 由 exec 里的循环本体决定怎么处理——循环语义仍然只有 exec 一份。
    bool blockMode = false;
    std::vector<int> blkBrks;
    std::vector<int> blkConts;
    // 编译不了的语句（对于/尝试/匹配/嵌套函数…）不放弃整个函数，
    // 记在这里，运行时用 BC_EXECSTMT 交给 exec 原样执行——语义和 AST 路径一模一样。
    std::vector<StmtPtr> slow;

    int emit(unsigned char op, int a = 0, int b = 0) {
        code.push_back(Instr{op, a, b});
        return (int)code.size() - 1;
    }
    void push() { if (++depth > maxDepth) maxDepth = depth; }
    void drop() { --depth; }
    bool isParam(SymId id) const {
        for (SymId p : params) if (p == id) return true;
        return false;
    }
    bool expr(const ExprPtr& e, bool numCtx = false);
    bool stmt(const StmtPtr& s);
    // 一句一句地编：这句编不出来就整体回滚，然后把它丢进慢语句表交给 exec。
    // 这样「表达式里有下标/文本/字典」之类的语句只损失它自己，不牵连整个函数。
    bool tryStmt(const StmtPtr& s) {
        size_t mark = code.size();
        int depthMark = depth;
        size_t slowMark = slow.size();
        size_t loopsMark = loops.size();
        size_t brkMark = blkBrks.size();
        size_t contMark = blkConts.size();
        if (stmt(s)) return true;
        code.resize(mark);
        depth = depthMark;
        slow.resize(slowMark);
        loops.resize(loopsMark);
        blkBrks.resize(brkMark);
        blkConts.resize(contMark);
        // 中断/继续 不能委派（它们本来就只能在循环里，交给 exec 语义会变）。
        // 「当」也不能委派：exec 的 While 分支自己会再试着编译这个循环，
        // 委派过去就会 exec → 编译 → 委派 → exec 地无限递归下去。
        if (s->k == Stmt::K::Break || s->k == Stmt::K::Continue ||
            s->k == Stmt::K::While) return false;
        if (hasFreeLoopControl(s)) return false;
        emit(BC_LINE, s->line);
        slow.push_back(s);
        emit(BC_EXECSTMT, (int)slow.size() - 1);
        return true;
    }
    bool block(const std::vector<StmtPtr>& b) {
        for (const auto& st : b) if (!tryStmt(st)) return false;
        return true;
    }
};

bool WenAsm::expr(const ExprPtr& e, bool numCtx) {
    if (!e) return false;
    switch (e->k) {
        case Expr::K::Num:
            kconst.push_back(e->num);
            emit(BC_K, (int)kconst.size() - 1);
            push();
            return true;
        case Expr::K::Bool:
            emit(e->b ? BC_PUSHT : BC_PUSHF);
            push();
            return true;
        case Expr::K::Var: {
            int gs = topLevel ? topSlotOf(e->sym) : -1;
            if (numCtx) {
                // 运算位置：运行时只读 num，类型不是数字再退回完整读取
                if (gs >= 0) emit(BC_GN, gs, (int)e->sym);
                else emit(BC_LN, (int)e->sym);
            } else if (gs >= 0) {
                emit(BC_G, gs, (int)e->sym);
            } else {
                emit(BC_L, (int)e->sym);
            }
            push();
            return true;
        }
        case Expr::K::Unary: {
            if (e->args.size() != 1) return false;
            if (e->op == "+") return expr(e->args[0], numCtx);   // 正号不改值
            if (!expr(e->args[0], true)) return false;
            drop();
            if (e->op == "-") { emit(BC_NEG); push(); return true; }
            if (e->op == "非") { emit(BC_NOT); push(); return true; }
            return false;
        }
        case Expr::K::Binary: {
            if (e->args.size() != 2) return false;
            unsigned char op = 0;
            const string& o = e->op;
            // 且/或：用跳转展开，保持短路语义（右边可能不执行）
            if (o == "且" || o == "或") {
                bool isAnd = (o == "且");
                if (!expr(e->args[0])) return false;
                drop();
                int j = emit(isAnd ? BC_JZ : BC_JNZ, 0);
                if (!expr(e->args[1])) return false;
                drop();
                emit(BC_BOOL);
                push();
                int jmp = emit(BC_JMP, 0);
                code[(size_t)j].a = (int)code.size();
                emit(isAnd ? BC_PUSHF : BC_PUSHT);
                push();
                code[(size_t)jmp].a = (int)code.size();
                return true;
            }
            bool arith = true;
            if (o == "+") op = BC_ADD;
            else if (o == "-") op = BC_SUB;
            else if (o == "*") op = BC_MUL;
            else if (o == "/") op = BC_DIV;
            else if (o == "%") op = BC_MOD;
            else if (o == "<") op = BC_LT;
            else if (o == "<=") op = BC_LE;
            else if (o == ">") op = BC_GT;
            else if (o == ">=") op = BC_GE;
            else if (o == "==" || o == "=") { op = BC_EQ; arith = false; }
            else if (o == "!=") { op = BC_NE; arith = false; }
            else return false;   // 且/或（短路）、整除、幂等先不编译
            if (!expr(e->args[0], arith)) return false;
            if (!expr(e->args[1], arith)) return false;
            drop();
            emit(op);
            return true;
        }
        case Expr::K::Call: {
            // 指挥(...) 是「按名字派发」，保持走 AST；普通调用编译成 CALL。
            if (e->commandCall || e->args.empty()) return false;
            const ExprPtr& callee = e->args[0];
            if (!callee) return false;
            if (callee->k == Expr::K::Var) {
                int gs = topLevel ? topSlotOf(callee->sym) : -1;
                emit(BC_LC, (int)callee->sym, gs);
            } else if (!expr(callee)) {
                return false;
            }
            push();
            for (size_t i = 1; i < e->args.size(); ++i) {
                if (!expr(e->args[i])) return false;
                push();
            }
            emit(BC_CALL, (int)e->args.size() - 1);
            // 被调用者 + 实参 出栈，结果入栈
            depth -= (int)e->args.size() - 1;
            return true;
        }
        default:
            return false;
    }
}

bool WenAsm::stmt(const StmtPtr& s) {
    if (!s) return false;
    switch (s->k) {
        case Stmt::K::Assign: {
            if (!s->target || s->target->k != Expr::K::Var || !s->target->sym) return false;
            emit(BC_LINE, s->line);
            if (!expr(s->expr)) return false;
            SymId sym = s->target->sym;
            int gs = topLevel ? topSlotOf(sym) : -1;
            if (gs >= 0) {
                // 顶层快槽：顺手把「名字 → 槽」记上（等价的 fastBind 本来在第一次赋值时做）
                if (globals) globals->fastBind(sym, gs);
                emit(BC_STG, gs, (int)sym);
            } else if (s->declareLocal) {
                emit(BC_STLL, (int)sym);          // 「局部」：强制写当前帧
            } else if (!topLevel && isParam(sym)) {
                emit(BC_STLL, (int)sym);          // 形参一定在当前帧里
            } else {
                // 其余走作用域链，和 AST 同一套语义。
                // b 里带上「这个名字是不是内建名」——内建表启动后就不再变，
                // 编译期算一次，省掉每次赋值查 690 项的名字表。
                emit(BC_STL, (int)sym, gBuiltinArity.count(symbolName(sym)) ? 1 : 0);
            }
            drop();
            return true;
        }
        case Stmt::K::Print: {
            emit(BC_LINE, s->line);
            for (const auto& a : s->args) {
                if (!expr(a)) return false;
                push();
            }
            emit(BC_PRINT, (int)s->args.size());
            depth -= (int)s->args.size();
            return true;
        }
        case Stmt::K::Return: {
            if (topLevel) return false;           // 顶层不该有「返回」
            emit(BC_LINE, s->line);
            if (s->expr) {
                if (!expr(s->expr)) return false;
                emit(BC_RET);
                drop();
            } else {
                emit(BC_RETN);
            }
            return true;
        }
        case Stmt::K::If: {
            emit(BC_LINE, s->line);
            std::vector<int> ends;
            for (const auto& br : s->branches) {
                if (!expr(br.first)) return false;
                drop();
                int jz = emit(BC_JZ, 0);
                if (!block(br.second)) return false;
                ends.push_back(emit(BC_JMP, 0));
                code[(size_t)jz].a = (int)code.size();
            }
            if (!block(s->elseBody)) return false;
            for (int e2 : ends) code[(size_t)e2].a = (int)code.size();
            return true;
        }
        case Stmt::K::While: {
            int start = (int)code.size();
            emit(BC_LINE, s->line);
            if (!expr(s->expr)) return false;
            drop();
            int jz = emit(BC_JZ, 0);
            loops.push_back(Loop{});
            if (!block(s->body)) return false;    // 失败时整个编译结果丢弃，不用收尾
            Loop L = loops.back();
            loops.pop_back();
            emit(BC_JMP, start);
            code[(size_t)jz].a = (int)code.size();
            for (int c : L.conts) code[(size_t)c].a = start;
            for (int b : L.brks) code[(size_t)b].a = (int)code.size();
            return true;
        }
        case Stmt::K::Break: {
            if (loops.empty() && blockMode) {
                emit(BC_LINE, s->line);
                blkBrks.push_back(emit(BC_JMP, 0));
                return true;
            }
            if (loops.empty()) return false;
            emit(BC_LINE, s->line);
            loops.back().brks.push_back(emit(BC_JMP, 0));
            return true;
        }
        case Stmt::K::Continue: {
            if (loops.empty() && blockMode) {
                emit(BC_LINE, s->line);
                blkConts.push_back(emit(BC_JMP, 0));
                return true;
            }
            if (loops.empty()) return false;
            emit(BC_LINE, s->line);
            loops.back().conts.push_back(emit(BC_JMP, 0));
            return true;
        }
        default:
            // 编译不了的语句交给 exec 原样执行：整函数照旧编成字节码，
            // 只有这几句多一次 exec 调用，语义与 AST 路径完全一致。
            emit(BC_LINE, s->line);
            slow.push_back(s);
            emit(BC_EXECSTMT, (int)slow.size() - 1);
            return true;
    }
}

}  // namespace

// 把一段语句编译成字节码；失败返回 false，调用方继续用 AST。
static bool compileBody(const std::vector<StmtPtr>& body, const std::vector<SymId>& params,
                        bool topLevel, const shared_ptr<Scope>& globals,
                        std::vector<Instr>& outCode, std::vector<double>& outK,
                        std::vector<StmtPtr>& outSlow, int& outStack) {
    if (body.empty()) return false;
    WenAsm a;
    a.topLevel = topLevel;
    a.globals = globals;
    a.params = params;
    if (!a.block(body)) return false;
    outCode.swap(a.code);
    outK.swap(a.kconst);
    outSlow.swap(a.slow);
    outStack = a.maxDepth + 4;
    return true;
}

// 把「一段循环体」编译成块：跑完返回，中断/继续 用块尾标记交回给 exec。
// 循环本身的语义（遍历什么、怎么绑定变量）仍然只有 exec 一份。
static bool compileBlock(const std::vector<StmtPtr>& body, bool topLevel,
                         const shared_ptr<Scope>& globals,
                         std::vector<Instr>& outCode, std::vector<double>& outK,
                         std::vector<StmtPtr>& outSlow, int& outStack, bool& hasRet) {
    hasRet = false;
    if (body.empty()) return false;
    WenAsm a;
    a.topLevel = topLevel;
    a.globals = globals;
    a.blockMode = true;
    if (!a.block(body)) return false;
    a.emit(BC_LOOPEND, 0);
    int lc = (int)a.code.size();
    a.emit(BC_LOOPEND, 1);
    int lb = (int)a.code.size();
    a.emit(BC_LOOPEND, 2);
    for (int c : a.blkConts) a.code[(size_t)c].a = lc;
    for (int b : a.blkBrks) a.code[(size_t)b].a = lb;
    for (const auto& ins : a.code)
        if (ins.op == BC_RET || ins.op == BC_RETN) { hasRet = true; break; }
    outCode.swap(a.code);
    outK.swap(a.kconst);
    outSlow.swap(a.slow);
    outStack = a.maxDepth + 4;
    return true;
}

// 对于 … 在 范围(a, b, step) 中：整个循环编成一段字节码，一次 runCode 跑完。
// 只有「单变量 + 迭代对象确实是范围」才走这里；其余情况由 exec 的通用循环兜底。
static bool compileForRange(const StmtPtr& s, const Value& iter, bool topLevel,
                            const shared_ptr<Scope>& globals,
                            std::vector<Instr>& outCode, std::vector<double>& outK,
                            std::vector<StmtPtr>& outSlow, int& outStack, bool& hasRet) {
    hasRet = false;
    if (!s || s->body.empty()) return false;
    WenAsm a;
    a.topLevel = topLevel;
    a.globals = globals;
    if (s->nameSlot >= 0 && globals) globals->fastBind(s->nameSym, s->nameSlot);
    auto pushK = [&](double d) {
        a.kconst.push_back(d);
        a.emit(BC_K, (int)a.kconst.size() - 1);
        a.push();
    };
    pushK(iter.rstart);
    pushK(iter.rstop);
    pushK(iter.rstep);
    int ltop = (int)a.code.size();
    int chk = a.emit(BC_FORCHECK, 0);
    a.emit(BC_FORVAR, s->nameSlot, (int)s->nameSym);
    a.loops.push_back(WenAsm::Loop{});
    if (!a.block(s->body)) return false;
    WenAsm::Loop L = a.loops.back();
    a.loops.pop_back();
    int lstep = (int)a.code.size();
    a.emit(BC_FORSTEP, ltop);
    int ldrop = (int)a.code.size();
    a.emit(BC_FORDROP, 3);
    for (int c : L.conts) a.code[(size_t)c].a = lstep;   // 继续 → 直接去 +步长
    for (int b : L.brks) a.code[(size_t)b].a = ldrop;    // 中断 → 收尾
    a.code[(size_t)chk].a = ldrop;
    for (const auto& ins : a.code)
        if (ins.op == BC_RET || ins.op == BC_RETN) { hasRet = true; break; }
    outCode.swap(a.code);
    outK.swap(a.kconst);
    outSlow.swap(a.slow);
    outStack = a.maxDepth + 4;
    return true;
}

// 表达式栈：按「深度指针」复用同一块内存，嵌套调用只是往上叠，不重新分配。
static thread_local std::vector<Value> gVStack;
static thread_local size_t gVSP = 0;

static inline void vmSetNum(Value& v, double d) {
    v.type = VT::Num; v.b = false; v.i = 0; v.num = d;
    v.width = 32; v.isSigned = false;
    v.str.clear(); v.big.clear();
    v.list.reset(); v.dict.reset(); v.callable.reset(); v.bytes.reset(); v.vol.reset();
}
static inline void vmSetBool(Value& v, bool x) {
    vmSetNum(v, x ? 1.0 : 0.0);
    v.type = VT::Bool; v.b = x;
}

Value Interpreter::runCode(const std::vector<Instr>& code, const std::vector<double>& kconst,
                           const std::vector<StmtPtr>& slow, int vstack,
                           const shared_ptr<Scope>& scope) {
    size_t base = gVSP;
    if (gVStack.size() < base + (size_t)vstack) gVStack.resize(base + (size_t)vstack);
    gVSP = base + (size_t)vstack;
    struct Restore { size_t b; ~Restore() { gVSP = b; } } restore{base};
    vmCtl = 0;
    vmRetFlag = 0;

    size_t sp = 0;
    size_t pc = 0;
    // 完整读一个变量（带零参数自动调用），AST 的 Var 分支同语义
    auto loadInto = [&](Value& d, bool useSlot, int slot, SymId sym) {
        bool got = false;
        if (useSlot && globals->fastGet(slot, d)) got = true;
        if (!got && !scope->lookup(sym, d)) undefinedName(symbolName(sym), gLastLine);
        if (d.type == VT::Func && d.callable && d.callable->zeroArgCall()) {
            vector<Value> noArgs;
            d = callValue(d, noArgs, gLastLine);
        }
    };
    for (;;) {
        if (pc >= code.size()) return vNone();
        const Instr& in = code[pc];
        switch (in.op) {
            case BC_LINE:
                gLastLine = in.a;
                ++gExecuted;
                ++pc;
                break;
            case BC_K:
                vmSetNum(gVStack[base + sp], kconst[(size_t)in.a]);
                ++sp; ++pc;
                break;
            case BC_L:
            case BC_G: {
                Value& d = gVStack[base + sp];
                bool useSlot = (in.op == BC_G);
                loadInto(d, useSlot, in.a, (SymId)(useSlot ? in.b : in.a));
                ++sp; ++pc;
                break;
            }
            case BC_GN:
            case BC_LN: {
                // 运算位置：快槽里是数字就直接取 num，省掉整份 200 字节拷贝
                Value& d = gVStack[base + sp];
                bool useSlot = (in.op == BC_GN);
                SymId sym = (SymId)(useSlot ? in.b : in.a);
                Value* p = useSlot ? globals->fastPtr(in.a) : scope->localPtr(sym);
                if (p && p->type == VT::Num) {
                    vmSetNum(d, p->num);
                } else {
                    loadInto(d, useSlot, in.a, sym);
                }
                ++sp; ++pc;
                break;
            }
            case BC_STG: {
                Value& s0 = gVStack[base + sp - 1];
                if (s0.type != VT::Num && s0.type != VT::Int && s0.type != VT::Bool)
                    scope->set((SymId)in.b, s0);      // 非数字：名字表里也要留一份
                globals->fastSet(in.a, std::move(s0));
                --sp; ++pc;
                break;
            }
            case BC_STL: {
                Value v = std::move(gVStack[base + sp - 1]);
                --sp;
                assignVarSym((SymId)in.a, std::move(v), scope, in.b != 0);
                ++pc;
                break;
            }
            case BC_STLL: {
                scope->set((SymId)in.a, std::move(gVStack[base + sp - 1]));
                --sp; ++pc;
                break;
            }
            case BC_POP:
                --sp; ++pc;
                break;
            case BC_ADD: case BC_SUB: case BC_MUL: case BC_DIV: case BC_MOD:
            case BC_LT: case BC_LE: case BC_GT: case BC_GE: {
                Value& b = gVStack[base + sp - 1];
                Value& a = gVStack[base + sp - 2];
                --sp; ++pc;
                if (a.type == VT::Num && b.type == VT::Num) {
                    double x = a.num, y = b.num;
                    switch (in.op) {
                        case BC_ADD: a.num = x + y; break;
                        case BC_SUB: a.num = x - y; break;
                        case BC_MUL: a.num = x * y; break;
                        case BC_DIV:
                            if (y != 0) a.num = x / y;
                            else a = applyBinary("/", a, b, gLastLine);
                            break;
                        case BC_MOD:
                            if (y != 0) a.num = x - std::floor(x / y) * y;
                            else a = applyBinary("%", a, b, gLastLine);
                            break;
                        case BC_LT: vmSetBool(a, x < y); break;
                        case BC_LE: vmSetBool(a, x <= y); break;
                        case BC_GT: vmSetBool(a, x > y); break;
                        default:    vmSetBool(a, x >= y); break;
                    }
                } else {
                    const char* op = in.op == BC_ADD ? "+" : in.op == BC_SUB ? "-"
                                   : in.op == BC_MUL ? "*" : in.op == BC_DIV ? "/"
                                   : in.op == BC_MOD ? "%" : in.op == BC_LT ? "<"
                                   : in.op == BC_LE ? "<=" : in.op == BC_GT ? ">" : ">=";
                    a = applyBinary(op, a, b, gLastLine);
                }
                break;
            }
            case BC_EQ:
            case BC_NE: {
                Value& b = gVStack[base + sp - 1];
                Value& a = gVStack[base + sp - 2];
                bool r = valueEquals(a, b);
                vmSetBool(a, in.op == BC_EQ ? r : !r);
                --sp; ++pc;
                break;
            }
            case BC_NEG: {
                Value& a = gVStack[base + sp - 1];
                if (a.type == VT::Num) a.num = -a.num;
                else a = negateValue(a, gLastLine);
                ++pc;
                break;
            }
            case BC_NOT: {
                Value& a = gVStack[base + sp - 1];
                bool t = truthy(a);
                vmSetBool(a, !t);
                ++pc;
                break;
            }
            case BC_JMP:
                pc = (size_t)in.a;
                break;
            case BC_JNZ: {
                bool t = truthy(gVStack[base + sp - 1]);
                --sp;
                pc = t ? (size_t)in.a : pc + 1;
                break;
            }
            case BC_BOOL: {
                Value& a = gVStack[base + sp - 1];
                bool t = truthy(a);
                vmSetBool(a, t);
                ++pc;
                break;
            }
            case BC_PUSHT:
                vmSetBool(gVStack[base + sp], true);
                ++sp; ++pc;
                break;
            case BC_PUSHF:
                vmSetBool(gVStack[base + sp], false);
                ++sp; ++pc;
                break;
            case BC_PRINT: {
                int argc = in.a;
                string out;
                for (int i = 0; i < argc; ++i) {
                    if (i) out += " ";
                    out += toText(gVStack[base + sp - (size_t)argc + (size_t)i]);
                }
                std::cout << out << "\n";
                sp -= (size_t)argc;
                ++pc;
                break;
            }
            case BC_JZ: {
                bool t = truthy(gVStack[base + sp - 1]);
                --sp;
                pc = t ? pc + 1 : (size_t)in.a;
                break;
            }
            case BC_RET: {
                Value out = std::move(gVStack[base + sp - 1]);
                vmRetFlag = 1;
                return out;
            }
            case BC_RETN:
                vmRetFlag = 1;
                return vNone();
            case BC_LC: {
                // 取「被调用者」的值：和 AST 的 Call 分支一样，不触发零参数自动调用
                Value& d = gVStack[base + sp];
                bool got = false;
                if (in.b >= 0 && globals->fastGet(in.b, d)) got = true;
                if (!got && !scope->lookup((SymId)in.a, d))
                    undefinedName(symbolName((SymId)in.a), gLastLine);
                ++sp; ++pc;
                break;
            }
            case BC_CALL: {
                int argc = in.a;
                size_t cbase = base + sp - (size_t)argc - 1;
                Value callee = std::move(gVStack[cbase]);
                sp -= (size_t)argc + 1;
                if (callee.type == VT::Func && callee.callable &&
                    !accelEnabled && !leapAuto && !memoryAuto) {
                    // 实参就在自己的表达式栈上，直接给指针：一次 vector 分配都省掉
                    gVStack[base + sp] = callee.callable->callSpan(
                        *this, argc > 0 ? &gVStack[cbase + 1] : nullptr, argc, gLastLine);
                } else {
                    vector<Value> args;
                    args.reserve((size_t)argc);
                    for (int i = 0; i < argc; ++i)
                        args.push_back(std::move(gVStack[cbase + 1 + (size_t)i]));
                    gVStack[base + sp] = callValue(callee, args, gLastLine);
                }
                ++sp; ++pc;
                break;
            }
            case BC_LOOPEND:
                vmCtl = in.a;
                return vNone();
            case BC_FORCHECK: {
                Value& x = gVStack[base + sp - 3];
                Value& stop = gVStack[base + sp - 2];
                Value& step = gVStack[base + sp - 1];
                bool go = step.num > 0 ? x.num < stop.num : x.num > stop.num;
                pc = go ? pc + 1 : (size_t)in.a;
                break;
            }
            case BC_FORVAR: {
                Value v;
                vmSetNum(v, gVStack[base + sp - 3].num);
                if (in.a >= 0) globals->fastSet(in.a, std::move(v));
                else scope->set((SymId)in.b, std::move(v));
                ++pc;
                break;
            }
            case BC_FORSTEP:
                gVStack[base + sp - 3].num += gVStack[base + sp - 1].num;
                pc = (size_t)in.a;
                break;
            case BC_FORDROP:
                sp -= (size_t)in.a;
                ++pc;
                break;
            case BC_EXECSTMT: {
                // 编译不了的语句：原样交给 exec，语义和 AST 路径完全一致。
                // delegating 挡住「exec 再把这个循环编译一遍」的无限递归。
                struct DelegGuard {
                    bool& f;
                    bool old;
                    explicit DelegGuard(bool& x) : f(x), old(x) { f = true; }
                    ~DelegGuard() { f = old; }
                } delegGuard(delegating);
                exec(slow[(size_t)in.a], scope);
                if (retFlag) {
                    Value out = std::move(retVal);
                    retFlag = false;
                    vmRetFlag = 1;
                    return out;
                }
                ++pc;
                break;
            }
            default:
                rtError(gLastLine, "内部错误：未知字节码指令");
        }
    }
}

void Interpreter::exec(const StmtPtr& s, const shared_ptr<Scope>& scope) {
    if (retFlag) return;
    ++gExecuted;
    gLastLine = s->line;
    if (s->k != Stmt::K::ExprStmt) lastWasExpr = false;

    switch (s->k) {
        case Stmt::K::Assign: {
            Value v = eval(s->expr, scope);
            if (s->declareLocal && s->target && s->target->k == Expr::K::Var && s->target->gslot < 0) {
                scope->set(s->target->sym, std::move(v));
                break;
            }
            assignTarget(s->target, std::move(v), scope);
            break;
        }
        case Stmt::K::Print: {
            string out;
            for (size_t i = 0; i < s->args.size(); ++i) {
                if (i) out += " ";
                out += toText(eval(s->args[i], scope));
            }
            std::cout << out << "\n";
            break;
        }
        case Stmt::K::If: {
            bool done = false;
            for (const auto& br : s->branches) {
                if (truthy(eval(br.first, scope))) {
                    for (const auto& st : br.second) exec(st, scope);
                    if (retFlag) return;
                    done = true;
                    break;
                }
            }
            if (!done) {
                for (const auto& st : s->elseBody) exec(st, scope);
                if (retFlag) return;
            }
            break;
        }
        case Stmt::K::While: {
            if (fastLinearSumWhile(*this, s, scope)) break;
            if (fastNumericWhile(*this, s, scope)) break;
            // 整个循环编译成字节码，一次 runCode 跑完（编译不了就往下走 AST）
            if (!gNoBytecode && !delegating) {
                std::vector<Instr> lcode;
                std::vector<double> lk;
                std::vector<StmtPtr> lslow;
                int lstack = 0;
                bool tl = (scope.get() == globals.get());
                if (compileBody(std::vector<StmtPtr>{s}, {}, tl, globals, lcode, lk, lslow, lstack)) {
                    Value r = runCode(lcode, lk, lslow, lstack, scope);
                    if (vmRetFlag) { retVal = std::move(r); retFlag = true; }
                    break;
                }
            }
            while (truthy(eval(s->expr, scope))) {
                try {
                    for (const auto& st : s->body) {
                        exec(st, scope);
                        if (retFlag) return;
                    }
                } catch (ContinueSignal&) {
                    continue;
                } catch (BreakSignal&) {
                    break;
                }
            }
            break;
        }
        case Stmt::K::For: {
            // 「对于 x 在 范围(...) 中」不必真造一张表：直接按范围迭代（省一次整表构造）。
            // 只在内建「范围」没被遮蔽、参数全是数字、元素数没超上限时走这条；
            // 其余情况一律照原样调用，保证语义和报错一字不差。
            Value iter;
            bool made = false;
            {
                const ExprPtr& itExpr = s->expr;
                if (!gNoBytecode && itExpr && itExpr->k == Expr::K::Call && !itExpr->commandCall &&
                    itExpr->args.size() >= 2 && itExpr->args.size() <= 4 && itExpr->args[0] &&
                    itExpr->args[0]->k == Expr::K::Var && itExpr->args[0]->text == "范围") {
                    Value callee;
                    std::shared_ptr<Builtin> b;
                    if (scope->lookup(itExpr->args[0]->sym, callee) && callee.type == VT::Func)
                        b = std::dynamic_pointer_cast<Builtin>(callee.callable);
                    if (b && b->name == "范围") {
                        std::vector<Value> av;
                        for (size_t i = 1; i < itExpr->args.size(); ++i)
                            av.push_back(eval(itExpr->args[i], scope));
                        bool nums = true;
                        for (const auto& v : av)
                            if (v.type != VT::Num) { nums = false; break; }
                        if (nums) {
                            double start = 0, stop = 0, step = 1;
                            if (av.size() == 1) stop = av[0].num;
                            else {
                                start = av[0].num; stop = av[1].num;
                                if (av.size() == 3) step = av[2].num;
                            }
                            double span = step == 0 ? 0 : (stop - start) / step;
                            long long n = span <= 0 ? 0 : (long long)std::ceil(span - 1e-12);
                            // 只接整数步长：小数步长按表逐项相加与按范围累加会差最后一位，
                            // 那种情况交给原来的「造表」路径，保证每个元素逐位相同。
                            auto isIntv = [](double x) {
                                return std::trunc(x) == x && std::fabs(x) < 9.0e15;
                            };
                            if (step != 0 && n <= 1000000 && isIntv(start) && isIntv(stop) &&
                                isIntv(step)) {
                                iter = vRange(start, stop, step);
                                made = true;
                            }
                        }
                        if (!made) iter = callValue(callee, av, s->line);
                    }
                }
            }
            if (!made) iter = eval(s->expr, scope);
            bool two = !s->name2.empty();
            // 循环体整体编译成字节码块；遍历与变量绑定仍然只在这里做
            std::vector<Instr> bcode;
            std::vector<double> bk;
            std::vector<StmtPtr> bslow;
            int bstack = 0;
            bool hasRet = false;
            bool bodyCompiled = false;
            std::vector<Instr> rcode;
            std::vector<double> rk;
            std::vector<StmtPtr> rslow;
            int rstack = 0;
            bool rHasRet = false;
            bool rangeCompiled = false;
            if (!gNoBytecode) {
                bool tl = (scope.get() == globals.get());
                bodyCompiled = compileBlock(s->body, tl, globals, bcode, bk, bslow, bstack, hasRet);
            }
            // 「名字 → 快槽」是幂等的，循环外记一次就够，不必每轮查表
            if (s->nameSlot >= 0) globals->fastBind(s->nameSym, s->nameSlot);
            if (two && s->name2Slot >= 0) globals->fastBind(s->name2Sym, s->name2Slot);
            if (!gNoBytecode && !two && iter.type == VT::Range)
                rangeCompiled = compileForRange(s, iter, (scope.get() == globals.get()),
                                                globals, rcode, rk, rslow, rstack, rHasRet);
            auto runBody = [&]() -> bool {          // true 继续下一轮，false 结束循环
                if (bodyCompiled) {
                    int savedCtl = vmCtl;
                    int savedRet = vmRetFlag;
                    vmRetFlag = 0;
                    Value r = runCode(bcode, bk, bslow, bstack, scope);
                    bool didRet = vmRetFlag != 0;
                    int ctl = vmCtl;
                    vmCtl = savedCtl;
                    vmRetFlag = savedRet;
                    if (didRet) { retVal = std::move(r); retFlag = true; return false; }
                    return ctl != 2;
                }
                try {
                    for (const auto& st : s->body) {
                        exec(st, scope);
                        if (retFlag) return false;
                    }
                } catch (ContinueSignal&) {
                    return true;
                } catch (BreakSignal&) {
                    return false;
                }
                return true;
            };
            auto runOne = [&](const Value& k) -> bool {
                if (s->nameSlot >= 0) {
                    globals->fastSet(s->nameSlot, k);
                    if (k.type != VT::Num && k.type != VT::Int && k.type != VT::Bool)
                        scope->set(s->nameSym, k);
                } else {
                    scope->set(s->nameSym, k);
                }
                return runBody();
            };
            auto runTwo = [&](const Value& k, const Value& v) -> bool {
                if (s->nameSlot >= 0) {
                    globals->fastSet(s->nameSlot, k);
                    if (k.type != VT::Num && k.type != VT::Int && k.type != VT::Bool)
                        scope->set(s->nameSym, k);
                } else {
                    scope->set(s->nameSym, k);
                }
                if (s->name2Slot >= 0) globals->fastSet(s->name2Slot, v);
                else scope->set(s->name2Sym, v);
                return runBody();
            };
            if ((iter.type == VT::List || iter.type == VT::Set) && iter.list) {
                for (size_t i = 0; i < iter.list->items.size(); ++i) {
                    bool go = two ? runTwo(vNum((double)i), iter.list->items[i])
                                  : runOne(iter.list->items[i]);
                    if (!go) break;
                }
            } else if (iter.type == VT::Str) {
                auto chars = utf8Chars(iter.str);
                for (size_t i = 0; i < chars.size(); ++i) {
                    bool go = two ? runTwo(vNum((double)i), vStr(chars[i])) : runOne(vStr(chars[i]));
                    if (!go) break;
                }
            } else if (iter.type == VT::Dict && iter.dict) {
                for (const auto& kv : iter.dict->items) {
                    bool go = two ? runTwo(vStr(kv.first), kv.second) : runOne(vStr(kv.first));
                    if (!go) break;
                }
            } else if (iter.type == VT::Range) {
                if (rangeCompiled) {
                    int savedCtl = vmCtl;
                    int savedRet = vmRetFlag;
                    vmRetFlag = 0;
                    Value r = runCode(rcode, rk, rslow, rstack, scope);
                    bool didRet = vmRetFlag != 0;
                    vmCtl = savedCtl;
                    vmRetFlag = savedRet;
                    if (didRet) { retVal = std::move(r); retFlag = true; }
                } else {
                    long long n = 0;
                    for (double x = iter.rstart; iter.rstep > 0 ? x < iter.rstop : x > iter.rstop;
                         x += iter.rstep) {
                        bool go = two ? runTwo(vNum((double)n), vNum(x)) : runOne(vNum(x));
                        ++n;
                        if (!go) break;
                    }
                }
            } else {
                rtError(s->line, "「对于」只能遍历列表、文本、字典、集合或范围，收到" +
                                     typeName(iter));
            }
            break;
        }
        case Stmt::K::Match: {
            Value subject = eval(s->expr, scope);
            bool matched = false;
            for (const auto& br : s->branches) {
                Value pat = eval(br.first, scope);
                if (valueEquals(subject, pat)) {
                    for (const auto& st : br.second) exec(st, scope);
                    if (retFlag) return;
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                for (const auto& st : s->elseBody) exec(st, scope);
                if (retFlag) return;
            }
            break;
        }
        case Stmt::K::Try: {
            // finally 无论如何都要跑：期间先把「返回」标志收起来，跑完再恢复
            auto runFinally = [&]() {
                if (s->finallyBody.empty()) return;
                bool savedFlag = retFlag;
                Value savedVal = retVal;
                retFlag = false;
                for (const auto& st : s->finallyBody) {
                    exec(st, scope);
                    if (retFlag) break;
                }
                if (!retFlag) { retFlag = savedFlag; retVal = savedVal; }
            };
            try {
                for (const auto& st : s->body) {
                    exec(st, scope);
                    if (retFlag) break;
                }
            } catch (WenError& e) {
                if (s->name.empty()) {
                    runFinally();
                    throw;
                }
                auto d = std::make_shared<Dict>();
                d->items["类型"] = vStr(e.kind);
                d->items["代码"] = vStr(wenErrorCodeOf(e.kind));
                d->items["原因"] = vStr(e.what());
                d->items["行"] = vNum(e.line);
                d->items["列"] = vNum(e.col);
                d->items["文件"] = vStr(filename);
                auto stack = std::make_shared<List>();
                for (const auto& f : e.frames) stack->items.push_back(vStr(f));
                d->items["栈"] = vList(stack);
                scope->set(s->nameSym, vDict(d));
                for (const auto& st : s->elseBody) {
                    exec(st, scope);
                    if (retFlag) break;
                }
            } catch (...) {
                runFinally();
                throw;
            }
            runFinally();
            break;
        }
        case Stmt::K::Func: {
            auto fn = std::make_shared<Function>();
            fn->name = s->name;
            fn->params = s->params;
            fn->paramSyms = s->paramSyms;
            fn->paramDefaults = s->paramDefaults;
            fn->body = s->body;
            // 纯数值函数编译成语句字节码；编译不了就继续走 AST（两条路语义等价）。
            if (!gNoBytecode)
                compileBody(s->body, s->paramSyms, false, globals,
                            fn->code, fn->kconst, fn->slow, fn->vstack);
            fn->closure = scope;
            fn->line = s->line;
            // 纯表达式体：返回 <数字/参数/四则/比较/逻辑> 组成的表达式
            if (s->body.size() == 1 && s->body[0] && s->body[0]->k == Stmt::K::Return &&
                s->body[0]->expr) {
                static std::function<bool(const ExprPtr&, const std::vector<SymId>&)> isPure;
                if (!isPure) {
                    isPure = [](const ExprPtr& e, const std::vector<SymId>& ps) -> bool {
                        if (!e) return false;
                        switch (e->k) {
                            case Expr::K::Num: return true;
                            case Expr::K::Var:
                                for (SymId s2 : ps) if (s2 == e->sym) return true;
                                return false;
                            case Expr::K::Unary:
                                return e->args.size() == 1 && isPure(e->args[0], ps);
                            case Expr::K::Binary: {
                                const string& o = e->op;
                                if (o != "+" && o != "-" && o != "*" && o != "/" && o != "%" &&
                                    o != "<" && o != "<=" && o != ">" && o != ">=" &&
                                    o != "==" && o != "!=" && o != "且" && o != "或") return false;
                                return e->args.size() == 2 && isPure(e->args[0], ps) && isPure(e->args[1], ps);
                            }
                            default: return false;
                        }
                    };
                }
                if (isPure(s->body[0]->expr, s->paramSyms)) {
                    fn->pureExpr = s->body[0]->expr;
                    compilePureExpr(s->body[0]->expr, s->paramSyms, fn->pureOp, fn->pureVal);
                }
            }
            // 识别「返回 参数 ±*/ 常数」这种单表达式函数
            if (s->body.size() == 1 && s->body[0] && s->body[0]->k == Stmt::K::Return &&
                !s->paramSyms.empty()) {
                ExprPtr ex = s->body[0]->expr;
                if (ex && ex->k == Expr::K::Var && ex->sym == s->paramSyms[0]) {
                    fn->simpleOp = 7;
                    fn->simpleParam = ex->sym;
                } else if (ex && ex->k == Expr::K::Num) {
                    fn->simpleOp = 8;
                    fn->simpleConst = ex->num;
                } else if (ex && ex->k == Expr::K::Binary && ex->args.size() == 2) {
                    ExprPtr L = ex->args[0], R = ex->args[1];
                    bool lok = L && L->k == Expr::K::Var && L->sym == s->paramSyms[0];
                    bool rok = R && R->k == Expr::K::Var && R->sym == s->paramSyms[0];
                    bool ln = L && L->k == Expr::K::Num;
                    bool rn = R && R->k == Expr::K::Num;
                    const string& o = ex->op;
                    int code = 0;
                    double cst = 0;
                    if (lok && rn) {
                        cst = R->num;
                        if (o == "+") code = 1;
                        else if (o == "-") code = 2;
                        else if (o == "*") code = 4;
                        else if (o == "/") code = 5;
                    } else if (ln && rok) {
                        cst = L->num;
                        if (o == "-") code = 3;
                        else if (o == "/") code = 6;
                        else if (o == "+") code = 1;
                        else if (o == "*") code = 4;
                    }
                    if (code) { fn->simpleOp = code; fn->simpleConst = cst; fn->simpleParam = s->paramSyms[0]; }
                }
            }
            if (!inLibrary_ && (scope == globals || (scope->parent && scope->parent == globals))) {
                auto owner = symbolOwner.find(s->name);
                if (owner != symbolOwner.end() && owner->second != "用户")
                    throw WenError("库冲突", s->line, 0,
                                   "名字「" + s->name + "」已被库「" +
                                       owner->second + "」占用；请改名");
                symbolOwner[s->name] = "用户";
            }
            if (s->nameSlot >= 0 && !inLibrary_) { globals->fastBind(s->nameSym, s->nameSlot); globals->fastSet(s->nameSlot, vFunc(fn)); }
            scope->set(s->nameSym, vFunc(fn));
            { string pre = "leap|" + s->name + "|"; for (auto it = leapCache.begin(); it != leapCache.end(); ) it = it->first.rfind(pre, 0) == 0 ? leapCache.erase(it) : std::next(it); }
            break;
        }
        case Stmt::K::Return: {
            retVal = s->expr ? eval(s->expr, scope) : vNone();
            retFlag = true;
            return;
        }
        case Stmt::K::Break:
            throw BreakSignal{s->line};
        case Stmt::K::Continue:
            throw ContinueSignal{s->line};
        case Stmt::K::Import: {
            for (const auto& n : s->imports) {
                if (是内置库(n)) 加载模块(n, s->line);
                else 加载外部库(n, s->line);
            }
            break;
        }
        case Stmt::K::Export: {
            if (!inLibrary_)
                rtError(s->line, "「导出」只能写在库里");
            for (const auto& n : s->imports) moduleExports.insert(n);
            break;
        }
        case Stmt::K::ExprStmt: {
            lastValue = eval(s->expr, scope);
            lastWasExpr = true;
            break;
        }
    }
}

Value Interpreter::eval(const ExprPtr& e, const shared_ptr<Scope>& scope) {
    switch (e->k) {
        case Expr::K::Num: return vNum(e->num);
        case Expr::K::Str: return vStr(e->text);
        case Expr::K::Bool: return vBool(e->b);
        case Expr::K::None: return vNone();
        case Expr::K::Var: {
            Value v;
            if (!(e->gslot >= 0 && globals->fastGet(e->gslot, v)) &&
                (!e->sym || !scope->lookup(e->sym, v)))
                undefinedName(e->text, e->line);
            // 零参数函数/内置：名字后面没写括号，也直接调用。
            // 要把它当值传给别人，请用有参数的函数（至少一个参数）。
            if (v.type == VT::Func && v.callable && v.callable->zeroArgCall()) {
                vector<Value> noArgs;
                return callValue(v, noArgs, e->line);
            }
            return v;
        }
        case Expr::K::Unary: {
            Value a = eval(e->args[0], scope);
            if (e->op == "-") return negateValue(a, e->line);
            if (e->op == "+") return vNum(needNum(a, "正号", e->line));
            if (e->op == "非") return vBool(!truthy(a));
            if (e->op == "插值") return vStr(toText(a, false));
            if (e->op == "√") {
                double x = needNum(a, "根号", e->line);
                if (x < 0) rtError(e->line, "根号不能对负数开平方");
                return vNum(wenSqrt(x));
            }
            if (e->op == "°") return vNum(needNum(a, "角度", e->line) * piValue() / 180.0);
            rtError(e->line, "未知一元运算：" + e->op);
        }
        case Expr::K::Binary: {
            if (e->op == "且") {
                Value a = eval(e->args[0], scope);
                if (!truthy(a)) return vBool(false);
                Value b = eval(e->args[1], scope);
                return vBool(truthy(b));
            }
            if (e->op == "或") {
                Value a = eval(e->args[0], scope);
                if (truthy(a)) return vBool(true);
                Value b = eval(e->args[1], scope);
                return vBool(truthy(b));
            }
            Value a = eval(e->args[0], scope);
            Value b = eval(e->args[1], scope);
            return applyBinary(e->op, a, b, e->line);
        }
        case Expr::K::Call: {
            // 指挥("名字", 参数…) 直接派发，省掉“内置指挥 + 目标函数”两层调用。
            if (e->commandCall) {
                Value cmd;
                if (scope->lookup("指挥", cmd) && cmd.type == VT::Func &&
                    std::dynamic_pointer_cast<Builtin>(cmd.callable)) {
                    if (e->args.size() < 2)
                        rtError(e->line, "「指挥」至少需要一个命令名");
                    string name = needStr(eval(e->args[1], scope), "指挥", e->line);
                    Value target;
                    if (!globals->lookup(name, target))
                        rtError(e->line, "指挥层不认识命令「" + name + "」");
                    vector<Value> cargs;
                    cargs.reserve(e->args.size() - 2);
                    for (size_t i = 2; i < e->args.size(); ++i)
                        cargs.push_back(eval(e->args[i], scope));
                    return callValue(target, cargs, e->line);
                }
            }
            // 被调用者要取“原始函数值”，不能再触发零参数自动调用，
            // 否则 零() 会先执行一次再被当成数字调用。
            Value callee;
            if (e->args[0]->k == Expr::K::Var) {
                SymId csid = e->args[0]->sym ? e->args[0]->sym : internSymbol(e->args[0]->text);
                if (!scope->lookup(csid, callee))
                    undefinedName(e->args[0]->text, e->line);
            } else {
                callee = eval(e->args[0], scope);
            }
            vector<Value> args;
            for (size_t i = 1; i < e->args.size(); ++i)
                args.push_back(eval(e->args[i], scope));
            return callValue(callee, args, e->line);
        }
        case Expr::K::Index: {
            Value obj = eval(e->args[0], scope);
            Value idx = eval(e->args[1], scope);
            return getIndex(obj, idx, e->line);
        }
        case Expr::K::Slice: {
            Value obj = eval(e->args[0], scope);
            long long step = 1;
            if (e->args[3]) step = needIndex(eval(e->args[3], scope), "切片步长", e->line);
            if (step == 0) rtError(e->line, "切片步长不能是 0");
            vector<Value> items;
            bool isText = false;
            if ((obj.type == VT::List || obj.type == VT::Set) && obj.list) {
                items = obj.list->items;
            } else if (obj.type == VT::Str) {
                for (const auto& ch : utf8Chars(obj.str)) items.push_back(vStr(ch));
                isText = true;
            } else {
                rtError(e->line, "切片只能用在列表、集合或文本上，收到" + typeName(obj));
            }
            long long n = (long long)items.size();
            bool hasStart = (bool)e->args[1];
            bool hasStop = (bool)e->args[2];
            long long start = hasStart ? 0 : (step > 0 ? 0 : n - 1);
            long long stop = hasStop ? 0 : (step > 0 ? n : -1);
            if (hasStart) start = needIndex(eval(e->args[1], scope), "切片起点", e->line);
            if (hasStop) stop = needIndex(eval(e->args[2], scope), "切片终点", e->line);
            if (hasStart && start < 0) start += n;
            if (hasStop && stop < 0) stop += n;
            if (step > 0) {
                start = std::max(0LL, std::min(start, n));
                stop = std::max(0LL, std::min(stop, n));
            } else {
                start = std::max(-1LL, std::min(start, n - 1));
                stop = std::max(-1LL, std::min(stop, n - 1));
            }
            auto out = std::make_shared<List>();
            for (long long i = start; step > 0 ? i < stop : i > stop; i += step)
                out->items.push_back(items[(size_t)i]);
            if (isText) {
                string s;
                for (const auto& v : out->items) s += v.str;
                return vStr(s);
            }
            return vList(out);
        }
        case Expr::K::List: {
            auto l = std::make_shared<List>();
            for (const auto& a : e->args) l->items.push_back(eval(a, scope));
            return vList(l);
        }
        case Expr::K::Dict: {
            auto d = std::make_shared<Dict>();
            for (const auto& p : e->pairs) {
                Value k = eval(p.first, scope);
                if (k.type != VT::Str)
                    rtError(e->line, "字典的键必须是文本（C++ 版 v0.2 限制）");
                d->items[k.str] = eval(p.second, scope);
            }
            return vDict(d);
        }
    }
    rtError(e->line, "未知表达式节点");
}

static bool cacheableBuiltin(const string& name) {
    auto it = functionModules().find(name);
    if (it == functionModules().end()) return false;
    const string& lib = it->second;
    if (lib == "数学库" || lib == "图形库" || lib == "物理库") return true;
    if (lib == "概率库")
        return name != "随机抽样" && name != "洗牌" && name != "加权选择";
    return false;
}

static string accelKey(const string& name, const vector<Value>& args) {
    string key = name;
    for (const auto& v : args) {
        string s = toText(v, true);
        key += "|" + std::to_string(s.size()) + ":" + s;
    }
    return key;
}

Value Interpreter::callValue(const Value& callee, vector<Value>& args, int line) {
    if (callee.type != VT::Func || !callee.callable)
        rtError(line, "这个值不能调用：" + typeName(callee));
    if (!accelEnabled && !leapAuto && !memoryAuto)
        return callee.callable->call(*this, args, line);
    if (accelEnabled && callee.callable->cacheable()) {
        string key = accelKey(callee.callable->name, args);
        auto it = accelCache.find(key);
        if (it != accelCache.end()) {
            ++accelHits;
            return it->second;
        }
        Value out = callee.callable->call(*this, args, line);
        if (out.type == VT::Num || out.type == VT::Str || out.type == VT::Bool ||
            out.type == VT::None) {
            if (accelCache.size() >= 200000) accelCache.clear();
            accelCache[key] = out;
        }
        return out;
    }
    if (leapAuto) {
        string memo = callee.callable->memoKey();
        if (!memo.empty()) {
            string key = "leap|" + memo + accelKey("", args);
            auto it = leapCache.find(key);
            if (it != leapCache.end()) {
                ++leapHits;
                return it->second;
            }
            ++leapMisses;
            Value out = callee.callable->call(*this, args, line);
            if (out.type == VT::Num || out.type == VT::Str || out.type == VT::Bool ||
                out.type == VT::None) {
                if (leapLimit && leapCache.size() >= leapLimit) leapCache.clear();
                leapCache[key] = out;
            }
            return out;
        }
    }
    if (memoryAuto && callee.type == VT::Func) {
        string memo = callee.callable->memoKey();
        if (!memo.empty()) {
            string key = "auto|" + memo + accelKey("", args);
            auto it = memoryStore.find(key);
            if (it != memoryStore.end()) {
                ++memoryHits;
                return it->second;
            }
            auto cit = memoryCompressed.find(key);
            if (cit != memoryCompressed.end()) {
                string raw = decompressMemoryText(cit->second, line);
                JsonReader reader(raw, line);
                Value v = reader.parse();
                memoryPut(key, false, v, line);
                memoryCompressed.erase(cit);
                memoryOrigSize.erase(key);
                ++memoryHits;
                return v;
            }
            Value out = callee.callable->call(*this, args, line);
            if (out.type == VT::Num || out.type == VT::Str || out.type == VT::Bool ||
                out.type == VT::None) {
                if (memoryCompress && isPulled(key)) {
                    string raw = jsonDump(out, line);
                    buildMemoryDict(raw);
                    memoryOrigSize[key] = raw.size();
                    memoryCompressed[key] = compressMemoryText(raw);
                } else {
                    memoryPut(key, false, out, line);
                }
            }
            return out;
        }
    }
    return callee.callable->call(*this, args, line);
}

void Interpreter::assignVarSym(SymId sym, Value val, const shared_ptr<Scope>& scope,
                               bool knownBuiltin) {
    // 内建名不能被函数里的普通赋值改掉：`值`、`长度` 这些名字同时是内建函数，
    // 直接 assign 会写进全局的内建槽，递归时所有层共用一个变量，循环会莫名退出。
    // 函数里碰到内建名就退化成局部变量（要改全局请显式用别的名字）。
    // 名字现在绑定的是一个函数（内建或用户函数）时，也不能在函数里被普通赋值改掉：
    // 那会写到全局上，递归时所有层共用，还会把函数本身顶掉。
    // knownBuiltin 由字节码编译期算好（内建表启动后就不再变），省掉一次 690 项查表。
    // 顶层作用域没有「退化成本地」这一说，直接按原语义写。
    if (scope.get() == globals.get()) {
        if (!scope->assign(sym, val)) scope->set(sym, std::move(val));
        return;
    }
    int r = scope->assignOnce(sym, val, knownBuiltin);
    if (r != 1) scope->set(sym, std::move(val));
}

void Interpreter::assignTarget(const ExprPtr& target, Value val,
                               const shared_ptr<Scope>& scope) {
    if (target->k == Expr::K::Var) {
        if (!target->sym) rtError(target->line, "内部符号缺失：" + target->text);
        if (target->gslot >= 0) {
            globals->fastBind(target->sym, target->gslot);
            if (val.type != VT::Num && val.type != VT::Int && val.type != VT::Bool)
                scope->set(target->sym, val);
            globals->fastSet(target->gslot, std::move(val));
        } else {
            assignVarSym(target->sym, std::move(val), scope,
                          gBuiltinArity.count(target->text) != 0);
        }
        return;
    }
    if (target->k == Expr::K::Index) {
        Value obj = eval(target->args[0], scope);
        Value idx = eval(target->args[1], scope);
        setIndex(obj, idx, val, target->line);
        return;
    }
    if (target->k == Expr::K::Slice)
        rtError(target->line, "切片不能直接赋值；请用循环或重建列表");
    rtError(target->line, "赋值左边只能是变量或索引");
}

Value Interpreter::getIndex(const Value& obj, const Value& idx, int line) {
    if (obj.type == VT::List && obj.list) {
        long long i = needIndex(idx, "列表下标", line);
        long long n = (long long)obj.list->items.size();
        if (i < 0) i += n;
        if (i < 0 || i >= n)
            rtError(line, "列表下标越界：" + std::to_string(i) +
                          "（长度 " + std::to_string(n) + "）");
        return obj.list->items[(size_t)i];
    }
    if (obj.type == VT::Str) {
        auto chars = utf8Chars(obj.str);
        long long i = needIndex(idx, "文本下标", line);
        long long n = (long long)chars.size();
        if (i < 0) i += n;
        if (i < 0 || i >= n)
            rtError(line, "文本下标越界：" + std::to_string(i));
        return vStr(chars[(size_t)i]);
    }
    if (obj.type == VT::Dict && obj.dict) {
        if (idx.type != VT::Str) rtError(line, "字典的键必须是文本");
        auto it = obj.dict->items.find(idx.str);
        if (it == obj.dict->items.end())
            rtError(line, "字典里没有键「" + idx.str + "」");
        return it->second;
    }
    if (obj.type == VT::Range) {
        double span = (obj.rstop - obj.rstart) / obj.rstep;
        long long n = span <= 0 ? 0 : (long long)std::ceil(span - 1e-12);
        long long i = needIndex(idx, "范围下标", line);
        if (i < 0) i += n;
        if (i < 0 || i >= n) rtError(line, "范围下标越界");
        return vNum(obj.rstart + (double)i * obj.rstep);
    }
    rtError(line, typeName(obj) + "不能用 [ ] 取下标");
}

void Interpreter::setIndex(Value& obj, const Value& idx, const Value& val, int line) {
    if (obj.type == VT::List && obj.list) {
        long long i = needIndex(idx, "列表下标", line);
        long long n = (long long)obj.list->items.size();
        if (i < 0) i += n;
        if (i < 0 || i >= n)
            rtError(line, "列表下标越界：" + std::to_string(i));
        obj.list->items[(size_t)i] = val;
        return;
    }
    if (obj.type == VT::Dict && obj.dict) {
        if (idx.type != VT::Str) rtError(line, "字典的键必须是文本");
        obj.dict->items[idx.str] = val;
        return;
    }
    if (obj.type == VT::Str)
        rtError(line, "文本不能修改");
    rtError(line, typeName(obj) + "不能用 [ ] 赋值");
}

// 函数调用：返回信号、循环外中断、错误调用栈
// 函数帧池：每次调用都 make_shared 一个作用域太亏，这里复用同一个对象。
// 收回前检查 use_count()==1——只要有别处还引用这个帧（闭包捕获、嵌套函数带走），
// 就原地丢弃、不进池，所以复用永远不会让两个调用共用一份局部变量。
static thread_local std::vector<shared_ptr<Scope>> gFramePool;

static shared_ptr<Scope> takeFrame(const shared_ptr<Scope>& closure) {
    auto& pool = gFramePool;
    shared_ptr<Scope> s;
    if (pool.empty()) {
        s = std::make_shared<Scope>(closure);
    } else {
        s = std::move(pool.back());
        pool.pop_back();
        s->svars.clear();
        s->idVars.clear();
        s->vars.clear();
        s->fast.clear();
        s->fastDefined.clear();
        s->idSlot.clear();
        s->parent = closure;
    }
    s->trackNames = false;
    s->smallMode = true;
    return s;
}

// 帧的唯一持有者。收回条件看 use_count()==1：只有「除了它自己没人再引用」才进池。
// 注意必须由它独占那一份 shared_ptr——如果外面还留一个局部变量指着，计数恒为 2，
// 池就永远不会命中（上一版就是这么白忙一场的）。
struct FrameHold {
    shared_ptr<Scope> s;
    explicit FrameHold(shared_ptr<Scope> x) : s(std::move(x)) {}
    ~FrameHold() {
        if (s && s.use_count() == 1 && gFramePool.size() < 64) {
            s->svars.clear();      // 容量留着，下次直接用
            s->parent.reset();     // 别把闭包链一直挂住
            gFramePool.push_back(std::move(s));
        }
    }
};

Value Function::call(Interpreter& vm, vector<Value>& args, int callLine) {
    return callSpan(vm, args.data(), (int)args.size(), callLine);
}

Value Function::callSpan(Interpreter& vm, const Value* a, int n, int callLine) {
    if (vm.callDepth >= vm.maxCallDepth)
        throw WenError("运行时错误", callLine, 0,
                       "递归过深：超过 " + std::to_string(vm.maxCallDepth) + " 层，可能栈溢出");
    struct DepthGuard {
        Interpreter& vm;
        explicit DepthGuard(Interpreter& v) : vm(v) { ++vm.callDepth; }
        ~DepthGuard() { --vm.callDepth; }
    } depthGuard(vm);
    if (vm.callStats && !name.empty()) ++vm.callCounts[name];
    size_t argc = (size_t)n;
    if (argc > params.size()) {
        throw WenError("运行时错误", callLine, 0,
                       "函数「" + name + "」最多需要 " + std::to_string(params.size()) +
                       " 个参数，收到 " + std::to_string(argc) + " 个");
    }
    // 单表达式快路径：不进帧、不分配作用域，直接算（放在建帧之前，省一次分配）
    if (simpleOp && argc == 1 && a[0].type == VT::Num && params.size() == 1) {
        double x = a[0].num;
        switch (simpleOp) {
            case 1: return vNum(x + simpleConst);
            case 2: return vNum(x - simpleConst);
            case 3: return vNum(simpleConst - x);
            case 4: return vNum(x * simpleConst);
            case 5: return vNum(simpleConst == 0 ? x : x / simpleConst);
            case 6: return vNum(x == 0 ? 0 : simpleConst / x);
            case 7: return a[0];
            case 8: return vNum(simpleConst);
            default: break;
        }
    }
    FrameHold frame(takeFrame(closure));
    Scope& S = *frame.s;
    // 形参和局部通常只有几个：一次留够，省掉 push_back 扩容与 200 字节搬运
    if (S.svars.capacity() < argc + params.size() + 4)
        S.svars.reserve(argc + params.size() + 4);
    for (size_t i = 0; i < argc; ++i) S.set(paramSyms[i], a[i]);
    for (size_t i = argc; i < params.size(); ++i) {
        if (i >= paramDefaults.size() || !paramDefaults[i])
            throw WenError("运行时错误", callLine, 0,
                           "函数「" + name + "」缺少参数「" + params[i] + "」");
        S.set(paramSyms[i], vm.eval(paramDefaults[i], frame.s));
    }
    bool savedFlag = vm.retFlag;
    Value savedVal;
    // 绝大多数调用进来的时候调用方并没有挂起的返回值：这时一个字节都不用抄
    if (savedFlag) savedVal = vm.retVal;
    vm.retFlag = false;
    // 被调函数自己的「返回」标记不许漏到调用方（否则外层循环会误以为返回了）
    struct VmRetGuard {
        Interpreter& vm;
        int old;
        explicit VmRetGuard(Interpreter& v) : vm(v), old(v.vmRetFlag) { vm.vmRetFlag = 0; }
        ~VmRetGuard() { vm.vmRetFlag = old; }
    } vmRetGuard(vm);
    Value result = vNone();
    try {
        if (!code.empty()) {
            // 有字节码就跑字节码：不再逐条语句 switch + 递归求值
            result = vm.runCode(code, kconst, slow, vstack, frame.s);
        } else {
            for (const auto& st : body) {
                vm.exec(st, frame.s);
                if (vm.retFlag) break;
            }
            if (vm.retFlag) result = vm.retVal;
        }
    } catch (BreakSignal&) {
        vm.retFlag = savedFlag; vm.retVal = savedVal;
        throw WenError("运行时错误", callLine, 0, "「中断」只能用在循环里");
    } catch (ContinueSignal&) {
        vm.retFlag = savedFlag; vm.retVal = savedVal;
        throw WenError("运行时错误", callLine, 0, "「继续」只能用在循环里");
    } catch (WenError& e) {
        vm.retFlag = savedFlag; vm.retVal = savedVal;
        if (e.frames.size() < 50)
            e.frames.push_back("在「" + name + "」（第 " +
                               std::to_string(callLine) + " 行调用）");
        throw;
    }
    vm.retFlag = savedFlag;
    if (savedFlag) vm.retVal = savedVal;
    return result;
}

Value Builtin::call(Interpreter& vm, vector<Value>& args, int line) {
    if (vm.callStats && !name.empty()) ++vm.callCounts[name];
    if (!core && !moduleLoaded) {
        string lib = module;
        if (!moduleKnown) {
            auto mit = functionModules().find(name);
            if (mit != functionModules().end()) lib = mit->second;
        }
        if (!lib.empty() && !vm.loadedModules.count(lib))
            throw WenError("运行时错误", line, 0,
                           "「" + name + "」属于「" + lib +
                           "」，请先在使用前写「依赖 " + lib + "」");
    }
    if ((int)args.size() < minArgs ||
        (maxArgs >= 0 && (int)args.size() > maxArgs)) {
        string need = maxArgs < 0
                          ? ("至少 " + std::to_string(minArgs))
                          : (std::to_string(minArgs) + " 到 " + std::to_string(maxArgs));
        throw WenError("运行时错误", line, 0,
                       "「" + name + "」需要 " + need + " 个参数，收到 " +
                       std::to_string(args.size()) + " 个");
    }
    try {
        return fn(vm, args, line);
    } catch (WenError&) {
        throw;
    } catch (std::exception& e) {
        throw WenError("运行时错误", line, 0,
                       "内置函数「" + name + "」出错：" + e.what());
    }
}

// ============================================================
// 10. 内置函数与数学库
// ============================================================

static int processSaveBlocks(const string& src, bool write, string& out,
                             vector<WenError>& errors);

static string xmlEscape(const string& s) {
    string out;
    for (char c : s) {
        switch (c) {
            case '&': out += "&amp;"; break;
            case '<': out += "&lt;"; break;
            case '>': out += "&gt;"; break;
            case '"': out += "&quot;"; break;
            case '\'': out += "&apos;"; break;
            default: out += c; break;
        }
    }
    return out;
}

static void ensureParentDirectory(const string& path) {
    fs::path p = fs::u8path(path);
    if (!p.has_parent_path()) return;
    std::error_code ec;
    fs::create_directories(p.parent_path(), ec);
    if (ec) throw IoError("无法创建目录：" + p.parent_path().u8string());
}

static string svgStart(const string& title, int w, int h) {
    std::ostringstream o;
    o << "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"" << w
      << "\" height=\"" << h << "\" viewBox=\"0 0 " << w << " " << h << "\">\n";
    o << "<rect width=\"100%\" height=\"100%\" fill=\"#ffffff\"/>\n";
    o << "<text x=\"" << w / 2
      << "\" y=\"30\" text-anchor=\"middle\" font-size=\"20\" "
         "font-family=\"Microsoft YaHei, sans-serif\" fill=\"#222\">"
      << xmlEscape(title) << "</text>\n";
    return o.str();
}

static string svgEnd() { return "</svg>\n"; }

static double combCount(long long n, long long k) {
    if (n < 0 || k < 0 || k > n) return 0;
    if (k > n - k) k = n - k;
    double r = 1;
    for (long long i = 1; i <= k; ++i) r = r * (double)(n - k + i) / (double)i;
    return r;
}

// 概率库共用：权重校验/归一化；随机抽样和洗牌共用洗牌逻辑。
static vector<double> normalizedWeights(const shared_ptr<List>& w, const string& where, int line) {
    if (w->items.empty())
        throw WenError("运行时错误", line, 0, where + "的权重列表不能为空");
    vector<double> out;
    double sum = 0;
    for (const auto& v : w->items) {
        double x = needNum(v, where, line);
        if (x < 0) throw WenError("运行时错误", line, 0, where + "的权重不能为负");
        out.push_back(x);
        sum += x;
    }
    if (sum <= 0)
        throw WenError("运行时错误", line, 0, where + "的权重总和必须大于 0");
    for (double& x : out) x /= sum;
    return out;
}

static vector<Value> shuffledValues(const vector<Value>& items, std::mt19937& rng) {
    vector<Value> out = items;
    std::shuffle(out.begin(), out.end(), rng);
    return out;
}

static void writeRenderSvg(const string& path, const string& svg, int line) {
    try {
        ensureParentDirectory(path);
        writeWholeFile(path, svg, false);
    } catch (IoError& e) {
        throw WenError("文件错误", line, 0, e.what());
    }
}

// ============================================================
// 渲染库辅助：面、面积、均匀布点、SVG 片段（纯自研，不依赖外部库）
// ============================================================
struct RenderPoint {
    double x = 0;
    double y = 0;
};

static vector<RenderPoint> renderVerticesFromList(const Value& v, int line) {
    auto l = needList(v, "顶点列表", line);
    vector<RenderPoint> pts;
    for (const auto& item : l->items) {
        auto p = needList(item, "顶点", line);
        if (p->items.size() == 2) {
            pts.push_back({needNum(p->items[0], "顶点 x", line),
                           needNum(p->items[1], "顶点 y", line)});
        } else if (p->items.size() == 3) {
            // 三维顶点在 2D 后端里做默认透视投影；深度排序请用「渲染三维」。
            double x = needNum(p->items[0], "顶点 x", line);
            double y = needNum(p->items[1], "顶点 y", line);
            double z = needNum(p->items[2], "顶点 z", line);
            double zz = z + 8.0;
            if (zz <= 0.1) throw WenError("运行时错误", line, 0, "三维顶点在相机后面");
            pts.push_back({400.0 + x * 520.0 / zz, 300.0 - y * 520.0 / zz});
        } else {
            throw WenError("运行时错误", line, 0, "顶点必须是 [x, y] 或 [x, y, z]");
        }
    }
    if (pts.size() < 3)
        throw WenError("运行时错误", line, 0, "面至少需要 3 个顶点");
    return pts;
}

static vector<RenderPoint> renderFaceVertices(const Value& v, int line) {
    auto d = needDict(v, "面", line);
    auto it = d->items.find("顶点");
    if (it == d->items.end())
        throw WenError("运行时错误", line, 0, "这个面没有顶点；请用「新建面」创建");
    return renderVerticesFromList(it->second, line);
}

static double renderPolygonArea(const vector<RenderPoint>& p) {
    double sum = 0;
    for (size_t i = 0; i < p.size(); ++i) {
        const auto& a = p[i];
        const auto& b = p[(i + 1) % p.size()];
        sum += a.x * b.y - b.x * a.y;
    }
    return std::fabs(sum) * 0.5;
}

static RenderPoint renderCentroid(const vector<RenderPoint>& p) {
    double a2 = 0, cx = 0, cy = 0;
    for (size_t i = 0; i < p.size(); ++i) {
        const auto& a = p[i];
        const auto& b = p[(i + 1) % p.size()];
        double cross = a.x * b.y - b.x * a.y;
        a2 += cross;
        cx += (a.x + b.x) * cross;
        cy += (a.y + b.y) * cross;
    }
    if (std::fabs(a2) < 1e-12) {
        double sx = 0, sy = 0;
        for (const auto& q : p) {
            sx += q.x;
            sy += q.y;
        }
        return {sx / (double)p.size(), sy / (double)p.size()};
    }
    return {cx / (3.0 * a2), cy / (3.0 * a2)};
}

static Value makeFaceValue(const vector<RenderPoint>& pts) {
    auto d = std::make_shared<Dict>();
    auto vertices = std::make_shared<List>();
    for (const auto& p : pts) {
        auto one = std::make_shared<List>();
        one->items.push_back(vNum(p.x));
        one->items.push_back(vNum(p.y));
        vertices->items.push_back(vList(one));
    }
    d->items["顶点"] = vList(vertices);
    d->items["面积"] = vNum(renderPolygonArea(pts));
    auto c = renderCentroid(pts);
    auto center = std::make_shared<List>();
    center->items.push_back(vNum(c.x));
    center->items.push_back(vNum(c.y));
    d->items["中心"] = vList(center);
    double minx = pts[0].x, maxx = pts[0].x, miny = pts[0].y, maxy = pts[0].y;
    for (const auto& p : pts) {
        minx = std::min(minx, p.x);
        maxx = std::max(maxx, p.x);
        miny = std::min(miny, p.y);
        maxy = std::max(maxy, p.y);
    }
    auto box = std::make_shared<List>();
    box->items.push_back(vNum(minx));
    box->items.push_back(vNum(miny));
    box->items.push_back(vNum(maxx));
    box->items.push_back(vNum(maxy));
    d->items["边界"] = vList(box);
    return vDict(d);
}

static Value renderPointsValue(const vector<RenderPoint>& pts) {
    auto vertices = std::make_shared<List>();
    for (const auto& p : pts) {
        auto one = std::make_shared<List>();
        one->items.push_back(vNum(p.x));
        one->items.push_back(vNum(p.y));
        vertices->items.push_back(vList(one));
    }
    return vList(vertices);
}

struct Render3Point {
    double x = 0, y = 0, z = 0;
};

static vector<Render3Point> render3Vertices(const Value& v, int line) {
    auto l = needList(v, "三维顶点", line);
    vector<Render3Point> pts;
    for (const auto& item : l->items) {
        auto p = needList(item, "三维顶点", line);
        if (p->items.size() != 3)
            throw WenError("运行时错误", line, 0, "三维顶点必须是 [x, y, z]");
        pts.push_back({needNum(p->items[0], "x", line),
                       needNum(p->items[1], "y", line),
                       needNum(p->items[2], "z", line)});
    }
    if (pts.size() < 3)
        throw WenError("运行时错误", line, 0, "三维面至少需要 3 个顶点");
    return pts;
}

static uint64_t readFixed(const vector<unsigned char>& b, size_t off, int width, bool big) {
    if (off + (size_t)width > b.size()) throw std::out_of_range("buffer");
    uint64_t v = 0;
    for (int i = 0; i < width; ++i) {
        int idx = big ? (width - 1 - i) : i;
        v |= (uint64_t)b[off + (size_t)idx] << (8 * i);
    }
    return v;
}
static void writeFixed(vector<unsigned char>& b, size_t off, int width, uint64_t v, bool big) {
    if (off + (size_t)width > b.size()) throw std::out_of_range("buffer");
    for (int i = 0; i < width; ++i) {
        int idx = big ? (width - 1 - i) : i;
        b[off + (size_t)idx] = (unsigned char)((v >> (8 * i)) & 255);
    }
}
