static shared_ptr<Dict> vpDict(const Value& v, int line) {
    auto d = needDict(v, "视口", line);
    if (!d->items.count("像素")) throw WenError("运行时错误", line, 0, "不是视口");
    return d;
}
static vector<unsigned char>& vpPixels(const shared_ptr<Dict>& d) {
    return *d->items.at("像素").bytes;
}
static void vpPut(const shared_ptr<Dict>& d, int x, int y, int c) {
    int w = (int)needNum(d->items.at("宽"), "视口", 0);
    int h = (int)needNum(d->items.at("高"), "视口", 0);
    if (x < 0 || y < 0 || x >= w || y >= h) return;
    auto& p = vpPixels(d);
    size_t i = ((size_t)y * (size_t)w + (size_t)x) * 3;
    p[i] = (unsigned char)((c >> 16) & 255);
    p[i + 1] = (unsigned char)((c >> 8) & 255);
    p[i + 2] = (unsigned char)(c & 255);
}
static void vpPutZ(const shared_ptr<Dict>& d, int x, int y, double z, int c) {
    int w = (int)needNum(d->items.at("宽"), "视口", 0);
    int h = (int)needNum(d->items.at("高"), "视口", 0);
    if (x < 0 || y < 0 || x >= w || y >= h) return;
    auto dp = needList(d->items.at("深度"), "视口", 0);
    size_t i = (size_t)y * (size_t)w + (size_t)x;
    if (z >= needNum(dp->items[i], "视口", 0)) return;
    dp->items[i] = vNum(z);
    vpPut(d, x, y, c);
}
static Value makeLayout(const string& spec, int line, bool packed = false) {
    auto d = std::make_shared<Dict>();
    auto fields = std::make_shared<List>();
    size_t offset = 0;
    int maxAlign = 1;
    std::istringstream ss(spec);
    string item;
    while (std::getline(ss, item, ',')) {
        size_t b = item.find_first_not_of(" \t");
        if (b == string::npos) continue;
        item = item.substr(b);
        size_t sp = item.find_last_of(" \t");
        if (sp == string::npos)
            throw WenError("运行时错误", line, 0, "布局字段要写成「类型 名字」：" + item);
        string type = lowerAscii(item.substr(0, sp));
        string name = item.substr(sp + 1);
        int width = 0;
        bool sign = false, isFloat = false;
        if (type == "u8") width = 1;
        else if (type == "i8") { width = 1; sign = true; }
        else if (type == "u16") width = 2;
        else if (type == "i16") { width = 2; sign = true; }
        else if (type == "u32") width = 4;
        else if (type == "i32") { width = 4; sign = true; }
        else if (type == "u64") width = 8;
        else if (type == "i64") { width = 8; sign = true; }
        else if (type == "f32") { width = 4; isFloat = true; }
        else if (type == "f64") { width = 8; isFloat = true; }
        else throw WenError("运行时错误", line, 0, "布局不认识的类型：" + type);
        maxAlign = std::max(maxAlign, width);
        if (!packed) offset = (offset + (size_t)width - 1) / (size_t)width * (size_t)width;
        auto f = std::make_shared<Dict>();
        f->items["名字"] = vStr(name);
        f->items["类型"] = vStr(type);
        f->items["偏移"] = vNum((double)offset);
        f->items["大小"] = vNum(width);
        f->items["有符号"] = vBool(sign);
        f->items["浮点"] = vBool(isFloat);
        fields->items.push_back(vDict(f));
        offset += width;
    }
    if (!packed) offset = (offset + (size_t)maxAlign - 1) / (size_t)maxAlign * (size_t)maxAlign;
    d->items["大小"] = vNum((double)offset);
    d->items["对齐"] = vNum(packed ? 1 : maxAlign);
    d->items["紧凑"] = vBool(packed);
    d->items["字段"] = vList(fields);
    return vDict(d);
}
static Value make3Face(const vector<Render3Point>& pts, const string& color) {
    auto d = std::make_shared<Dict>();
    d->items["类型"] = vStr("三维面");
    auto vs = std::make_shared<List>();
    for (const auto& p : pts) {
        auto one = std::make_shared<List>();
        one->items.push_back(vNum(p.x));
        one->items.push_back(vNum(p.y));
        one->items.push_back(vNum(p.z));
        vs->items.push_back(vList(one));
    }
    d->items["顶点"] = vList(vs);
    d->items["颜色"] = vStr(color);
    return vDict(d);
}

static void collect3Faces(const Value& v, vector<Value>& out, int line) {
    if (v.type == VT::Dict && v.dict) {
        auto it = v.dict->items.find("类型");
        if (it != v.dict->items.end() && toText(it->second) == "三维面") {
            out.push_back(v);
            return;
        }
        throw WenError("运行时错误", line, 0, "不是三维面");
    }
    if (v.type == VT::List && v.list) {
        for (const auto& item : v.list->items) collect3Faces(item, out, line);
        return;
    }
    throw WenError("运行时错误", line, 0, "需要三维面或三维面列表");
}

static Value make3Box(double cx, double cy, double cz, double s, const string& color) {
    double h = s * 0.5;
    auto list = std::make_shared<List>();
    auto face = [&](std::initializer_list<Render3Point> pts) {
        list->items.push_back(make3Face(vector<Render3Point>(pts), color));
    };
    face({{cx-h,cy-h,cz-h},{cx+h,cy-h,cz-h},{cx+h,cy+h,cz-h},{cx-h,cy+h,cz-h}});
    face({{cx-h,cy-h,cz+h},{cx-h,cy+h,cz+h},{cx+h,cy+h,cz+h},{cx+h,cy-h,cz+h}});
    face({{cx-h,cy-h,cz-h},{cx-h,cy+h,cz-h},{cx-h,cy+h,cz+h},{cx-h,cy-h,cz+h}});
    face({{cx+h,cy-h,cz-h},{cx+h,cy-h,cz+h},{cx+h,cy+h,cz+h},{cx+h,cy+h,cz-h}});
    face({{cx-h,cy-h,cz-h},{cx-h,cy-h,cz+h},{cx+h,cy-h,cz+h},{cx+h,cy-h,cz-h}});
    face({{cx-h,cy+h,cz-h},{cx+h,cy+h,cz-h},{cx+h,cy+h,cz+h},{cx-h,cy+h,cz+h}});
    return vList(list);
}

static Value make3Sphere(double cx, double cy, double cz, double r, int segs,
                         const string& color) {
    if (segs < 3) segs = 3;
    if (segs > 64) segs = 64;
    auto list = std::make_shared<List>();
    const double pi = piValue();
    auto at = [&](int i, int j) {
        double th = pi * (double)i / segs;
        double ph = 2.0 * pi * (double)j / segs;
        return Render3Point{cx + r * std::sin(th) * std::cos(ph),
                            cy + r * std::cos(th),
                            cz + r * std::sin(th) * std::sin(ph)};
    };
    for (int i = 0; i < segs; ++i)
        for (int j = 0; j < segs; ++j) {
            auto a = at(i, j), b = at(i + 1, j), c = at(i + 1, j + 1), d = at(i, j + 1);
            list->items.push_back(make3Face({a, b, c, d}, color));
        }
    return vList(list);
}
static bool renderPointInside(const vector<RenderPoint>& poly, double x, double y) {
    bool inside = false;
    for (size_t i = 0, j = poly.size() - 1; i < poly.size(); j = i++) {
        double xi = poly[i].x, yi = poly[i].y;
        double xj = poly[j].x, yj = poly[j].y;
        bool cross = ((yi > y) != (yj > y)) &&
                     (x < (xj - xi) * (y - yi) / (yj - yi + 1e-300) + xi);
        if (cross) inside = !inside;
    }
    return inside;
}

static double renderHalton(int index, int base) {
    double f = 1, r = 0;
    while (index > 0) {
        f /= base;
        r += f * (index % base);
        index /= base;
    }
    return r;
}

// 在面内均匀布 N 个点：Halton 候选 + 最远点贪心，视觉上对等、不堆在一起。
static vector<RenderPoint> renderDistribute(const vector<RenderPoint>& poly, int n,
                                            double minx, double miny,
                                            double maxx, double maxy, int line) {
    vector<RenderPoint> cand;
    int tries = std::max(n * 150, 800);
    for (int i = 1; i <= tries; ++i) {
        double x = minx + renderHalton(i, 2) * (maxx - minx);
        double y = miny + renderHalton(i, 3) * (maxy - miny);
        if (renderPointInside(poly, x, y)) cand.push_back({x, y});
    }
    if ((int)cand.size() < n)
        throw WenError("运行时错误", line, 0,
                       "面太小，放不下 " + std::to_string(n) + " 个涂鸦");
    vector<char> used(cand.size(), 0);
    vector<RenderPoint> chosen;
    chosen.push_back(cand[0]);
    used[0] = 1;
    while ((int)chosen.size() < n) {
        int best = -1;
        double bestDist = -1;
        for (size_t i = 0; i < cand.size(); ++i) {
            if (used[i]) continue;
            double minD = std::numeric_limits<double>::max();
            for (const auto& c : chosen) {
                double dx = cand[i].x - c.x, dy = cand[i].y - c.y;
                minD = std::min(minD, dx * dx + dy * dy);
            }
            if (minD > bestDist) {
                bestDist = minD;
                best = (int)i;
            }
        }
        if (best < 0) break;
        used[best] = 1;
        chosen.push_back(cand[best]);
    }
    return chosen;
}

static string cppFloatLit(double v) {
    std::ostringstream s;
    s << std::setprecision(8) << v;
    string t = s.str();
    if (t.find('.') == string::npos && t.find('e') == string::npos &&
        t.find('E') == string::npos)
        t += ".0";
    return t;
}

static std::array<float, 3> renderHexRgb(const string& c) {    std::array<float, 3> rgb{0.2f, 0.2f, 0.2f};
    if (c.size() == 7 && c[0] == '#') {
        auto hex = [&](int i) {
            return (float)std::strtol(c.substr(i, 2).c_str(), nullptr, 16) / 255.0f;
        };
        rgb = {hex(1), hex(3), hex(5)};
    }
    return rgb;
}

static string renderColor(const string& c, const string& fallback) {    if (c.size() == 4 || c.size() == 7) {
        if (c[0] == '#') {
            bool ok = true;
            for (size_t i = 1; i < c.size(); ++i)
                if (!std::isxdigit((unsigned char)c[i])) ok = false;
            if (ok) return c;
        }
    }
    bool letters = !c.empty();
    for (unsigned char ch : c)
        if (!std::isalpha(ch)) letters = false;
    if (letters) return c;
    return fallback;
}

static string renderPointsAttr(const vector<RenderPoint>& pts) {
    std::ostringstream o;
    for (size_t i = 0; i < pts.size(); ++i) {
        if (i) o << " ";
        o << std::setprecision(6) << pts[i].x << "," << pts[i].y;
    }
    return o.str();
}

static string renderMotif(const string& pattern, double x, double y, double r) {
    std::ostringstream o;
    o << std::setprecision(4);
    if (pattern == "星") {
        o << "<polygon points=\"";
        for (int k = 0; k < 10; ++k) {
            double ang = -piValue() / 2.0 + k * piValue() / 5.0;
            double rr = (k % 2 == 0) ? r : r * 0.42;
            if (k) o << " ";
            o << (x + std::cos(ang) * rr) << "," << (y + std::sin(ang) * rr);
        }
        o << "\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"1.2\"/>\n";
    } else if (pattern == "波纹") {
        for (int k = 1; k <= 3; ++k)
            o << "<circle cx=\"" << x << "\" cy=\"" << y << "\" r=\"" << (r * k / 3.0)
              << "\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"1\"/>\n";
    } else if (pattern == "螺旋") {
        o << "<polyline points=\"";
        const int steps = 48;
        for (int k = 0; k <= steps; ++k) {
            double t = (double)k / steps;
            double ang = t * 5.0 * piValue();
            double rr = r * (0.15 + 0.85 * t);
            if (k) o << " ";
            o << (x + std::cos(ang) * rr) << "," << (y + std::sin(ang) * rr);
        }
        o << "\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"1.1\"/>\n";
    } else {
        o << "<circle cx=\"" << x << "\" cy=\"" << y << "\" r=\"" << r
          << "\" fill=\"none\" stroke=\"#2b2b2b\" stroke-width=\"1.2\"/>\n";
    }
    return o.str();
}

// 体积光：2D 形体雾 / 3D 范围雾（SVG 近似，不引外部库）
static string renderLightSvg(const vector<RenderPoint>& poly, double lx, double ly,
                             double strength, bool volumetric, const string& title,
                             double minx, double miny, double maxx, double maxy) {
    double w = (maxx - minx) + 80, h = (maxy - miny) + 110;
    auto tx = [&](double x) { return x - minx + 40; };
    auto ty = [&](double y) { return y - miny + 70; };
    vector<RenderPoint> pts;
    for (const auto& p : poly) pts.push_back({tx(p.x), ty(p.y)});
    std::ostringstream o;
    o << "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"" << (int)w
      << "\" height=\"" << (int)h << "\" viewBox=\"0 0 " << (int)w << " " << (int)h
      << "\">\n";
    o << "<defs>\n";
    o << "  <clipPath id=\"faceClip\"><polygon points=\"" << renderPointsAttr(pts)
      << "\"/></clipPath>\n";
    o << "  <radialGradient id=\"glow\" gradientUnits=\"userSpaceOnUse\" cx=\""
      << tx(lx) << "\" cy=\"" << ty(ly) << "\" r=\"" << (w + h) << "\">\n";
    o << "    <stop offset=\"0\" stop-color=\"#ffffff\" stop-opacity=\"" << strength
      << "\"/>\n";
    o << "    <stop offset=\"0.35\" stop-color=\"#ffffff\" stop-opacity=\""
      << (strength * 0.55) << "\"/>\n";
    o << "    <stop offset=\"1\" stop-color=\"#ffffff\" stop-opacity=\"0\"/>\n";
    o << "  </radialGradient>\n";
    if (volumetric) {
        o << "  <filter id=\"fog\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n";
        o << "    <feGaussianBlur stdDeviation=\"14\"/>\n";
        o << "  </filter>\n";
    }
    o << "</defs>\n";
    o << "<rect width=\"100%\" height=\"100%\" fill=\"#0b1020\"/>\n";
    o << "<polygon points=\"" << renderPointsAttr(pts)
      << "\" fill=\"#101826\" stroke=\"#5a6b8c\" stroke-width=\"1.5\"/>\n";
    o << "<g clip-path=\"url(#faceClip)\"";
    if (volumetric) o << " filter=\"url(#fog)\"";
    o << ">\n";
    o << "<polygon points=\"" << renderPointsAttr(pts) << "\" fill=\"url(#glow)\"/>\n";
    if (volumetric) {
        // 多层错位，模拟“范围雾”的厚度。
        for (int k = 1; k <= 4; ++k) {
            double dx = (lx - (minx + maxx) / 2) * k * 0.02;
            double dy = (ly - (miny + maxy) / 2) * k * 0.02;
            o << "<polygon points=\"" << renderPointsAttr(pts)
              << "\" fill=\"url(#glow)\" opacity=\"" << (0.22 / k) << "\""
              << " transform=\"translate(" << dx << "," << dy << ")\"/>\n";
        }
    }
    o << "</g>\n";
    o << "<circle cx=\"" << tx(lx) << "\" cy=\"" << ty(ly)
      << "\" r=\"5\" fill=\"#fff6c8\"/>\n";
    o << "<text x=\"" << (int)(w / 2) << "\" y=\"30\" text-anchor=\"middle\" "
         "font-size=\"18\" font-family=\"Microsoft YaHei, sans-serif\" fill=\"#e8eefc\">"
      << xmlEscape(title) << "</text>\n";
    o << "</svg>\n";
    return o.str();
}

static string externalTarget(const string& src) {
    std::istringstream in(src);
    string line;
    while (std::getline(in, line)) {
        string t = trimText(line);
        if (t.empty()) continue;
        if (t[0] != '#') return "";
        t = trimText(t.substr(1));
        if (t.rfind("外派", 0) != 0) return "";
        t = trimText(t.substr(6));
        if (!t.empty() && (t[0] == ':' || startsWith(t, 0, "："))) {
            t = trimText(t.substr(t[0] == ':' ? 1 : 3));
        }
        size_t p = t.find_first_of(" \t");
        return p == string::npos ? t : t.substr(0, p);
    }
    return "";
}

static string pyQuote(const string& s) {
    string out = "'";
    for (char c : s) {
        if (c == '\\') out += "\\\\";
        else if (c == '\'') out += "\\'";
        else if (c == '\n') out += "\\n";
        else if (c == '\r') out += "\\r";
        else if (c == '\t') out += "\\t";
        else out += c;
    }
    out += "'";
    return out;
}

struct PyEmitter {
    const vector<StmtPtr>& program;
    vector<string> diags;
    std::ostringstream out;
    int indent = 0;
    bool usedMath = false;
    bool usedRandom = false;
    std::set<string> userFuncs;

    explicit PyEmitter(const vector<StmtPtr>& p) : program(p) { collectFuncs(p); }

    void collectFuncs(const vector<StmtPtr>& ps) {
        for (const auto& s : ps) {
            if (!s) continue;
            if (s->k == Stmt::K::Func) userFuncs.insert(s->name);
            collectFuncs(s->body);
            collectFuncs(s->elseBody);
            collectFuncs(s->finallyBody);
            for (const auto& br : s->branches) collectFuncs(br.second);
        }
    }

    void diag(int line, const string& msg) {
        diags.push_back("第 " + std::to_string(line) + " 行：" + msg);
    }
    void line(const string& s) {
        out << string(indent * 4, ' ') << s << "\n";
    }
    string expr(const ExprPtr& e) {
        if (!e) return "None";
        switch (e->k) {
            case Expr::K::Num: {
                if (std::isnan(e->num)) return "float('nan')";
                if (std::isinf(e->num)) return e->num < 0 ? "-float('inf')" : "float('inf')";
                std::ostringstream s;
                s << std::setprecision(17) << e->num;
                return s.str();
            }
            case Expr::K::Str: return pyQuote(e->text);
            case Expr::K::Bool: return e->b ? "True" : "False";
            case Expr::K::None: return "None";
            case Expr::K::Var: {
                if (e->text == "圆周率" || e->text == "π") { usedMath = true; return "math.pi"; }
                if (e->text == "自然常数") { usedMath = true; return "math.e"; }
                return e->text;
            }
            case Expr::K::Unary: {
                string a = expr(e->args[0]);
                if (e->op == "非") return "(not " + a + ")";
                if (e->op == "插值") return "str(" + a + ")";
                if (e->op == "√") { usedMath = true; return "math.sqrt(" + a + ")"; }
                return "(" + e->op + a + ")";
            }
            case Expr::K::Binary: {
                string a = expr(e->args[0]), b = expr(e->args[1]);
                string op = e->op;
                if (op == "且") op = "and";
                else if (op == "或") op = "or";
                else if (op == "包含") op = "in";
                else if (op == "不包含") { return "(" + a + " not in " + b + ")"; }
                return "(" + a + " " + op + " " + b + ")";
            }
            case Expr::K::Call: {
                string callee = expr(e->args[0]);
                string name = e->args[0]->k == Expr::K::Var ? e->args[0]->text : "";
                static const std::map<string, string> pyNames = {
                    {"长度", "len"}, {"范围", "range"}, {"绝对值", "abs"},
                    {"取整", "int"}, {"最大", "max"}, {"最小", "min"},
                    {"求和", "sum"}, {"幂", "pow"}, {"类型", "type"},
                    {"打印", "print"}};
                static const std::map<string, string> mathNames = {
                    {"平方根", "sqrt"}, {"正弦", "sin"}, {"余弦", "cos"},
                    {"正切", "tan"}, {"对数", "log"}, {"对数10", "log10"},
                    {"指数", "exp"}, {"反余弦", "acos"}, {"反正弦", "asin"},
                    {"反正切", "atan"}, {"双曲正弦", "sinh"}, {"双曲余弦", "cosh"},
                    {"双曲正切", "tanh"}, {"向上取整", "ceil"}, {"向下取整", "floor"}};
                if (name == "有键" && e->args.size() == 3)
                    return "(" + expr(e->args[2]) + " in " + expr(e->args[1]) + ")";
                if (name == "键" && e->args.size() == 2)
                    return expr(e->args[1]) + ".keys()";
                if (name == "值" && e->args.size() == 2)
                    return expr(e->args[1]) + ".values()";
                auto mit = userFuncs.count(name) ? mathNames.end() : mathNames.find(name);
                if (mit != mathNames.end()) {
                    usedMath = true;
                    callee = "math." + mit->second;
                } else {
                    auto it = pyNames.find(name);
                    if (it != pyNames.end()) callee = it->second;
                    else if (name == "随机") { usedRandom = true; callee = "random.random"; }
                    else if (name == "随机整数") { usedRandom = true; callee = "random.randint"; }
                    else if (!name.empty() && !userFuncs.count(name)) {
                        diag(e->line, "内置函数「" + name + "」没有 Python 映射");
                    }
                }
                string s = callee + "(";
                for (size_t i = 1; i < e->args.size(); ++i) {
                    if (i > 1) s += ", ";
                    s += expr(e->args[i]);
                }
                return s + ")";
            }
            case Expr::K::Index:
                return expr(e->args[0]) + "[" + expr(e->args[1]) + "]";
            case Expr::K::Slice: {
                string o = expr(e->args[0]);
                string a = e->args.size() > 1 && e->args[1] ? expr(e->args[1]) : "";
                string b = e->args.size() > 2 && e->args[2] ? expr(e->args[2]) : "";
                string c = e->args.size() > 3 && e->args[3] ? expr(e->args[3]) : "";
                return o + "[" + a + ":" + b + (e->args.size() > 3 ? ":" + c : "") + "]";
            }
            case Expr::K::List: {
                string s = "[";
                for (size_t i = 0; i < e->args.size(); ++i) {
                    if (i) s += ", ";
                    s += expr(e->args[i]);
                }
                return s + "]";
            }
            case Expr::K::Dict: {
                string s = "{";
                for (size_t i = 0; i < e->pairs.size(); ++i) {
                    if (i) s += ", ";
                    s += expr(e->pairs[i].first) + ": " + expr(e->pairs[i].second);
                }
                return s + "}";
            }
        }
        return "None";
    }
    void block(const vector<StmtPtr>& body) {
        ++indent;
        if (body.empty()) line("pass");
        for (const auto& s : body) stmt(s);
        --indent;
    }
    void stmt(const StmtPtr& s) {
        if (!s) return;
        switch (s->k) {
            case Stmt::K::Assign:
                if (s->target->k == Expr::K::Var)
                    line(s->target->text + " = " + expr(s->expr));
                else if (s->target->k == Expr::K::Index)
                    line(expr(s->target) + " = " + expr(s->expr));
                else
                    diag(s->line, "外派只支持变量/下标赋值");
                break;
            case Stmt::K::Print: {
                string args;
                for (size_t i = 0; i < s->args.size(); ++i) {
                    if (i) args += ", ";
                    args += "_文(" + expr(s->args[i]) + ")";
                }
                line("print(" + args + ")");
                break;
            }
            case Stmt::K::If:
                for (size_t i = 0; i < s->branches.size(); ++i) {
                    line(string(i == 0 ? "if " : "elif ") + expr(s->branches[i].first) + ":");
                    block(s->branches[i].second);
                }
                if (!s->elseBody.empty()) {
                    line("else:");
                    block(s->elseBody);
                }
                break;
            case Stmt::K::While:
                line("while " + expr(s->expr) + ":");
                block(s->body);
                break;
            case Stmt::K::For:
                if (!s->name2.empty())
                    line("for " + s->name + ", " + s->name2 + " in " + expr(s->expr) + ".items():");
                else
                    line("for " + s->name + " in " + expr(s->expr) + ":");
                block(s->body);
                break;
            case Stmt::K::Func: {
                string params;
                for (size_t i = 0; i < s->params.size(); ++i) {
                    if (i) params += ", ";
                    params += s->params[i];
                }
                line("def " + s->name + "(" + params + "):");
                block(s->body);
                break;
            }
            case Stmt::K::Return:
                line("return" + (s->expr ? " " + expr(s->expr) : ""));
                break;
            case Stmt::K::Break: line("break"); break;
            case Stmt::K::Continue: line("continue"); break;
            case Stmt::K::ExprStmt: line(expr(s->expr)); break;
            case Stmt::K::Import:
                diag(s->line, "「依赖」不翻译；请在外派目标里手动补库");
                break;
            case Stmt::K::Export:
                break;
            case Stmt::K::Match:
                diag(s->line, "匹配暂不翻译");
                break;
            case Stmt::K::Try:
                line("try:");
                block(s->body);
                if (!s->name.empty()) {
                    line("except Exception as " + s->name + ":");
                    block(s->elseBody);
                }
                if (!s->finallyBody.empty()) {
                    line("finally:");
                    block(s->finallyBody);
                }
                break;
        }
    }
    string generate() {
        for (const auto& s : program) stmt(s);
        string head = "# 由「文」外派库生成 · WEN-LANG-0.3\n";
        head += "import sys\n";
        head += "sys.stdout.reconfigure(encoding='utf-8')\n";
        head += "def _文数(v):\n";
        head += "    v = float(v)\n";
        head += "    if v == 0: return '0'\n";
        head += "    a = abs(v)\n";
        head += "    if a < 1e-9 or a >= 1e17: return format(v, '.6e')\n";
        head += "    if v == int(v): return str(int(v))\n";
        head += "    s = format(v, '.16g')\n";
        head += "    if 'e' in s or 'E' in s:\n";
        head += "        s = format(v, '.16f').rstrip('0').rstrip('.')\n";
        head += "    return s\n";
        head += "def _文值(v):\n";
        head += "    if v is True: return '\u771f'\n";
        head += "    if v is False: return '\u5047'\n";
        head += "    if v is None: return '\u7a7a'\n";
        head += "    if isinstance(v, str): return '\"' + v.replace('\\\\', '\\\\\\\\').replace('\"', '\\\\\"') + '\"'\n";
        head += "    if isinstance(v, list): return '[' + ', '.join(_文值(x) for x in v) + ']'\n";
        head += "    if isinstance(v, dict): return '{' + ', '.join(_文值(k) + ': ' + _文值(x) for k, x in sorted(v.items(), key=lambda kv: str(kv[0]).encode('utf-8'))) + '}'\n";
        head += "    return _文(v)\n";
        head += "def _文(v):\n";
        head += "    if v is True: return '\u771f'\n";
        head += "    if v is False: return '\u5047'\n";
        head += "    if v is None: return '\u7a7a'\n";
        head += "    if isinstance(v, (int, float)) and not isinstance(v, bool): return _文数(v)\n";
        head += "    if isinstance(v, str): return v\n";
        head += "    if isinstance(v, list): return '[' + ', '.join(_文值(x) for x in v) + ']'\n";
        head += "    if isinstance(v, dict): return '{' + ', '.join(_文值(k) + ': ' + _文值(x) for k, x in sorted(v.items(), key=lambda kv: str(kv[0]).encode('utf-8'))) + '}'\n";
        head += "    return str(v)\n";
        if (usedMath) head += "import math\n";
        if (usedRandom) head += "import random\n";
        return head + out.str();
    }
};

struct JsEmitter {
    const vector<StmtPtr>& program;
    vector<string> diags;
    std::ostringstream out;
    int indent = 0;

    explicit JsEmitter(const vector<StmtPtr>& p) : program(p) {}

    void diag(int line, const string& msg) {
        diags.push_back("第 " + std::to_string(line) + " 行：" + msg);
    }
    void line(const string& s) { out << string(indent * 2, ' ') << s << "\n"; }
    string expr(const ExprPtr& e) {
        if (!e) return "null";
        switch (e->k) {
            case Expr::K::Num: {
                if (std::isnan(e->num)) return "NaN";
                if (std::isinf(e->num)) return e->num < 0 ? "-Infinity" : "Infinity";
                std::ostringstream s;
                s << std::setprecision(17) << e->num;
                return s.str();
            }
            case Expr::K::Str: return pyQuote(e->text);
            case Expr::K::Bool: return e->b ? "true" : "false";
            case Expr::K::None: return "null";
            case Expr::K::Var: {
                if (e->text == "圆周率" || e->text == "π") return "Math.PI";
                if (e->text == "自然常数") return "Math.E";
                return e->text;
            }
            case Expr::K::Unary: {
                string a = expr(e->args[0]);
                if (e->op == "非") return "(!wenTruthy(" + a + "))";
                if (e->op == "插值") return "String(" + a + ")";
                if (e->op == "√") return "Math.sqrt(" + a + ")";
                return "(" + e->op + a + ")";
            }
            case Expr::K::Binary: {
                string a = expr(e->args[0]), b = expr(e->args[1]);
                string op = e->op;
                if (op == "且") return "(wenTruthy(" + a + ") && wenTruthy(" + b + "))";
                if (op == "或") return "(wenTruthy(" + a + ") || wenTruthy(" + b + "))";
                if (op == "包含") return "wenContains(" + b + ", " + a + ")";
                if (op == "不包含") return "(!wenContains(" + b + ", " + a + "))";
                return "(" + a + " " + op + " " + b + ")";
            }
            case Expr::K::Call: {
                string callee = expr(e->args[0]);
                string name = e->args[0]->k == Expr::K::Var ? e->args[0]->text : "";
                static const std::map<string, string> jsNames = {
                    {"长度", "wenLen"}, {"范围", "wenRange"}, {"绝对值", "Math.abs"},
                    {"取整", "Math.trunc"}, {"最大", "Math.max"}, {"最小", "Math.min"},
                    {"求和", "wenSum"}, {"幂", "Math.pow"}, {"类型", "wenType"},
                    {"打印", "console.log"}};
                static const std::map<string, string> mathNames = {
                    {"平方根", "Math.sqrt"}, {"正弦", "Math.sin"}, {"余弦", "Math.cos"},
                    {"正切", "Math.tan"}, {"对数", "Math.log"}, {"对数10", "Math.log10"},
                    {"指数", "Math.exp"}, {"反余弦", "Math.acos"}, {"反正弦", "Math.asin"},
                    {"反正切", "Math.atan"}, {"双曲正弦", "Math.sinh"},
                    {"双曲余弦", "Math.cosh"}, {"双曲正切", "Math.tanh"},
                    {"向上取整", "Math.ceil"}, {"向下取整", "Math.floor"}};
                auto mit = mathNames.find(name);
                if (mit != mathNames.end()) callee = mit->second;
                else {
                    auto it = jsNames.find(name);
                    if (it != jsNames.end()) callee = it->second;
                    else if (name == "随机") callee = "Math.random";
                    else if (name == "随机整数") callee = "wenRandInt";
                    else if (!name.empty() && functionModules().count(name) &&
                             !jsNames.count(name))
                        diag(e->line, "内置函数「" + name + "」没有 JavaScript 映射");
                }
                string s = callee + "(";
                for (size_t i = 1; i < e->args.size(); ++i) {
                    if (i > 1) s += ", ";
                    s += expr(e->args[i]);
                }
                return s + ")";
            }
            case Expr::K::Index:
                return expr(e->args[0]) + "[" + expr(e->args[1]) + "]";
            case Expr::K::Slice: {
                string o = expr(e->args[0]);
                string a = e->args.size() > 1 && e->args[1] ? expr(e->args[1]) : "0";
                string b = e->args.size() > 2 && e->args[2] ? expr(e->args[2]) : "undefined";
                string c = e->args.size() > 3 && e->args[3] ? expr(e->args[3]) : "1";
                return "wenSlice(" + o + ", " + a + ", " + b + ", " + c + ")";
            }
            case Expr::K::List: {
                string s = "[";
                for (size_t i = 0; i < e->args.size(); ++i) {
                    if (i) s += ", ";
                    s += expr(e->args[i]);
                }
                return s + "]";
            }
            case Expr::K::Dict: {
                string s = "{";
                for (size_t i = 0; i < e->pairs.size(); ++i) {
                    if (i) s += ", ";
                    s += "[" + expr(e->pairs[i].first) + "]: " + expr(e->pairs[i].second);
                }
                return s + "}";
            }
        }
        return "null";
    }
    void block(const vector<StmtPtr>& body) {
        line("{");
        ++indent;
        for (const auto& s : body) stmt(s);
        --indent;
        line("}");
    }
    void stmt(const StmtPtr& s) {
        if (!s) return;
        switch (s->k) {
            case Stmt::K::Assign:
                if (s->target->k == Expr::K::Var)
                    line("var " + s->target->text + " = " + expr(s->expr) + ";");
                else if (s->target->k == Expr::K::Index)
                    line(expr(s->target) + " = " + expr(s->expr) + ";");
                else
                    diag(s->line, "外派只支持变量/下标赋值");
                break;
            case Stmt::K::Print: {
                string args;
                for (size_t i = 0; i < s->args.size(); ++i) {
                    if (i) args += ", ";
                    args += expr(s->args[i]);
                }
                line("console.log(" + args + ");");
                break;
            }
            case Stmt::K::If:
                for (size_t i = 0; i < s->branches.size(); ++i) {
                    line(string(i == 0 ? "if " : "else if ") + "(wenTruthy(" +
                         expr(s->branches[i].first) + "))");
                    block(s->branches[i].second);
                }
                if (!s->elseBody.empty()) {
                    line("else");
                    block(s->elseBody);
                }
                break;
            case Stmt::K::While:
                line("while (wenTruthy(" + expr(s->expr) + "))");
                block(s->body);
                break;
            case Stmt::K::For:
                if (!s->name2.empty())
                    line("for (const [" + s->name + ", " + s->name2 + "] of wenItems(" +
                         expr(s->expr) + "))");
                else
                    line("for (const " + s->name + " of " + expr(s->expr) + ")");
                block(s->body);
                break;
            case Stmt::K::Func: {
                string params;
                for (size_t i = 0; i < s->params.size(); ++i) {
                    if (i) params += ", ";
                    params += s->params[i];
                }
                line("function " + s->name + "(" + params + ")");
                block(s->body);
                break;
            }
            case Stmt::K::Return:
                line("return" + (s->expr ? " " + expr(s->expr) : "") + ";");
                break;
            case Stmt::K::Break: line("break;"); break;
            case Stmt::K::Continue: line("continue;"); break;
            case Stmt::K::ExprStmt: line(expr(s->expr) + ";"); break;
            case Stmt::K::Import:
                diag(s->line, "「依赖」不翻译；请在外派目标里手动补库");
                break;
            case Stmt::K::Export: break;
            case Stmt::K::Match:
                diag(s->line, "匹配暂不翻译");
                break;
            case Stmt::K::Try:
                line("try");
                block(s->body);
                if (!s->name.empty()) {
                    line("catch (" + s->name + ")");
                    block(s->elseBody);
                }
                if (!s->finallyBody.empty()) {
                    line("finally");
                    block(s->finallyBody);
                }
                break;
        }
    }
    string generate() {
        for (const auto& s : program) stmt(s);
        const char* helpers =
            "function wenTruthy(v){if(v===null||v===undefined)return false;"
            "if(typeof v==='number')return v!==0;if(typeof v==='string')return v.length>0;"
            "if(Array.isArray(v))return v.length>0;"
            "if(typeof v==='object')return Object.keys(v).length>0;return !!v;}\n"
            "function wenLen(v){if(v===null||v===undefined)return 0;"
            "if(typeof v==='string')return [...v].length;"
            "if(Array.isArray(v))return v.length;"
            "if(typeof v==='object')return Object.keys(v).length;return 0;}\n"
            "function wenRange(a,b,c){let s=0,e=a,st=1;if(b!==undefined){s=a;e=b;}"
            "if(c!==undefined)st=c;let out=[];if(st>0){for(let i=s;i<e;i+=st)out.push(i);}"
            "else{for(let i=s;i>e;i+=st)out.push(i);}return out;}\n"
            "function wenItems(v){return Object.entries(v);}\n"
            "function wenContains(c,x){if(typeof c==='string')return c.includes(x);"
            "if(Array.isArray(c))return c.some(y=>JSON.stringify(y)===JSON.stringify(x));"
            "if(c&&typeof c==='object')return Object.prototype.hasOwnProperty.call(c,x);"
            "return false;}\n"
            "function wenSlice(v,a,b,c){a=a||0;if(b===undefined)b=v.length;if(c===undefined)c=1;"
            "let out=[];if(c>0){for(let i=a;i<b;i+=c)out.push(v[i]);}"
            "else{for(let i=a;i>b;i+=c)out.push(v[i]);}return out;}\n"
            "function wenSum(v){let s=0;for(const x of v)s+=x;return s;}\n"
            "function wenType(v){if(v===null||v===undefined)return '空';"
            "if(typeof v==='number')return '数字';if(typeof v==='string')return '文本';"
            "if(typeof v==='boolean')return '布尔';if(Array.isArray(v))return '列表';"
            "if(typeof v==='object')return '字典';return '未知';}\n"
            "function wenRandInt(a,b){return Math.floor(Math.random()*(b-a+1))+a;}\n";
        return "// 由「文」外派库生成 · WEN-LANG-0.3\n" + string(helpers) + "\n" + out.str();
    }
};

struct JsonEmitter {
    const vector<StmtPtr>& program;
    vector<string> diags;
    explicit JsonEmitter(const vector<StmtPtr>& p) : program(p) {}
    void diag(int line, const string& msg) {
        diags.push_back("第 " + std::to_string(line) + " 行：" + msg);
    }
    string expr(const ExprPtr& e) {
        if (!e) return "null";
        switch (e->k) {
            case Expr::K::Num: return "{\"k\":\"num\",\"v\":" + numberToString(e->num) + "}";
            case Expr::K::Str: return "{\"k\":\"str\",\"v\":" + quoteText(e->text) + "}";
            case Expr::K::Bool: return string("{\"k\":\"bool\",\"v\":") + (e->b ? "true" : "false") + "}";
            case Expr::K::None: return "{\"k\":\"none\"}";
            case Expr::K::Var: return "{\"k\":\"var\",\"name\":" + quoteText(e->text) + "}";
            case Expr::K::Unary:
                return "{\"k\":\"unary\",\"op\":" + quoteText(e->op) + ",\"a\":" + expr(e->args[0]) + "}";
            case Expr::K::Binary:
                return "{\"k\":\"binary\",\"op\":" + quoteText(e->op) + ",\"a\":" + expr(e->args[0]) +
                       ",\"b\":" + expr(e->args[1]) + "}";
            case Expr::K::Call: {
                string s = "{\"k\":\"call\",\"callee\":" + expr(e->args[0]) + ",\"args\":[";
                for (size_t i = 1; i < e->args.size(); ++i) {
                    if (i > 1) s += ",";
                    s += expr(e->args[i]);
                }
                return s + "]}";
            }
            case Expr::K::Index:
                return "{\"k\":\"index\",\"obj\":" + expr(e->args[0]) + ",\"idx\":" +
                       expr(e->args[1]) + "}";
            case Expr::K::Slice: {
                auto part = [&](size_t i) { return e->args.size() > i && e->args[i] ? expr(e->args[i]) : "null"; };
                return "{\"k\":\"slice\",\"obj\":" + expr(e->args[0]) + ",\"start\":" + part(1) +
                       ",\"stop\":" + part(2) + ",\"step\":" + part(3) + "}";
            }
            case Expr::K::List: {
                string s = "{\"k\":\"list\",\"items\":[";
                for (size_t i = 0; i < e->args.size(); ++i) {
                    if (i) s += ",";
                    s += expr(e->args[i]);
                }
                return s + "]}";
            }
            case Expr::K::Dict: {
                string s = "{\"k\":\"dict\",\"pairs\":[";
                for (size_t i = 0; i < e->pairs.size(); ++i) {
                    if (i) s += ",";
                    s += "[" + expr(e->pairs[i].first) + "," + expr(e->pairs[i].second) + "]";
                }
                return s + "]}";
            }
        }
        return "null";
    }
    string block(const vector<StmtPtr>& body) {
        string s = "[";
        for (size_t i = 0; i < body.size(); ++i) {
            if (i) s += ",";
            s += stmt(body[i]);
        }
        return s + "]";
    }
    string stmt(const StmtPtr& s) {
        if (!s) return "null";
        string head = "{\"line\":" + std::to_string(s->line) + ",\"k\":";
        switch (s->k) {
            case Stmt::K::Assign:
                return head + "\"assign\",\"target\":" + expr(s->target) + ",\"expr\":" +
                       expr(s->expr) + "}";
            case Stmt::K::Print: {
                string a = "[";
                for (size_t i = 0; i < s->args.size(); ++i) {
                    if (i) a += ",";
                    a += expr(s->args[i]);
                }
                return head + "\"print\",\"args\":" + a + "]}";
            }
            case Stmt::K::If: {
                string b = "[";
                for (size_t i = 0; i < s->branches.size(); ++i) {
                    if (i) b += ",";
                    b += "{\"cond\":" + expr(s->branches[i].first) + ",\"body\":" +
                         block(s->branches[i].second) + "}";
                }
                return head + "\"if\",\"branches\":" + b + ",\"else\":" + block(s->elseBody) + "}";
            }
            case Stmt::K::While:
                return head + "\"while\",\"cond\":" + expr(s->expr) + ",\"body\":" + block(s->body) + "}";
            case Stmt::K::For:
                return head + "\"for\",\"name\":" + quoteText(s->name) + ",\"name2\":" +
                       quoteText(s->name2) + ",\"iter\":" + expr(s->expr) + ",\"body\":" +
                       block(s->body) + "}";
            case Stmt::K::Func: {
                string p = "[";
                for (size_t i = 0; i < s->params.size(); ++i) {
                    if (i) p += ",";
                    p += quoteText(s->params[i]);
                }
                p += "]";
                return head + "\"func\",\"name\":" + quoteText(s->name) + ",\"params\":" + p +
                       ",\"body\":" + block(s->body) + "}";
            }
            case Stmt::K::Return:
                return head + "\"return\",\"expr\":" + (s->expr ? expr(s->expr) : "null") + "}";
            case Stmt::K::Break: return head + "\"break\"}";
            case Stmt::K::Continue: return head + "\"continue\"}";
            case Stmt::K::ExprStmt: return head + "\"expr\",\"expr\":" + expr(s->expr) + "}";
            case Stmt::K::Import: {
                string a = "[";
                for (size_t i = 0; i < s->imports.size(); ++i) {
                    if (i) a += ",";
                    a += quoteText(s->imports[i]);
                }
                return head + "\"import\",\"names\":" + a + "]}";
            }
            case Stmt::K::Export: {
                string a = "[";
                for (size_t i = 0; i < s->imports.size(); ++i) {
                    if (i) a += ",";
                    a += quoteText(s->imports[i]);
                }
                return head + "\"export\",\"names\":" + a + "]}";
            }
            case Stmt::K::Try:
                return head + "\"try\",\"body\":" + block(s->body) + ",\"catch\":" +
                       quoteText(s->name) + ",\"catchBody\":" + block(s->elseBody) +
                       ",\"finally\":" + block(s->finallyBody) + "}";
        }
        return "null";
    }
    string generate() {
        return "{\"target\":\"json\",\"ast\":" + block(program) + "}";
    }
};

struct JavaEmitter {
    const vector<StmtPtr>& program;
    vector<string> diags;
    std::ostringstream out;
    int indent = 1;
    set<string> locals;

    explicit JavaEmitter(const vector<StmtPtr>& p) : program(p) {}

    void diag(int line, const string& msg) {
        diags.push_back("第 " + std::to_string(line) + " 行：" + msg);
    }
    void line(const string& s) { out << string(indent * 4, ' ') << s << "\n"; }
    static string jstr(const string& s) {
        string o = "\"";
        for (char c : s) {
            if (c == '\\') o += "\\\\";
            else if (c == '"') o += "\\\"";
            else if (c == '\n') o += "\\n";
            else if (c == '\r') o += "\\r";
            else if (c == '\t') o += "\\t";
            else o += c;
        }
        return o + "\"";
    }
    string expr(const ExprPtr& e) {
        if (!e) return "null";
        switch (e->k) {
            case Expr::K::Num: {
                if (std::isnan(e->num) || std::isinf(e->num)) {
                    diag(e->line, "Java 目标不支持非数/无穷");
                    return "null";
                }
                return numberToString(e->num);
            }
            case Expr::K::Str: return jstr(e->text);
            case Expr::K::Bool: return e->b ? "true" : "false";
            case Expr::K::None: return "null";
            case Expr::K::Var: {
                if (e->text == "圆周率" || e->text == "π") return "Math.PI";
                if (e->text == "自然常数") return "Math.E";
                return e->text;
            }
            case Expr::K::Unary:
                if (e->op == "非") return "(!W.truthy(" + expr(e->args[0]) + "))";
                if (e->op == "插值") return "String(" + expr(e->args[0]) + ")";
                if (e->op == "√") return "Math.sqrt(" + expr(e->args[0]) + ")";
                return "(W.neg(" + expr(e->args[0]) + "))";
            case Expr::K::Binary: {
                string a = expr(e->args[0]), b = expr(e->args[1]);
                string op = e->op;
                if (op == "且") return "(W.truthy(" + a + ") && W.truthy(" + b + "))";
                if (op == "或") return "(W.truthy(" + a + ") || W.truthy(" + b + "))";
                if (op == "包含") return "W.contains(" + b + "," + a + ")";
                if (op == "不包含") return "(!W.contains(" + b + "," + a + "))";
                if (op == "+") return "W.add(" + a + "," + b + ")";
                if (op == "-") return "W.sub(" + a + "," + b + ")";
                if (op == "*") return "W.mul(" + a + "," + b + ")";
                if (op == "/") return "W.div(" + a + "," + b + ")";
                if (op == "//") return "W.idiv(" + a + "," + b + ")";
                if (op == "%") return "W.mod(" + a + "," + b + ")";
                if (op == "**") return "W.pow(" + a + "," + b + ")";
                if (op == "==") return "W.eq(" + a + "," + b + ")";
                if (op == "!=") return "(!W.eq(" + a + "," + b + "))";
                if (op == "<") return "W.lt(" + a + "," + b + ")";
                if (op == "<=") return "W.le(" + a + "," + b + ")";
                if (op == ">") return "W.gt(" + a + "," + b + ")";
                if (op == ">=") return "W.ge(" + a + "," + b + ")";
                diag(e->line, "Java 目标不支持的运算符「" + op + "」");
                return "null";
            }
            case Expr::K::Call: {
                string name = e->args[0]->k == Expr::K::Var ? e->args[0]->text : "";
                string callee = expr(e->args[0]);
                static const std::map<string, string> builtins = {
                    {"长度", "W.len"}, {"范围", "W.range"}, {"绝对值", "W.abs"},
                    {"取整", "W.intVal"}, {"最大", "W.max"}, {"最小", "W.min"},
                    {"求和", "W.sum"}, {"幂", "W.pow"}, {"类型", "W.type"},
                    {"打印", "W.print"}, {"平方根", "W.sqrt"}, {"正弦", "W.sin"},
                    {"余弦", "W.cos"}, {"正切", "W.tan"}, {"对数", "W.log"},
                    {"对数10", "W.log10"}, {"指数", "W.exp"}, {"随机", "W.random"},
                    {"随机整数", "W.randInt"}};
                auto it = builtins.find(name);
                if (it != builtins.end()) callee = it->second;
                else if (!name.empty() && functionModules().count(name))
                    diag(e->line, "内置函数「" + name + "」没有 Java 映射");
                string s = callee + "(";
                for (size_t i = 1; i < e->args.size(); ++i) {
                    if (i > 1) s += ", ";
                    s += expr(e->args[i]);
                }
                return s + ")";
            }
            case Expr::K::Index:
                return "W.index(" + expr(e->args[0]) + "," + expr(e->args[1]) + ")";
            case Expr::K::Slice:
                return "W.slice(" + expr(e->args[0]) + "," +
                       (e->args.size() > 1 && e->args[1] ? expr(e->args[1]) : "null") + "," +
                       (e->args.size() > 2 && e->args[2] ? expr(e->args[2]) : "null") + "," +
                       (e->args.size() > 3 && e->args[3] ? expr(e->args[3]) : "null") + ")";
            case Expr::K::List: {
                string s = "W.list(";
                for (size_t i = 0; i < e->args.size(); ++i) {
                    if (i) s += ", ";
                    s += expr(e->args[i]);
                }
                return s + ")";
            }
            case Expr::K::Dict: {
                string s = "W.dict(";
                for (size_t i = 0; i < e->pairs.size(); ++i) {
                    if (i) s += ", ";
                    s += expr(e->pairs[i].first) + ", " + expr(e->pairs[i].second);
                }
                return s + ")";
            }
        }
        return "null";
    }
    void collect(const StmtPtr& s) {
        if (!s) return;
        switch (s->k) {
            case Stmt::K::Assign:
                if (s->target->k == Expr::K::Var) locals.insert(s->target->text);
                break;
            case Stmt::K::If:
                for (const auto& b : s->branches)
                    for (const auto& x : b.second) collect(x);
                for (const auto& x : s->elseBody) collect(x);
                break;
            case Stmt::K::While:
                for (const auto& x : s->body) collect(x);
                break;
            case Stmt::K::For:
                for (const auto& x : s->body) collect(x);
                break;
            case Stmt::K::Try:
                for (const auto& x : s->body) collect(x);
                for (const auto& x : s->elseBody) collect(x);
                for (const auto& x : s->finallyBody) collect(x);
                break;
            case Stmt::K::Match:
                for (const auto& br : s->branches) for (const auto& x : br.second) collect(x);
                for (const auto& x : s->elseBody) collect(x);
                break;
            default: break;
        }
    }
    void block(const vector<StmtPtr>& body) {
        line("{");
        ++indent;
        for (const auto& s : body) stmt(s);
        --indent;
        line("}");
    }
    void stmt(const StmtPtr& s) {
        if (!s) return;
        switch (s->k) {
            case Stmt::K::Assign:
                if (s->target->k == Expr::K::Var)
                    line(s->target->text + " = " + expr(s->expr) + ";");
                else if (s->target->k == Expr::K::Index)
                    line("W.setIndex(" + expr(s->target->args[0]) + "," +
                         expr(s->target->args[1]) + "," + expr(s->expr) + ");");
                else
                    diag(s->line, "Java 目标只支持变量/下标赋值");
                break;
            case Stmt::K::Print: {
                string a;
                for (size_t i = 0; i < s->args.size(); ++i) {
                    if (i) a += ", ";
                    a += expr(s->args[i]);
                }
                line("W.print(" + a + ");");
                break;
            }
            case Stmt::K::If:
                for (size_t i = 0; i < s->branches.size(); ++i) {
                    line(string(i == 0 ? "if (W.truthy(" : "else if (W.truthy(") +
                         expr(s->branches[i].first) + "))");
                    block(s->branches[i].second);
                }
                if (!s->elseBody.empty()) {
                    line("else");
                    block(s->elseBody);
                }
                break;
            case Stmt::K::While:
                line("while (W.truthy(" + expr(s->expr) + "))");
                block(s->body);
                break;
            case Stmt::K::For:
                if (!s->name2.empty()) {
                    line("for (Object[] kv : W.entries(" + expr(s->expr) + "))");
                    line("{");
                    ++indent;
                    line("Object " + s->name + " = kv[0];");
                    line("Object " + s->name2 + " = kv[1];");
                    for (const auto& x : s->body) stmt(x);
                    --indent;
                    line("}");
                } else {
                    line("for (Object " + s->name + " : W.iter(" + expr(s->expr) + "))");
                    block(s->body);
                }
                break;
            case Stmt::K::Func: {
                string params;
                for (size_t i = 0; i < s->params.size(); ++i) {
                    if (i) params += ", ";
                    params += "Object " + s->params[i];
                }
                line("static Object " + s->name + "(" + params + ")");
                line("{");
                ++indent;
                set<string> save = locals;
                locals.clear();
                for (const auto& x : s->body) collect(x);
                vector<string> names(locals.begin(), locals.end());
                for (const auto& n : names) line("Object " + n + ";");
                for (const auto& x : s->body) stmt(x);
                if (s->body.empty() || s->body.back()->k != Stmt::K::Return)
                    line("return null;");
                locals = save;
                --indent;
                line("}");
                break;
            }
            case Stmt::K::Return:
                line("return" + (s->expr ? " " + expr(s->expr) : " null") + ";");
                break;
            case Stmt::K::Break: line("break;"); break;
            case Stmt::K::Continue: line("continue;"); break;
            case Stmt::K::ExprStmt: line(expr(s->expr) + ";"); break;
            case Stmt::K::Import:
                diag(s->line, "「依赖」不翻译；请在外派目标里手动补库");
                break;
            case Stmt::K::Export: break;
            case Stmt::K::Match:
                diag(s->line, "匹配暂不翻译");
                break;
            case Stmt::K::Try:
                line("try");
                block(s->body);
                if (!s->name.empty()) {
                    line("catch (Exception " + s->name + ")");
                    block(s->elseBody);
                }
                if (!s->finallyBody.empty()) {
                    line("finally");
                    block(s->finallyBody);
                }
                break;
        }
    }
    string generate() {
        std::ostringstream head;
        head << "// 由「文」外派库生成 · WEN-LANG-0.3\nimport java.util.*;\n\npublic class Main {\n";
        head << R"JAVA(static class W {
    static void print(Object... a) {
        StringBuilder b = new StringBuilder();
        for (int i = 0; i < a.length; i++) { if (i > 0) b.append(" "); b.append(str(a[i])); }
        System.out.println(b);
    }
    static String str(Object v) {
        if (v == null) return "空";
        if (v instanceof List) {
            StringBuilder b = new StringBuilder("[");
            List<?> l = (List<?>) v;
            for (int i = 0; i < l.size(); i++) { if (i > 0) b.append(", "); b.append(str(l.get(i))); }
            return b.append("]").toString();
        }
        if (v instanceof Map) {
            StringBuilder b = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<?,?> e : ((Map<?,?>) v).entrySet()) {
                if (!first) b.append(", "); first = false;
                b.append(str(e.getKey())).append(": ").append(str(e.getValue()));
            }
            return b.append("}").toString();
        }
        return String.valueOf(v);
    }
    static boolean truthy(Object v) {
        if (v == null) return false;
        if (v instanceof Number) return ((Number) v).doubleValue() != 0;
        if (v instanceof String) return !((String) v).isEmpty();
        if (v instanceof Collection) return !((Collection<?>) v).isEmpty();
        if (v instanceof Map) return !((Map<?,?>) v).isEmpty();
        return true;
    }
    static double d(Object v) { return ((Number) v).doubleValue(); }
    static Object neg(Object a) { return -d(a); }
    static Object add(Object a, Object b) {
        if (a instanceof String || b instanceof String) return str(a) + str(b);
        return d(a) + d(b);
    }
    static Object sub(Object a, Object b) { return d(a) - d(b); }
    static Object mul(Object a, Object b) { return d(a) * d(b); }
    static Object div(Object a, Object b) { return d(a) / d(b); }
    static Object idiv(Object a, Object b) { return Math.floor(d(a) / d(b)); }
    static Object mod(Object a, Object b) { return d(a) % d(b); }
    static Object pow(Object a, Object b) { return Math.pow(d(a), d(b)); }
    static boolean eq(Object a, Object b) { return Objects.equals(a, b); }
    static boolean lt(Object a, Object b) { return d(a) < d(b); }
    static boolean le(Object a, Object b) { return d(a) <= d(b); }
    static boolean gt(Object a, Object b) { return d(a) > d(b); }
    static boolean ge(Object a, Object b) { return d(a) >= d(b); }
    static Object len(Object v) {
        if (v instanceof String) return (double) ((String) v).length();
        if (v instanceof Collection) return (double) ((Collection<?>) v).size();
        if (v instanceof Map) return (double) ((Map<?,?>) v).size();
        return 0.0;
    }
    static Object range(Object a) { return range(0, a, 1); }
    static Object range(Object a, Object b) { return range(a, b, 1); }
    static Object range(Object a, Object b, Object c) {
        List<Object> l = new ArrayList<>();
        double s = d(a), e = d(b), st = d(c);
        if (st > 0) for (double i = s; i < e; i += st) l.add(i);
        else for (double i = s; i > e; i += st) l.add(i);
        return l;
    }
    static List<Object> list(Object... a) { return new ArrayList<>(Arrays.asList(a)); }
    static Map<Object,Object> dict(Object... kv) {
        Map<Object,Object> m = new LinkedHashMap<>();
        for (int i = 0; i + 1 < kv.length; i += 2) m.put(kv[i], kv[i + 1]);
        return m;
    }
    static Object index(Object o, Object i) {
        if (o instanceof List) return ((List<?>) o).get(((Number) i).intValue());
        if (o instanceof Map) return ((Map<?,?>) o).get(i);
        if (o instanceof String) return String.valueOf(((String) o).charAt(((Number) i).intValue()));
        return null;
    }
    static void setIndex(Object o, Object i, Object v) {
        if (o instanceof List) ((List<Object>) o).set(((Number) i).intValue(), v);
        else if (o instanceof Map) ((Map<Object,Object>) o).put(i, v);
    }
    static Object slice(Object o, Object a, Object b, Object c) {
        List<Object> src = new ArrayList<>();
        if (o instanceof String) for (char ch : ((String) o).toCharArray()) src.add(String.valueOf(ch));
        else if (o instanceof List) src.addAll((List<?>) o);
        int n = src.size();
        int st = c == null ? 1 : ((Number) c).intValue();
        int s = a == null ? (st > 0 ? 0 : n - 1) : ((Number) a).intValue();
        int e = b == null ? (st > 0 ? n : -1) : ((Number) b).intValue();
        List<Object> out = new ArrayList<>();
        if (st > 0) for (int i = s; i < e && i < n; i += st) { if (i >= 0) out.add(src.get(i)); }
        else for (int i = s; i > e && i >= 0; i += st) { if (i < n) out.add(src.get(i)); }
        return out;
    }
    static Object sum(Object o) { double s = 0; for (Object x : (List<?>) o) s += d(x); return s; }
    static Object abs(Object a) { return Math.abs(d(a)); }
    static Object intVal(Object a) { return (double) ((long) d(a)); }
    static Object sqrt(Object a) { return Math.sqrt(d(a)); }
    static Object sin(Object a) { return Math.sin(d(a)); }
    static Object cos(Object a) { return Math.cos(d(a)); }
    static Object tan(Object a) { return Math.tan(d(a)); }
    static Object log(Object a) { return Math.log(d(a)); }
    static Object log10(Object a) { return Math.log10(d(a)); }
    static Object exp(Object a) { return Math.exp(d(a)); }
    static Object random() { return Math.random(); }
    static Object randInt(Object a, Object b) { return (double) ((int) (d(a) + Math.random() * (d(b) - d(a) + 1))); }
    static Object max(Object a, Object b) { return Math.max(d(a), d(b)); }
    static Object min(Object a, Object b) { return Math.min(d(a), d(b)); }
    static Object type(Object v) {
        if (v == null) return "空";
        if (v instanceof Number) return "数字";
        if (v instanceof String) return "文本";
        if (v instanceof Boolean) return "布尔";
        if (v instanceof List) return "列表";
        if (v instanceof Map) return "字典";
        return "未知";
    }
    static Iterable<?> iter(Object o) {
        if (o instanceof Iterable) return (Iterable<?>) o;
        if (o instanceof String) {
            List<Object> l = new ArrayList<>();
            for (char c : ((String) o).toCharArray()) l.add(String.valueOf(c));
            return l;
        }
        return new ArrayList<>();
    }
    static Iterable<Object[]> entries(Object o) {
        List<Object[]> l = new ArrayList<>();
        if (o instanceof Map) for (Map.Entry<?,?> e : ((Map<?,?>) o).entrySet()) l.add(new Object[]{e.getKey(), e.getValue()});
        return l;
    }
    static boolean contains(Object c, Object x) {
        if (c instanceof String) return ((String) c).contains(str(x));
        if (c instanceof Collection) return ((Collection<?>) c).contains(x);
        if (c instanceof Map) return ((Map<?,?>) c).containsKey(x);
        return false;
    }
}
)JAVA";
        locals.clear();
        for (const auto& s : program) collect(s);
        vector<string> names(locals.begin(), locals.end());
        // 顶层函数
        for (const auto& s : program) {
            if (s->k == Stmt::K::Func) {
                out.str("");
                out.clear();
                indent = 1;
                stmt(s);
                head << out.str();
            }
        }
        head << "\n    public static void main(String[] args) throws Exception {\n";
        for (const auto& n : names) head << "        Object " << n << ";\n";
        for (const auto& s : program)
            if (s->k != Stmt::K::Func && s->k != Stmt::K::Import) {
                out.str("");
                out.clear();
                indent = 2;
                stmt(s);
                head << out.str();
            }
        head << "    }\n}\n";
        return head.str();
    }
};

static double parallelReduceNums(const vector<double>& xs, int mode) {
    if (xs.empty()) return 0;
    unsigned hw = std::thread::hardware_concurrency();
    size_t threads = std::max(1u, std::min<unsigned>(hw ? hw : 1, (unsigned)xs.size()));
    vector<double> parts(threads, mode == 2 ? std::numeric_limits<double>::max() : 0);
    if (mode == 1)
        for (double& p : parts) p = -std::numeric_limits<double>::max();
    vector<std::thread> pool;
    for (size_t t = 0; t < threads; ++t) {
        pool.emplace_back([&, t]() {
            size_t begin = xs.size() * t / threads;
            size_t end = xs.size() * (t + 1) / threads;
            double acc = parts[t];
            for (size_t i = begin; i < end; ++i) {
                if (mode == 0) acc += xs[i];
                else if (mode == 1) acc = std::max(acc, xs[i]);
                else acc = std::min(acc, xs[i]);
            }
            parts[t] = acc;
        });
    }
    for (auto& th : pool) th.join();
    double out = parts[0];
    for (size_t i = 1; i < parts.size(); ++i) {
        if (mode == 0) out += parts[i];
        else if (mode == 1) out = std::max(out, parts[i]);
        else out = std::min(out, parts[i]);
    }
    return out;
}
static string translateToCppSource(const vector<StmtPtr>& program, vector<string>& diags);

struct TranslationTarget {
    int line = 0;
    string name;
};

static vector<TranslationTarget> translationTargets(const string& src) {
    vector<TranslationTarget> out;
    std::istringstream in(src);
    string line;
    int n = 0;
    while (std::getline(in, line)) {
        ++n;
        string t = trimText(line);
        if (t.empty() || t[0] != '#') continue;
        t = trimText(t.substr(1));
        if (t.rfind("翻译", 0) != 0) continue;
        t = trimText(t.substr(6));
        if (!t.empty() && (t[0] == ':' || startsWith(t, 0, "：")))
            t = trimText(t.substr(t[0] == ':' ? 1 : 3));
        size_t p = t.find_first_of(" \t");
        string name = p == string::npos ? t : t.substr(0, p);
        if (name == "bytecode" || name == "bc") name = "字节码";
        if (name == "cpp" || name == "c++" || name == "C++") name = "C++";
        if (name == "asm" || name == "assembly") name = "汇编";
        out.push_back({n, name});
    }
    return out;
}

struct StackIns {
    string op;
    string jsonArg;
    string asmArg;
    int target = -1;
};

struct BcFunction {
    vector<string> params;
    vector<StackIns> code;
};

struct StackEmitter {
    const vector<StmtPtr>& program;
    vector<string> diags;
    vector<StackIns> code;
    int tempCounter = 0;
    bool inFunction = false;
    map<string, BcFunction> funcs;
    vector<vector<int>> breakJumps;
    vector<vector<int>> continueJumps;

    explicit StackEmitter(const vector<StmtPtr>& p) : program(p) {}

    void diag(int line, const string& msg) {
        diags.push_back("第 " + std::to_string(line) + " 行：" + msg);
    }
    int emit(const string& op, const string& jsonArg = "", const string& asmArg = "") {
        code.push_back({op, jsonArg, asmArg, -1});
        return (int)code.size() - 1;
    }
    void patch(int at, int target) { code[(size_t)at].target = target; }
    void expr(const ExprPtr& e) {
        if (!e) { emit("push", "\"v\":null", "PUSH null"); return; }
        switch (e->k) {
            case Expr::K::Num:
                emit("push", "\"v\":" + numberToString(e->num), "PUSH " + numberToString(e->num));
                break;
            case Expr::K::Str:
                emit("push", "\"v\":" + quoteText(e->text), "PUSH " + pyQuote(e->text));
                break;
            case Expr::K::Bool:
                emit("push", string("\"v\":") + (e->b ? "true" : "false"), e->b ? "PUSH true" : "PUSH false");
                break;
            case Expr::K::None:
                emit("push", "\"v\":null", "PUSH null");
                break;
            case Expr::K::Var:
                emit("load", "\"name\":" + quoteText(e->text), "LOAD " + e->text);
                break;
            case Expr::K::Unary:
                expr(e->args[0]);
                if (e->op == "非") emit("not", "", "NOT");
                else if (e->op == "-") emit("neg", "", "NEG");
                else if (e->op == "√") emit("sqrt", "", "SQRT");
                else diag(e->line, "字节码/汇编不支持的运算符「" + e->op + "」");
                break;
            case Expr::K::Binary: {
                expr(e->args[0]);
                expr(e->args[1]);
                string op = e->op;
                if (op == "+") emit("add", "", "ADD");
                else if (op == "-") emit("sub", "", "SUB");
                else if (op == "*") emit("mul", "", "MUL");
                else if (op == "/") emit("div", "", "DIV");
                else if (op == "//") emit("idiv", "", "IDIV");
                else if (op == "%") emit("mod", "", "MOD");
                else if (op == "**") emit("pow", "", "POW");
                else if (op == "==") emit("eq", "", "EQ");
                else if (op == "!=") emit("ne", "", "NE");
                else if (op == "<") emit("lt", "", "LT");
                else if (op == "<=") emit("le", "", "LE");
                else if (op == ">") emit("gt", "", "GT");
                else if (op == ">=") emit("ge", "", "GE");
                else if (op == "且") emit("and", "", "AND");
                else if (op == "或") emit("or", "", "OR");
                else diag(e->line, "字节码/汇编不支持的运算符「" + op + "」");
                break;
            }
            case Expr::K::Call: {
                if (e->args[0]->k != Expr::K::Var) {
                    diag(e->line, "字节码/汇编只支持按名字调用");
                    break;
                }
                for (size_t i = 1; i < e->args.size(); ++i) expr(e->args[i]);
                string name = e->args[0]->text;
                emit("call", "\"name\":" + quoteText(name) + ",\"n\":" +
                                  std::to_string(e->args.size() - 1),
                     "CALL " + name + " " + std::to_string(e->args.size() - 1));
                break;
            }
            case Expr::K::Index:
                expr(e->args[0]);
                expr(e->args[1]);
                emit("index", "", "INDEX");
                break;
            case Expr::K::List:
                for (const auto& a : e->args) expr(a);
                emit("list", "\"n\":" + std::to_string(e->args.size()),
                     "LIST " + std::to_string(e->args.size()));
                break;
            case Expr::K::Dict:
                for (const auto& kv : e->pairs) { expr(kv.first); expr(kv.second); }
                emit("dict", "\"n\":" + std::to_string(e->pairs.size()),
                     "DICT " + std::to_string(e->pairs.size()));
                break;
            case Expr::K::Slice:
                expr(e->args[0]);
                for (size_t i = 1; i < 4; ++i) {
                    if (i < e->args.size() && e->args[i]) expr(e->args[i]);
                    else emit("push", "\"v\":null", "PUSH null");
                }
                emit("slice", "", "SLICE");
                break;
        }
    }
    void stmt(const StmtPtr& s) {
        if (!s) return;
        switch (s->k) {
            case Stmt::K::Assign:
                if (s->target->k != Expr::K::Var) {
                    diag(s->line, "字节码/汇编只支持变量赋值");
                    break;
                }
                expr(s->expr);
                emit("store", "\"name\":" + quoteText(s->target->text), "STORE " + s->target->text);
                break;
            case Stmt::K::Print: {
                for (const auto& a : s->args) expr(a);
                emit("print", "\"n\":" + std::to_string(s->args.size()), "PRINT " + std::to_string(s->args.size()));
                break;
            }
            case Stmt::K::ExprStmt:
                expr(s->expr);
                emit("pop", "", "POP");
                break;
            case Stmt::K::If: {
                vector<int> ends;
                for (const auto& br : s->branches) {
                    expr(br.first);
                    int jz = emit("jz");
                    for (const auto& x : br.second) stmt(x);
                    ends.push_back(emit("jmp"));
                    patch(jz, (int)code.size());
                }
                for (const auto& x : s->elseBody) stmt(x);
                int end = (int)code.size();
                for (int j : ends) patch(j, end);
                break;
            }
            case Stmt::K::While: {
                int start = (int)code.size();
                expr(s->expr);
                int jz = emit("jz");
                for (const auto& x : s->body) stmt(x);
                int jmp = emit("jmp");
                patch(jmp, start);
                patch(jz, (int)code.size());
                break;
            }
            case Stmt::K::Break:
                if (breakJumps.empty()) diag(s->line, "「中断」只能用在循环里");
                else breakJumps.back().push_back(emit("jmp", "\"to\":0", "JMP 0"));
                break;
            case Stmt::K::Continue:
                if (continueJumps.empty()) diag(s->line, "「继续」只能用在循环里");
                else continueJumps.back().push_back(emit("jmp", "\"to\":0", "JMP 0"));
                break;
            case Stmt::K::Func: {
                if (inFunction) { diag(s->line, "字节码/汇编暂不支持嵌套函数"); break; }
                StackEmitter sub(s->body);
                sub.inFunction = true;
                for (const auto& bodyStmt : s->body) sub.stmt(bodyStmt);
                for (const auto& d : sub.diags) diags.push_back(d);
                funcs[s->name] = {s->params, sub.code};
                break;
            }
            case Stmt::K::For: {
                if (!s->name2.empty()) {
                    string dictVar = "__for_dict_" + std::to_string(tempCounter);
                    string keysVar = "__for_keys_" + std::to_string(tempCounter);
                    string valsVar = "__for_vals_" + std::to_string(tempCounter);
                    string idxVar = "__for_i_" + std::to_string(tempCounter);
                    ++tempCounter;
                    expr(s->expr);
                    emit("store", "\"name\":" + quoteText(dictVar), "STORE " + dictVar);
                    emit("load", "\"name\":" + quoteText(dictVar), "LOAD " + dictVar);
                    emit("call", "\"name\":\"键\",\"n\":1", "CALL 键 1");
                    emit("store", "\"name\":" + quoteText(keysVar), "STORE " + keysVar);
                    emit("load", "\"name\":" + quoteText(dictVar), "LOAD " + dictVar);
                    emit("call", "\"name\":\"值\",\"n\":1", "CALL 值 1");
                    emit("store", "\"name\":" + quoteText(valsVar), "STORE " + valsVar);
                    emit("push", "\"v\":0", "PUSH 0");
                    emit("store", "\"name\":" + quoteText(idxVar), "STORE " + idxVar);
                    int start = (int)code.size();
                    emit("load", "\"name\":" + quoteText(idxVar), "LOAD " + idxVar);
                    emit("load", "\"name\":" + quoteText(keysVar), "LOAD " + keysVar);
                    emit("call", "\"name\":\"长度\",\"n\":1", "CALL 长度 1");
                    emit("lt", "", "LT");
                    int exitJump = emit("jz", "\"to\":0", "JZ 0");
                    emit("load", "\"name\":" + quoteText(keysVar), "LOAD " + keysVar);
                    emit("load", "\"name\":" + quoteText(idxVar), "LOAD " + idxVar);
                    emit("index", "", "INDEX");
                    emit("store", "\"name\":" + quoteText(s->name), "STORE " + s->name);
                    emit("load", "\"name\":" + quoteText(valsVar), "LOAD " + valsVar);
                    emit("load", "\"name\":" + quoteText(idxVar), "LOAD " + idxVar);
                    emit("index", "", "INDEX");
                    emit("store", "\"name\":" + quoteText(s->name2), "STORE " + s->name2);
                    breakJumps.push_back({});
                    continueJumps.push_back({});
                    for (const auto& bodyStmt : s->body) stmt(bodyStmt);
                    int contTarget = (int)code.size();
                    for (int j : continueJumps.back()) patch(j, contTarget);
                    emit("load", "\"name\":" + quoteText(idxVar), "LOAD " + idxVar);
                    emit("push", "\"v\":1", "PUSH 1");
                    emit("add", "", "ADD");
                    emit("store", "\"name\":" + quoteText(idxVar), "STORE " + idxVar);
                    emit("jmp", "\"to\":" + std::to_string(start), "JMP " + std::to_string(start));
                    int loopEnd = (int)code.size();
                    for (int j : breakJumps.back()) patch(j, loopEnd);
                    breakJumps.pop_back();
                    continueJumps.pop_back();
                    patch(exitJump, loopEnd);
                    break;
                }
                string listVar = "__for_list_" + std::to_string(tempCounter);
                string idxVar = "__for_i_" + std::to_string(tempCounter);
                ++tempCounter;
                expr(s->expr);
                emit("store", "\"name\":" + quoteText(listVar), "STORE " + listVar);
                emit("push", "\"v\":0", "PUSH 0");
                emit("store", "\"name\":" + quoteText(idxVar), "STORE " + idxVar);
                int start = (int)code.size();
                emit("load", "\"name\":" + quoteText(idxVar), "LOAD " + idxVar);
                emit("load", "\"name\":" + quoteText(listVar), "LOAD " + listVar);
                emit("call", "\"name\":\"长度\",\"n\":1", "CALL 长度 1");
                emit("lt", "", "LT");
                int exitJump = emit("jz", "\"to\":0", "JZ 0");
                emit("load", "\"name\":" + quoteText(listVar), "LOAD " + listVar);
                emit("load", "\"name\":" + quoteText(idxVar), "LOAD " + idxVar);
                emit("index", "", "INDEX");
                emit("store", "\"name\":" + quoteText(s->name), "STORE " + s->name);
                breakJumps.push_back({});
                continueJumps.push_back({});
                for (const auto& bodyStmt : s->body) stmt(bodyStmt);
                int contTarget = (int)code.size();
                for (int j : continueJumps.back()) patch(j, contTarget);
                emit("load", "\"name\":" + quoteText(idxVar), "LOAD " + idxVar);
                emit("push", "\"v\":1", "PUSH 1");
                emit("add", "", "ADD");
                emit("store", "\"name\":" + quoteText(idxVar), "STORE " + idxVar);
                emit("jmp", "\"to\":" + std::to_string(start), "JMP " + std::to_string(start));
                int loopEnd = (int)code.size();
                for (int j : breakJumps.back()) patch(j, loopEnd);
                breakJumps.pop_back();
                continueJumps.pop_back();
                patch(exitJump, loopEnd);
                break;
            }
            case Stmt::K::Try:
                diag(s->line, "字节码/汇编暂不支持尝试/捕获");
                break;
            case Stmt::K::Match:
                diag(s->line, "字节码/汇编暂不支持匹配");
                break;
            case Stmt::K::Import:
                diag(s->line, "「依赖」不翻译");
                break;
            case Stmt::K::Export:
                break;
            case Stmt::K::Return:
                if (!inFunction) { diag(s->line, "「返回」只能写在函数里"); break; }
                if (s->expr) expr(s->expr);
                else emit("push", "\"v\":null", "PUSH null");
                emit("ret", "", "RET");
                break;
        }
    }
    string bytecode() {
        for (const auto& s : program) stmt(s);
        emit("halt", "", "HALT");
        std::ostringstream o;
        o << "{\"target\":\"bytecode\",\"code\":[";
        for (size_t i = 0; i < code.size(); ++i) {
            if (i) o << ",";
            o << "{\"op\":" << quoteText(code[i].op);
            if (!code[i].jsonArg.empty()) o << "," << code[i].jsonArg;
            if (code[i].target >= 0) o << ",\"to\":" << code[i].target;
            o << "}";
        }
        o << "],\"functions\":{";
        bool firstFn = true;
        for (const auto& kv : funcs) {
            if (!firstFn) o << ",";
            firstFn = false;
            o << quoteText(kv.first) << ":{\"params\":[";
            for (size_t j = 0; j < kv.second.params.size(); ++j) {
                if (j) o << ",";
                o << quoteText(kv.second.params[j]);
            }
            o << "],\"code\":[";
            for (size_t j = 0; j < kv.second.code.size(); ++j) {
                if (j) o << ",";
                const auto& c = kv.second.code[j];
                o << "{\"op\":" << quoteText(c.op);
                if (!c.jsonArg.empty()) o << "," << c.jsonArg;
                if (c.target >= 0) o << ",\"to\":" << c.target;
                o << "}";
            }
            o << "]}";
        }
        o << "}}";
        return o.str();
    }
    string assembly() {
        for (const auto& s : program) stmt(s);
        emit("halt", "", "HALT");
        std::ostringstream o;
        o << "; 翻译目标：汇编（自定义栈指令）\n";
        for (size_t i = 0; i < code.size(); ++i) {
            o << "L" << i << ":\n";
            const auto& c = code[i];
            if (c.op == "jz") o << "  JZ L" << c.target << "\n";
            else if (c.op == "jmp") o << "  JMP L" << c.target << "\n";
            else if (!c.asmArg.empty()) o << "  " << c.asmArg << "\n";
            else o << "  " << c.op << "\n";
        }
        return o.str();
    }
};

static string translateByTarget(const string& target, const vector<StmtPtr>& program,
                                vector<string>& diags) {
    if (target == "字节码") {
        StackEmitter em(program);
        string s = em.bytecode();
        for (const auto& d : em.diags) diags.push_back(d);
        return s;
    }
    if (target == "汇编") {
        StackEmitter em(program);
        string s = em.assembly();
        for (const auto& d : em.diags) diags.push_back(d);
        return s;
    }
    if (target == "C++") return translateToCppSource(program, diags);
    diags.push_back("第 1 行：未知翻译目标「" + target + "」");
    return "";
}

static vector<string> disassembleBytecode(const string& path, int line);
static Value verifyBinary(const string& path, int line);
static Value verifyPlugin(const string& path, int line);
static vector<string> binaryStrings(const string& bytes, size_t minLen, size_t limit,
                                    const string& filter, int line);
static Value binaryHeader(const string& path, int line);
static Value binaryStringsValue(const string& path, int line, size_t minLen, size_t limit,
                                const string& filter);
static std::pair<int, string> runCapture(const string& cmd) {
    FILE* p = _popen((cmd + " 2>&1").c_str(), "r");
    if (!p) return {-1, "无法启动命令"};
    string out;
    char buf[4096];
    while (std::fgets(buf, sizeof(buf), p)) out += buf;
    int rc = _pclose(p);
    return {rc, out};
}

static vector<Value> parseExternalErrors(const string& lang, const string& out,
                                         const string& code, int line, int exitCode) {
    vector<Value> result;
    auto srcLines = splitLines(code);
    std::set<string> seen;
    auto add = [&](int ln, int col, const string& reason, const string& raw) {
        if ((int)result.size() >= 40) return;
        string key = std::to_string(ln) + ":" + std::to_string(col) + ":" + reason;
        if (!seen.insert(key).second) return;
        auto d = std::make_shared<Dict>();
        d->items["文件"] = vStr("<代码>");
        d->items["行"] = vNum(ln);
        d->items["列"] = vNum(col);
        d->items["级别"] = vStr(reason.find("warning") != string::npos ? "警告" : "错误");
        d->items["原因"] = vStr(reason);
        string loc = ln > 0 ? ("第 " + std::to_string(ln) + " 行") : "代码";
        if (col > 0) loc += " 第 " + std::to_string(col) + " 列";
        d->items["说明"] = vStr("在" + loc + "发现 " + lang + " 错误：" + reason);
        if (!raw.empty()) d->items["原始"] = vStr(raw);
        if (ln >= 1 && (size_t)ln <= srcLines.size())
            d->items["源码"] = vStr(srcLines[(size_t)ln - 1]);
        result.push_back(vDict(d));
    };
    auto lines = splitLines(out);
    std::regex generic(R"(((?:[A-Za-z]:)?[^:\r\n]+):(\d+):(?:(\d+):)?\s*(?:error|warning|fatal error|note)?:?\s*(.+))");
    for (size_t i = 0; i < lines.size(); ++i) {
        std::smatch m;
        if (std::regex_search(lines[i], m, generic)) {
            int ln = std::atoi(m[2].str().c_str());
            int col = m[3].matched ? std::atoi(m[3].str().c_str()) : 0;
            string reason = m[4].str();
            if (reason.rfind("error:", 0) == 0) reason = reason.substr(6);
            else if (reason.rfind("warning:", 0) == 0) reason = reason.substr(8);
            add(ln, col, reason, lines[i]);
        }
    }
    if (result.empty()) {
        std::regex py(R"(File ".*?", line (\d+))");
        std::regex pyErr(R"((\w*Error):\s*(.*))");
        int ln = 0, col = 0;
        string reason;
        for (size_t i = 0; i < lines.size(); ++i) {
            std::smatch m;
            if (ln == 0 && std::regex_search(lines[i], m, py)) ln = std::atoi(m[1].str().c_str());
            if (reason.empty() && std::regex_search(lines[i], m, pyErr))
                reason = m[1].str() + ": " + m[2].str();
            if (ln > 0 && i > 0 && !lines[i - 1].empty()) {
                auto caret = lines[i].find('^');
                if (caret != string::npos) col = (int)caret + 1;
            }
        }
        if (ln > 0 || !reason.empty()) add(ln, col, reason.empty() ? "语法错误" : reason, "");
    }
    if (result.empty() && exitCode != 0) {
        string first;
        for (const auto& s : lines) {
            if (!s.empty()) { first = s; break; }
        }
        bool missing = first.find("not recognized") != string::npos ||
                       first.find("不是内部或外部命令") != string::npos ||
                       first.find("command not found") != string::npos;
        add(0, 0, missing ? "解析器不可用：" + first : (first.empty() ? "解析失败" : first), first);
    }
    return result;
}
static vector<std::pair<int, string>> compatTargetLines(const string& src) {
    vector<std::pair<int, string>> out;
    int n = 0;
    for (const auto& raw : splitLines(src)) {
        ++n;
        size_t b = raw.find_first_not_of(" \t");
        if (b == string::npos) continue;
        string s = raw.substr(b);
        if (s.rfind("# 翻译:", 0) == 0) out.push_back({n, "翻译:" + s.substr(6)});
        else if (s.rfind("# 外派:", 0) == 0) out.push_back({n, "外派:" + s.substr(6)});
    }
    return out;
}
static vector<string> compatUserFuncCollisions(const string& src) {
    vector<string> out;
    for (const auto& raw : splitLines(src)) {
        size_t b = raw.find_first_not_of(" \t");
        if (b == string::npos) continue;
        string s = raw.substr(b);
        if (s.rfind("函数 ", 0) != 0) continue;
        std::istringstream ss(s.substr(6));
        string name;
        if (!(ss >> name)) continue;
        if (functionModules().count(name)) out.push_back(name);
    }
    return out;
}
static Value compatParse(const string& lang0, const string& code, int line) {
    string lang = lowerAscii(lang0);
    if (lang == "json") {
        try {
            JsonReader reader(code, line);
            reader.parse();
            auto d = std::make_shared<Dict>();
            d->items["语言"] = vStr("json");
            d->items["ok"] = vBool(true);
            d->items["退出码"] = vNum(0);
            d->items["输出"] = vStr("");
            return vDict(d);
        } catch (WenError& e) {
            auto d = std::make_shared<Dict>();
            d->items["语言"] = vStr("json");
            d->items["ok"] = vBool(false);
            d->items["退出码"] = vNum(1);
            d->items["输出"] = vStr(e.what());
            return vDict(d);
        }
    }
    string ext, cmd;
    if (lang == "python") { ext = ".py"; cmd = "python -m py_compile"; }
    else if (lang == "javascript" || lang == "js") { ext = ".js"; cmd = "node --check"; }
    else if (lang == "typescript" || lang == "ts") { ext = ".js"; cmd = "node --check"; }
    else if (lang == "java") { ext = ".java"; cmd = "javac -d"; }
    else if (lang == "c") { ext = ".c"; cmd = "gcc -fsyntax-only"; }
    else if (lang == "cpp" || lang == "c++") { ext = ".cpp"; cmd = "g++ -fsyntax-only"; }
    else if (lang == "lua") { ext = ".lua"; cmd = "luac -p"; }
    else if (lang == "ruby") { ext = ".rb"; cmd = "ruby -c"; }
    else if (lang == "php") { ext = ".php"; cmd = "php -l"; }
    else if (lang == "bash" || lang == "shell") { ext = ".sh"; cmd = "bash -n"; }
    else if (lang == "rust") { ext = ".rs"; cmd = "rustc --emit=metadata --crate-type lib"; }
    else if (lang == "go") { ext = ".go"; cmd = "gofmt -e"; }
    else throw WenError("运行时错误", line, 0, "不支持的解析语言：" + lang0);
    auto stamp = std::chrono::steady_clock::now().time_since_epoch().count();
    fs::path tmp = fs::temp_directory_path() /
                   fs::u8path("wen_parse_" + std::to_string((long long)stamp) + ext);
    try {
        writeWholeFile(tmp.u8string(), code, false);
        string full;
        if (lang == "java") {
            fs::path dir = tmp.parent_path();
            full = cmd + " \"" + dir.u8string() + "\" \"" + tmp.u8string() + "\"";
        } else {
            full = cmd + " \"" + tmp.u8string() + "\"";
        }
        auto [rc, out] = runCapture(full);
        auto d = std::make_shared<Dict>();
        d->items["语言"] = vStr(lang);
        d->items["ok"] = vBool(rc == 0);
        d->items["退出码"] = vNum((double)rc);
        d->items["输出"] = vStr(out);
        auto diagList = std::make_shared<List>();
        for (const auto& dv : parseExternalErrors(lang, out, code, line, rc))
            diagList->items.push_back(dv);
        d->items["诊断"] = vList(diagList);
        std::error_code ec;
        fs::remove(tmp, ec);
        return vDict(d);
    } catch (...) {
        std::error_code ec;
        fs::remove(tmp, ec);
        throw;
    }
}
static double nnAct(double x, const string& act) {
    if (act == "tanh") return wenTanh(x);
    if (act == "relu") return x > 0 ? x : 0;
    if (act == "linear") return x;
    return 1.0 / (1.0 + wenExp(-x));
}
static double nnActDeriv(double z, double y, const string& act) {
    if (act == "tanh") return 1 - y * y;
    if (act == "relu") return z > 0 ? 1 : 0;
    if (act == "linear") return 1;
    return y * (1 - y);
}
static Value nnLayer(int in, int out, string act, int line) {
    if (in <= 0 || out <= 0 || in > 4096 || out > 4096)
        throw WenError("运行时错误", line, 0, "神经层尺寸必须在 1..4096");
    if (act.empty()) act = "sigmoid";
    std::mt19937 rng(std::random_device{}());
    double limit = wenSqrt(6.0 / (in + out));
    std::uniform_real_distribution<double> dist(-limit, limit);
    auto weights = std::make_shared<List>();
    for (int j = 0; j < out; ++j) {
        auto row = std::make_shared<List>();
        for (int i = 0; i < in; ++i) row->items.push_back(vNum(dist(rng)));
        weights->items.push_back(vList(row));
    }
    auto bias = std::make_shared<List>();
    for (int j = 0; j < out; ++j) bias->items.push_back(vNum(0));
    auto d = std::make_shared<Dict>();
    d->items["输入"] = vNum(in);
    d->items["输出"] = vNum(out);
    d->items["激活"] = vStr(act);
    d->items["权重"] = vList(weights);
    d->items["偏置"] = vList(bias);
    return vDict(d);
}
static std::vector<double> nnInput(const Value& v, int line) {
    auto l = needList(v, "神经网络输入", line);
    std::vector<double> x;
    for (const auto& e : l->items) x.push_back(needNum(e, "神经网络输入", line));
    return x;
}
static std::vector<Value> nnLayers(const Value& net, int line) {
    auto d = needDict(net, "神经网络", line);
    auto it = d->items.find("层");
    if (it == d->items.end()) throw WenError("运行时错误", line, 0, "不是神经链");
    auto l = needList(it->second, "神经链", line);
    return l->items;
}
static std::vector<double> nnForward(const Value& net, const std::vector<double>& input,
                                     int line) {
    auto layers = nnLayers(net, line);
    std::vector<double> cur = input;
    for (const auto& lv : layers) {
        auto layer = needDict(lv, "神经层", line);
        int in = (int)needNum(layer->items.at("输入"), "输入", line);
        int out = (int)needNum(layer->items.at("输出"), "输出", line);
        if ((int)cur.size() != in)
            throw WenError("运行时错误", line, 0, "神经层输入尺寸不匹配");
        auto weights = needList(layer->items.at("权重"), "权重", line);
        auto bias = needList(layer->items.at("偏置"), "偏置", line);
        string act = needStr(layer->items.at("激活"), "激活", line);
        std::vector<double> next((size_t)out);
        for (int j = 0; j < out; ++j) {
            auto row = needList(weights->items[(size_t)j], "权重行", line);
            double s = needNum(bias->items[(size_t)j], "偏置", line);
            for (int i = 0; i < in; ++i)
                s += needNum(row->items[(size_t)i], "权重", line) * cur[(size_t)i];
            next[(size_t)j] = nnAct(s, act);
        }
        cur = std::move(next);
    }
    return cur;
}
static Value nnTrain(const Value& net, const std::vector<double>& input,
                     const std::vector<double>& target, double lr, int line) {
    auto layers = nnLayers(net, line);
    std::vector<std::vector<double>> cur(1, input);
    std::vector<std::vector<double>> zs;
    for (const auto& lv : layers) {
        auto layer = needDict(lv, "神经层", line);
        int in = (int)needNum(layer->items.at("输入"), "输入", line);
        int out = (int)needNum(layer->items.at("输出"), "输出", line);
        auto weights = needList(layer->items.at("权重"), "权重", line);
        auto bias = needList(layer->items.at("偏置"), "偏置", line);
        string act = needStr(layer->items.at("激活"), "激活", line);
        std::vector<double> z((size_t)out), y((size_t)out);
        for (int j = 0; j < out; ++j) {
            auto row = needList(weights->items[(size_t)j], "权重行", line);
            double s = needNum(bias->items[(size_t)j], "偏置", line);
            for (int i = 0; i < in; ++i)
                s += needNum(row->items[(size_t)i], "权重", line) * cur.back()[(size_t)i];
            z[(size_t)j] = s;
            y[(size_t)j] = nnAct(s, act);
        }
        zs.push_back(z);
        cur.push_back(y);
    }
    if ((int)cur.back().size() != (int)target.size())
        throw WenError("运行时错误", line, 0, "训练目标尺寸不匹配");
    std::vector<double> delta(target.size());
    double loss = 0;
    for (size_t j = 0; j < target.size(); ++j) {
        double err = cur.back()[j] - target[j];
        loss += err * err;
        delta[j] = err * nnActDeriv(zs.back()[j], cur.back()[j],
                                    needStr(needDict(layers.back(), "层", line)->items.at("激活"), "激活", line));
    }
    loss /= (double)target.size();
    for (int li = (int)layers.size() - 1; li >= 0; --li) {
        auto layer = needDict(layers[(size_t)li], "神经层", line);
        int in = (int)needNum(layer->items.at("输入"), "输入", line);
        auto weights = needList(layer->items.at("权重"), "权重", line);
        auto bias = needList(layer->items.at("偏置"), "偏置", line);
        std::vector<double> prev((size_t)in, 0);
        for (int j = 0; j < (int)delta.size(); ++j) {
            auto row = needList(weights->items[(size_t)j], "权重行", line);
            for (int i = 0; i < in; ++i) {
                double w = needNum(row->items[(size_t)i], "权重", line);
                prev[(size_t)i] += w * delta[(size_t)j];
                row->items[(size_t)i] = vNum(w - lr * delta[(size_t)j] * cur[(size_t)li][(size_t)i]);
            }
            bias->items[(size_t)j] = vNum(needNum(bias->items[(size_t)j], "偏置", line) - lr * delta[(size_t)j]);
        }
        if (li > 0) {
            string act = needStr(needDict(layers[(size_t)(li - 1)], "层", line)->items.at("激活"), "激活", line);
            for (int i = 0; i < in; ++i)
                prev[(size_t)i] *= nnActDeriv(zs[(size_t)(li - 1)][(size_t)i],
                                              cur[(size_t)li][(size_t)i], act);
            delta = prev;
        }
    }
    return vNum(loss);
}

static string netHostOf(const string& url) {
    size_t p = url.find("://");
    size_t b = p == string::npos ? 0 : p + 3;
    size_t e = url.find_first_of("/:?#", b);
    string host = url.substr(b, e == string::npos ? string::npos : e - b);
    for (auto& c : host) c = (char)std::tolower((unsigned char)c);
    return host;
}
static bool netWildcard(const string& pat, const string& text) {
    size_t p = 0, t = 0, star = string::npos, mark = 0;
    while (t < text.size()) {
        if (p < pat.size() && (pat[p] == '?' || pat[p] == text[t])) { ++p; ++t; }
        else if (p < pat.size() && pat[p] == '*') { star = p++; mark = t; }
        else if (star != string::npos) { p = star + 1; t = ++mark; }
        else return false;
    }
    while (p < pat.size() && pat[p] == '*') ++p;
    return p == pat.size();
}
static bool netProtocolOk(const string& url) {
    if (gNetProtocol.empty()) return true;
    return url.rfind(gNetProtocol + "://", 0) == 0;
}
static bool netWhitelisted(const string& url) {
    if (!gSandbox && gNetWhitelist.empty()) return true;
    if (gNetWhitelist.empty()) return false;
    string host = netHostOf(url);
    for (const auto& w : gNetWhitelist)
        if (netWildcard(w, host)) return true;
    return false;
}
static bool netAllowed(const std::vector<std::pair<string, bool>>& rules, const string& url) {
    if (rules.empty()) return true;
    string host = netHostOf(url);
    for (const auto& r : rules)
        if (netWildcard(r.first, host)) return r.second;
    return false;
}
static string int128ToString(WenI128 x) {
    if (x == 0) return "0";
    bool neg = x < 0;
    WenU128 u = neg ? (WenU128)(-x) : (WenU128)x;
    string s;
    while (u) { s.push_back(char('0' + (int)(u % 10))); u /= 10; }
    if (neg) s.push_back('-');
    std::reverse(s.begin(), s.end());
    return s;
}
static vector<uint32_t> bigParse(string s) {
    size_t b = 0;
    while (b < s.size() && std::isspace((unsigned char)s[b])) ++b;
    while (s.size() > b && std::isspace((unsigned char)s.back())) s.pop_back();
    if (b >= s.size()) return {0};
    vector<uint32_t> out;
    for (int i = (int)s.size(); i > (int)b; i -= 9) {
        int st = std::max((int)b, i - 9);
        uint32_t v = 0;
        for (int j = st; j < i; ++j) {
            if (!std::isdigit((unsigned char)s[j]))
                throw WenError("运行时错误", 0, 0, "大整数只接受十进制数字");
            v = v * 10 + (uint32_t)(s[j] - '0');
        }
        out.push_back(v);
    }
    return out;
}
static string bigStr(const vector<uint32_t>& a) {
    if (a.empty()) return "0";
    string out;
    out.reserve(a.size() * 9 + 1);
    out += std::to_string(a.back());
    char buf[16];
    for (int i = (int)a.size() - 2; i >= 0; --i) {
        std::snprintf(buf, sizeof(buf), "%09u", a[(size_t)i]);
        out += buf;
    }
    return out;
}
static void bigTrim(vector<uint32_t>& a) {
    while (a.size() > 1 && a.back() == 0) a.pop_back();
}
static vector<uint32_t> bigMulSchool(const vector<uint32_t>& a, const vector<uint32_t>& b) {
    vector<uint32_t> c(a.size() + b.size(), 0);
    for (size_t i = 0; i < a.size(); ++i) {
        uint64_t carry = 0;
        for (size_t j = 0; j < b.size(); ++j) {
            uint64_t cur = (uint64_t)c[i + j] + (uint64_t)a[i] * b[j] + carry;
            c[i + j] = (uint32_t)(cur % 1000000000ULL);
            carry = cur / 1000000000ULL;
        }
        size_t k = i + b.size();
        while (carry) {
            uint64_t cur = (uint64_t)c[k] + carry;
            c[k] = (uint32_t)(cur % 1000000000ULL);
            carry = cur / 1000000000ULL;
            ++k;
        }
    }
    bigTrim(c);
    return c;
}
static vector<uint32_t> bigAdd(const vector<uint32_t>& a, const vector<uint32_t>& b) {
    vector<uint32_t> c(std::max(a.size(), b.size()) + 1, 0);
    uint64_t carry = 0;
    for (size_t i = 0; i < c.size(); ++i) {
        uint64_t cur = carry;
        if (i < a.size()) cur += a[i];
        if (i < b.size()) cur += b[i];
        c[i] = (uint32_t)(cur % 1000000000ULL);
        carry = cur / 1000000000ULL;
    }
    bigTrim(c);
    return c;
}
static vector<uint32_t> bigSub(const vector<uint32_t>& a, const vector<uint32_t>& b) {
    vector<uint32_t> c = a;
    int64_t borrow = 0;
    for (size_t i = 0; i < c.size(); ++i) {
        int64_t cur = (int64_t)c[i] - borrow - (i < b.size() ? b[i] : 0);
        if (cur < 0) { cur += 1000000000LL; borrow = 1; } else borrow = 0;
        c[i] = (uint32_t)cur;
    }
    bigTrim(c);
    return c;
}
static vector<uint32_t> bigDivSmall(vector<uint32_t> a, uint32_t d) {
    uint64_t rem = 0;
    for (int i = (int)a.size() - 1; i >= 0; --i) {
        uint64_t cur = rem * 1000000000ULL + a[(size_t)i];
        a[(size_t)i] = (uint32_t)(cur / d);
        rem = cur % d;
    }
    bigTrim(a);
    return a;
}
static vector<uint32_t> bigFromU64(uint64_t v) {
    vector<uint32_t> out;
    if (!v) return {0};
    while (v) { out.push_back((uint32_t)(v % 1000000000ULL)); v /= 1000000000ULL; }
    return out;
}
static void bigAddShift(vector<uint32_t>& c, const vector<uint32_t>& a, size_t shift) {
    if (c.size() < shift + a.size() + 1) c.resize(shift + a.size() + 1, 0);
    uint64_t carry = 0;
    size_t i = 0;
    for (; i < a.size() || carry; ++i) {
        uint64_t cur = (uint64_t)c[shift + i] + (i < a.size() ? a[i] : 0) + carry;
        c[shift + i] = (uint32_t)(cur % 1000000000ULL);
        carry = cur / 1000000000ULL;
    }
    bigTrim(c);
}
static uint64_t nttPow(uint64_t a, uint64_t e, uint64_t mod) {
    uint64_t r = 1;
    while (e) { if (e & 1) r = r * a % mod; a = a * a % mod; e >>= 1; }
    return r;
}
static void ntt(vector<int>& a, bool inv, int mod, int root) {
    int n = (int)a.size();
    for (int i = 1, j = 0; i < n; ++i) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) std::swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        uint64_t wlen = nttPow(root, (uint64_t)(mod - 1) / len, mod);
        if (inv) wlen = nttPow(wlen, mod - 2, mod);
        for (int i = 0; i < n; i += len) {
            uint64_t w = 1;
            int half = len >> 1;
            for (int j = 0; j < half; ++j) {
                int u = a[i + j];
                int v = (int)((uint64_t)a[i + j + half] * w % mod);
                int x = u + v; if (x >= mod) x -= mod;
                int y = u - v; if (y < 0) y += mod;
                a[i + j] = x;
                a[i + j + half] = y;
                w = w * wlen % mod;
            }
        }
    }
    if (inv) {
        uint64_t invn = nttPow(n, mod - 2, mod);
        for (int& x : a) x = (int)((uint64_t)x * invn % mod);
    }
}
#if defined(__SIZEOF_INT128__)
static vector<uint32_t> bigMulNTT(const vector<uint32_t>& a, const vector<uint32_t>& b) {
    static const int MODS[3] = {998244353, 1004535809, 469762049};
    static const int ROOT = 3;
    size_t need = a.size() + b.size();
    size_t n = 1;
    while (n < need) n <<= 1;
    vector<vector<int>> conv(3, vector<int>(n));
    for (int k = 0; k < 3; ++k) {
        vector<int> fa(n), fb(n);
        for (size_t i = 0; i < a.size(); ++i) fa[i] = (int)(a[i] % MODS[k]);
        for (size_t i = 0; i < b.size(); ++i) fb[i] = (int)(b[i] % MODS[k]);
        ntt(fa, false, MODS[k], ROOT);
        ntt(fb, false, MODS[k], ROOT);
        for (size_t i = 0; i < n; ++i) fa[i] = (int)((uint64_t)fa[i] * fb[i] % MODS[k]);
        ntt(fa, true, MODS[k], ROOT);
        conv[k] = std::move(fa);
    }
    uint64_t inv12 = nttPow(MODS[0], MODS[1] - 2, MODS[1]);
    uint64_t p12 = (uint64_t)MODS[0] * MODS[1];
    uint64_t inv123 = nttPow(p12 % MODS[2], MODS[2] - 2, MODS[2]);
    vector<unsigned __int128> coeff(need);
    for (size_t i = 0; i < need; ++i) {
        uint64_t r1 = (uint64_t)conv[0][i];
        uint64_t r2 = (uint64_t)conv[1][i];
        uint64_t r3 = (uint64_t)conv[2][i];
        uint64_t t1 = (r2 + MODS[1] - r1 % MODS[1]) % MODS[1] * inv12 % MODS[1];
        unsigned __int128 x12 = (unsigned __int128)r1 + (unsigned __int128)MODS[0] * t1;
        uint64_t r3x = (uint64_t)(x12 % MODS[2]);
        uint64_t t2 = (r3 + MODS[2] - r3x) % MODS[2] * inv123 % MODS[2];
        coeff[i] = x12 + (unsigned __int128)p12 * t2;
    }
    vector<uint32_t> out(need + 1, 0);
    unsigned __int128 carry = 0;
    for (size_t i = 0; i < need; ++i) {
        unsigned __int128 cur = coeff[i] + carry;
        out[i] = (uint32_t)(cur % 1000000000ULL);
        carry = cur / 1000000000ULL;
    }
    size_t k = need;
    while (carry) {
        out[k++] = (uint32_t)(carry % 1000000000ULL);
        carry /= 1000000000ULL;
    }
    out.resize(k);
    bigTrim(out);
    return out;
}

#else

template <int MOD>
static uint64_t nttPowT(uint64_t a, uint64_t e) {
    uint64_t r = 1;
    while (e) { if (e & 1) r = r * a % MOD; a = a * a % MOD; e >>= 1; }
    return r;
}
template <int MOD>
static void nttT(vector<int>& a, bool inv) {
    int n = (int)a.size();
    for (int i = 1, j = 0; i < n; ++i) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) std::swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        uint64_t wlen = nttPowT<MOD>(3, (uint64_t)(MOD - 1) / len);
        if (inv) wlen = nttPowT<MOD>(wlen, MOD - 2);
        for (int i = 0; i < n; i += len) {
            uint64_t w = 1;
            int half = len >> 1;
            for (int j = 0; j < half; ++j) {
                int u = a[i + j];
                int v = (int)((uint64_t)a[i + j + half] * w % MOD);
                int x = u + v; if (x >= MOD) x -= MOD;
                int y = u - v; if (y < 0) y += MOD;
                a[i + j] = x; a[i + j + half] = y;
                w = w * wlen % MOD;
            }
        }
    }
    if (inv) {
        uint64_t invn = nttPowT<MOD>(n, MOD - 2);
        for (int& x : a) x = (int)((uint64_t)x * invn % MOD);
    }
}
static vector<uint32_t> bigMulNTT32(const vector<uint32_t>& a, const vector<uint32_t>& b) {
    auto to3 = [](const vector<uint32_t>& x) {
        vector<uint32_t> o;
        for (uint32_t v0 : x) {
            uint32_t v = v0;
            for (int j = 0; j < 3; ++j) { o.push_back(v % 1000); v /= 1000; }
        }
        bigTrim(o);
        return o;
    };
    auto x = to3(a), y = to3(b);
    size_t need = x.size() + y.size();
    size_t n = 1;
    while (n < need) n <<= 1;
    static const int MODS[2] = {998244353, 1004535809};
    vector<vector<int>> conv(2, vector<int>(n));
    {
        vector<int> fa(n), fb(n);
        for (size_t i = 0; i < x.size(); ++i) fa[i] = (int)x[i];
        for (size_t i = 0; i < y.size(); ++i) fb[i] = (int)y[i];
        ntt(fa, false, 998244353, 3); ntt(fb, false, 998244353, 3);
        for (size_t i = 0; i < n; ++i) fa[i] = (int)((uint64_t)fa[i] * fb[i] % 998244353);
        ntt(fa, true, 998244353, 3); conv[0] = std::move(fa);
    }
    {
        vector<int> fa(n), fb(n);
        for (size_t i = 0; i < x.size(); ++i) fa[i] = (int)x[i];
        for (size_t i = 0; i < y.size(); ++i) fb[i] = (int)y[i];
        ntt(fa, false, 1004535809, 3); ntt(fb, false, 1004535809, 3);
        for (size_t i = 0; i < n; ++i) fa[i] = (int)((uint64_t)fa[i] * fb[i] % 1004535809);
        ntt(fa, true, 1004535809, 3); conv[1] = std::move(fa);
    }
    uint64_t inv = nttPow(998244353, 1004535809 - 2, 1004535809);
    vector<uint64_t> c(need);
    for (size_t i = 0; i < need; ++i) {
        uint64_t r1 = (uint64_t)conv[0][i];
        uint64_t r2 = (uint64_t)conv[1][i];
        uint64_t t = (r2 + MODS[1] - r1 % MODS[1]) % MODS[1] * inv % MODS[1];
        c[i] = r1 + (uint64_t)MODS[0] * t;
    }
    vector<uint32_t> out;
    uint64_t carry = 0;
    for (size_t i = 0; i < need; ++i) {
        uint64_t cur = c[i] + carry;
        out.push_back((uint32_t)(cur % 1000));
        carry = cur / 1000;
    }
    while (carry) { out.push_back((uint32_t)(carry % 1000)); carry /= 1000; }
    vector<uint32_t> res;
    uint32_t limb = 0, mul = 1;
    int cnt = 0;
    for (uint32_t d : out) {
        limb += d * mul;
        mul *= 1000;
        if (++cnt == 3) { res.push_back(limb); limb = 0; mul = 1; cnt = 0; }
    }
    if (cnt) res.push_back(limb);
    bigTrim(res);
    return res;
}
#endif
static vector<uint32_t> bigMul(const vector<uint32_t>& a, const vector<uint32_t>& b) {
#if defined(__SIZEOF_INT128__)
    if (std::min(a.size(), b.size()) >= 1024) return bigMulNTT(a, b);
#else
    if (std::min(a.size(), b.size()) >= 512) return bigMulNTT32(a, b);
#endif
    if (a.empty() || b.empty()) return {0};
    if (std::min(a.size(), b.size()) <= 128) return bigMulSchool(a, b);
    size_t n = std::max(a.size(), b.size()) / 2;
    vector<uint32_t> a0(a.begin(), a.begin() + std::min(n, a.size()));
    vector<uint32_t> a1(a.size() > n ? a.begin() + n : a.end(), a.end());
    vector<uint32_t> b0(b.begin(), b.begin() + std::min(n, b.size()));
    vector<uint32_t> b1(b.size() > n ? b.begin() + n : b.end(), b.end());
    bigTrim(a0); bigTrim(a1); bigTrim(b0); bigTrim(b1);
    auto z0 = bigMul(a0, b0);
    auto z2 = bigMul(a1, b1);
    auto z1 = bigMul(bigAdd(a0, a1), bigAdd(b0, b1));
    z1 = bigSub(z1, z0);
    z1 = bigSub(z1, z2);
    auto out = z0;
    bigAddShift(out, z1, n);
    bigAddShift(out, z2, 2 * n);
    bigTrim(out);
    return out;
}
static vector<uint32_t> bigPow(vector<uint32_t> base, long long exp);
static vector<uint32_t> bigFromU64(uint64_t v);
static vector<uint32_t> bigProductList(const std::vector<vector<uint32_t>>& xs, size_t l, size_t r) {
    if (l >= r) return {1};
    if (r - l == 1) return xs[l];
    size_t m = l + (r - l) / 2;
    return bigMul(bigProductList(xs, l, m), bigProductList(xs, m, r));
}
static vector<uint32_t> bigFactorialPrime(uint32_t n) {
    vector<char> comp(n + 1, 0);
    std::vector<vector<uint32_t>> factors;
    for (uint32_t p = 2; p <= n; ++p) {
        if (comp[p]) continue;
        for (uint64_t q = (uint64_t)p * p; q <= n; q += p) comp[(size_t)q] = 1;
        long long e = 0;
        for (uint64_t q = p; q <= n; q *= p) e += n / q;
        factors.push_back(bigPow(bigFromU64(p), e));
    }
    return bigProductList(factors, 0, factors.size());
}
static vector<uint32_t> bigProductRange(uint32_t l, uint32_t r, int depth = 0) {
    if (l > r) return {1};
    if (l == r) return bigFromU64(l);
    uint32_t m = l + (r - l) / 2;
    if (depth < 2 && r - l >= 20000 && std::thread::hardware_concurrency() > 1) {
        auto left = std::async(std::launch::async, [l, m, depth] {
            return bigProductRange(l, m, depth + 1);
        });
        auto right = bigProductRange(m + 1, r, depth + 1);
        return bigMul(left.get(), right);
    }
    return bigMul(bigProductRange(l, m, depth + 1), bigProductRange(m + 1, r, depth + 1));
}
static vector<uint32_t> bigPow(vector<uint32_t> base, long long exp) {
    vector<uint32_t> out{1};
    while (exp > 0) {
        if (exp & 1) out = bigMul(out, base);
        exp >>= 1;
        if (exp) base = bigMul(base, base);
    }
    return out;
}
static vector<uint32_t> bigAtanInv(uint32_t x, const vector<uint32_t>& scale) {
    auto p = bigDivSmall(scale, x);
    vector<uint32_t> sum{0};
    uint32_t x2 = x * x;
    int k = 0;
    bool plus = true;
    while (!(p.size() == 1 && p[0] == 0)) {
        auto term = bigDivSmall(p, (uint32_t)(2 * k + 1));
        sum = plus ? bigAdd(sum, term) : bigSub(sum, term);
        p = bigDivSmall(p, x2);
        ++k;
        plus = !plus;
    }
    return sum;
}
static string piText(int digits) {
    int guard = 12;
    auto scale = bigPow(bigFromU64(10), digits + guard);
    auto a = bigMul(bigAtanInv(5, scale), bigFromU64(16));
    auto b = bigMul(bigAtanInv(239, scale), bigFromU64(4));
    string s = bigStr(bigSub(a, b));
    size_t need = (size_t)digits + 1;
    if (s.size() < need) s.append(need - s.size(), '0');
    return s.substr(0, 1) + "." + s.substr(1, digits);
}
static double piValue() {
    static const double v = std::stod(piText(40));
    return v;
}
static double wenSqrt(double x) {
    if (x <= 0) return 0;
    long double r = x > 1 ? (long double)x : 1.0L;
    for (int i = 0; i < 80; ++i) r = 0.5L * (r + (long double)x / r);
    return (double)r;
}
static double wenAtanh(double z) {
    double z2 = z * z, term = z, sum = 0;
    for (int n = 0; n < 80; ++n) {
        sum += term / (2 * n + 1);
        term *= z2;
    }
    return 2 * sum;
}
static double wenLn2() {
    static const double v = wenAtanh(1.0 / 3.0);
    return v;
}
static double wenE() {
    static const double v = [] {
        double sum = 1, term = 1;
        for (int n = 1; n < 40; ++n) { term /= n; sum += term; }
        return sum;
    }();
    return v;
}
static double wenExp(double x) {
    if (x > 700) return std::numeric_limits<double>::infinity();
    if (x < -700) return 0;
    double k = std::floor(x);
    double r = x - k;
    double sum = 1, term = 1;
    for (int n = 1; n < 40; ++n) { term *= r / n; sum += term; }
    double e = wenE();
    for (int i = 0; i < (int)k; ++i) sum *= e;
    for (int i = 0; i < (int)(-k); ++i) sum /= e;
    return sum;
}
static double wenLog(double x) {
    if (x <= 0) return -std::numeric_limits<double>::infinity();
    int k = 0;
    while (x >= 2) { x /= 2; ++k; }
    while (x < 1) { x *= 2; --k; }
    return k * wenLn2() + wenAtanh((x - 1) / (x + 1));
}
static double wenAtan(double x) {
    if (std::fabs(x) > 1) {
        double s = x > 0 ? 1 : -1;
        return s * piValue() / 2 - wenAtan(1 / x);
    }
    int k = 0;
    while (std::fabs(x) > 0.2) {
        x = x / (1 + wenSqrt(1 + x * x));
        ++k;
    }
    double x2 = x * x, term = x, sum = 0;
    for (int n = 0; n < 60; ++n) {
        sum += term / (2 * n + 1);
        term *= -x2;
    }
    for (int i = 0; i < k; ++i) sum *= 2;
    return sum;
}
static double wenAsin(double x) {
    if (x <= -1) return -piValue() / 2;
    if (x >= 1) return piValue() / 2;
    return wenAtan(x / wenSqrt(1 - x * x));
}
static double wenAcos(double x) { return piValue() / 2 - wenAsin(x); }
static double wenPow(double x, double y) {
    double yi = std::floor(y);
    if (yi == y && std::fabs(y) < 1e9) {
        long long n = (long long)y;
        bool neg = n < 0;
        if (neg) n = -n;
        double r = 1, b = x;
        while (n) {
            if (n & 1) r *= b;
            b *= b;
            n >>= 1;
        }
        return neg ? 1 / r : r;
    }
    if (x < 0) return std::numeric_limits<double>::quiet_NaN();
    if (x == 0) return y > 0 ? 0 : std::numeric_limits<double>::infinity();
    return wenExp(y * wenLog(x));
}
static double wenSinh(double x) { return (wenExp(x) - wenExp(-x)) / 2; }
static double wenCosh(double x) { return (wenExp(x) + wenExp(-x)) / 2; }
static double wenTanh(double x) { double a = wenExp(x), b = wenExp(-x); return (a - b) / (a + b); }
static long double bigDigitEstimate(const vector<uint32_t>& base, long long exp) {
    if (exp <= 0 || base.empty()) return 1;
    long double d = 0;
    for (size_t i = 0; i < base.size(); ++i)
        d += (long double)base[i] * std::pow(1000000000.0L, (long double)i);
    if (d <= 0) return 1;
    return std::floor((long double)exp * std::log10(d)) + 1.0L;
}
static void bigGuard(long double digits, int line = 0) {
    if (digits > (long double)gBigMaxDigits)
        throw WenError("运行时错误", line, 0,
            "大整数结果约 " + std::to_string((long long)digits) +
            " 位，超过上限 " + std::to_string(gBigMaxDigits) + " 位；拒绝分配");
}static string bigArg(const Value& v, int line) {
    if (v.type == VT::Str) return v.str;
    if (v.type == VT::Int) return intText(v);
    if (v.type == VT::Num) return std::to_string((long long)needNum(v, "大整数", line));
    throw WenError("运行时错误", line, 0, "大整数参数需要数字或文本");
}

