        d->items["数量"] = vNum((double)n);
        auto list = std::make_shared<List>();
        for (UINT i=0;i<n;++i) {
            WAVEINCAPSW caps{};
            if (waveInGetDevCapsW(i,&caps,sizeof(caps)) == MMSYSERR_NOERROR)
                list->items.push_back(vStr(wideToUtf8(caps.szPname)));
        }
