        vector<Value> args;
        if (a.size() == 1) { args.push_back(vNum(1)); args.push_back(a[0]); args.push_back(vNum(1)); }
        else if (a.size() == 2) { args.push_back(a[0]); args.push_back(a[1]); args.push_back(vNum(1)); }
        else args = a;
        return callValue(fn, args, line);
