            throw WenError("运行时错误", line, 0, "「质因数分解」只接受大于 1 的整数");
        auto l = std::make_shared<List>();
        for (long long i = 2; i * i <= n; ++i) {
            while (n % i == 0) {
                l->items.push_back(vNum((double)i));
                n /= i;
            }
        }
        if (n > 1) l->items.push_back(vNum((double)n));
        return vList(l);
